/**
 * 文件说明：
 * - 负责把多种历史/运行时数据源配置格式归一化为 data-architecture 标准结构。
 * - 服务于导入导出、执行链、编辑器桥接等多个入口，是配置兼容层的核心门面。
 * - 任何格式分支调整都可能影响旧数据回放与新配置保存，改动前要先确认上下游契约。
 */

import {
  isImportExportFormat,
  isSimpleConfigEditorFormat,
  isStandardDataItem,
  normalizePersistedDataItem,
  normalizePersistedDataSourceType,
  normalizePersistedMergeStrategy,
  normalizePersistedSourceId
} from './DataFormatNormalizerCompatibility'

export interface StandardDataItem {
  item: {
    type: 'static' | 'http' | 'json' | 'websocket' | 'file' | 'data-source-bindings'
    config: Record<string, any>
  }
  processing: {
    filterPath: string
    customScript?: string
    defaultValue?: any
  }
}

export interface StandardDataSourceConfig {
  componentId: string
  dataSources: Array<{
    sourceId: string
    dataItems: StandardDataItem[]
    mergeStrategy: { type: 'object' | 'array' | 'replace' }
  }>
  createdAt: number
  updatedAt: number
}

type StandardDataSource = StandardDataSourceConfig['dataSources'][number]
type StandardProcessing = StandardDataItem['processing']

const DEFAULT_FILTER_PATH = '$'
const DEFAULT_SOURCE_ID = 'main'
const DEFAULT_MERGE_STRATEGY: StandardDataSource['mergeStrategy'] = { type: 'object' }

export class DataFormatNormalizer {
  static normalizeToStandard(data: any, componentId: string): StandardDataSourceConfig {
    if (this.isStandardFormat(data)) {
      return data as StandardDataSourceConfig
    }

    // SimpleConfigurationEditor 是持久化格式标识，不代表运行时组件依赖。
    if (isSimpleConfigEditorFormat(data)) {
      return this.convertFromSimpleConfigEditor(data, componentId)
    }

    if (isImportExportFormat(data)) {
      return this.convertFromImportExport(data, componentId)
    }

    if (this.isCard2ExecutorFormat(data)) {
      return this.convertFromCard2Executor(data, componentId)
    }

    if (this.isEditorManagerFormat(data)) {
      return this.convertFromEditorManager(data, componentId)
    }

    return this.convertFromGenericObject(data, componentId)
  }

  static convertFromStandard(
    standardData: StandardDataSourceConfig,
    targetFormat: 'simpleConfigEditor' | 'importExport' | 'card2Executor'
  ): any {
    switch (targetFormat) {
      case 'simpleConfigEditor':
        return this.convertToSimpleConfigEditor(standardData)
      case 'importExport':
        return this.convertToImportExport(standardData)
      case 'card2Executor':
        return this.convertToCard2Executor(standardData)
      default:
        return standardData
    }
  }

  private static isStandardFormat(data: any): boolean {
    return !!(
      data &&
      typeof data === 'object' &&
      'componentId' in data &&
      'dataSources' in data &&
      Array.isArray(data.dataSources) &&
      data.dataSources.every(
        (ds: any) =>
          ds &&
          'sourceId' in ds &&
          'dataItems' in ds &&
          Array.isArray(ds.dataItems) &&
          ds.dataItems.every((item: any) => isStandardDataItem(item))
      )
    )
  }

  private static isCard2ExecutorFormat(data: any): boolean {
    return !!(
      data &&
      typeof data === 'object' &&
      Object.keys(data).some(
        key =>
          data[key] &&
          typeof data[key] === 'object' &&
          'type' in data[key] &&
          'data' in data[key] &&
          'metadata' in data[key]
      )
    )
  }

  private static isEditorManagerFormat(data: any): boolean {
    return !!(
      data &&
      typeof data === 'object' &&
      'type' in data &&
      'config' in data &&
      !('item' in data && 'processing' in data)
    )
  }

  private static convertFromSimpleConfigEditor(data: any, componentId: string): StandardDataSourceConfig {
    const dataSources = (data.dataSources || []).map((ds: any) =>
      this.createStandardDataSource(
        normalizePersistedSourceId(ds, 'default'),
        (ds.dataItems || []).map((item: any): StandardDataItem => normalizePersistedDataItem(item)),
        normalizePersistedMergeStrategy(ds.mergeStrategy)
      )
    )

    return this.createStandardConfig(componentId, dataSources, data.createdAt)
  }

  private static convertFromImportExport(data: any, componentId: string): StandardDataSourceConfig {
    const dataSourceConfig = data.dataSourceConfig || {}
    // 导入导出格式是单数据源壳结构，这里补成标准 dataSources 数组。
    const dataItems = (dataSourceConfig.dataItems || []).map(
      (rawItem: any): StandardDataItem => normalizePersistedDataItem(rawItem)
    )

    return this.createStandardConfig(componentId, [
      this.createStandardDataSource(
        normalizePersistedSourceId(dataSourceConfig, DEFAULT_SOURCE_ID),
        dataItems,
        normalizePersistedMergeStrategy(dataSourceConfig.mergeStrategy)
      )
    ])
  }

  private static convertFromCard2Executor(data: any, componentId: string): StandardDataSourceConfig {
    const dataSources = Object.entries(data).map(([sourceId, sourceData]: [string, any]) =>
      this.createStandardDataSource(sourceId, [
        this.createStandardItem(sourceData.type || 'static', sourceData.data || sourceData)
      ])
    )

    return this.createStandardConfig(componentId, dataSources)
  }

  private static convertFromEditorManager(data: any, componentId: string): StandardDataSourceConfig {
    return this.createStandardConfig(componentId, [
      this.createStandardDataSource(DEFAULT_SOURCE_ID, [
        this.createStandardItem(data.type || 'static', data.config || data, {
          filterPath: data.filterPath || DEFAULT_FILTER_PATH,
          customScript: data.processScript
        })
      ])
    ])
  }

  private static convertFromGenericObject(data: any, componentId: string): StandardDataSourceConfig {
    return this.createStandardConfig(componentId, [
      this.createStandardDataSource(DEFAULT_SOURCE_ID, [this.createStandardItem('static', data)])
    ])
  }

  private static convertToSimpleConfigEditor(standardData: StandardDataSourceConfig): any {
    return {
      dataSources: standardData.dataSources.map(ds => ({
        sourceId: ds.sourceId,
        dataItems: ds.dataItems,
        mergeStrategy: ds.mergeStrategy
      })),
      createdAt: standardData.createdAt,
      updatedAt: standardData.updatedAt
    }
  }

  private static convertToImportExport(standardData: StandardDataSourceConfig): any {
    const dataItems = standardData.dataSources.flatMap(ds => ds.dataItems.map(item => item.item))

    return {
      dataSourceConfig: {
        dataItems,
        mergeStrategy: standardData.dataSources[0]?.mergeStrategy || DEFAULT_MERGE_STRATEGY
      }
    }
  }

  private static convertToCard2Executor(standardData: StandardDataSourceConfig): any {
    const result: Record<string, any> = {}

    standardData.dataSources.forEach(ds => {
      ds.dataItems.forEach((item, index) => {
        // card2 executor 不支持一个 sourceId 下挂数组，因此多项时追加索引展开。
        const key = ds.dataItems.length === 1 ? ds.sourceId : `${ds.sourceId}_${index}`
        result[key] = {
          type: item.item.type,
          data: item.item.config,
          metadata: {
            sourceId: ds.sourceId,
            processing: item.processing
          }
        }
      })
    })

    return result
  }

  static normalizeMultiple(dataList: Array<{ data: any; componentId: string }>): StandardDataSourceConfig[] {
    return dataList.map(({ data, componentId }) => this.normalizeToStandard(data, componentId))
  }

  static validateStandardFormat(data: StandardDataSourceConfig): { valid: boolean; errors: string[] } {
    const errors: string[] = []

    if (!data.componentId) {
      errors.push('componentId is required')
    }

    if (!Array.isArray(data.dataSources)) {
      errors.push('dataSources must be an array')
    } else {
      data.dataSources.forEach((ds, dsIndex) => {
        if (!ds.sourceId) {
          errors.push(`dataSources[${dsIndex}].sourceId is required`)
        }

        if (!Array.isArray(ds.dataItems)) {
          errors.push(`dataSources[${dsIndex}].dataItems must be an array`)
        } else {
          ds.dataItems.forEach((item, itemIndex) => {
            if (!item.item || !item.processing) {
              errors.push(`dataSources[${dsIndex}].dataItems[${itemIndex}] must include item and processing`)
            }
          })
        }
      })
    }

    return {
      valid: errors.length === 0,
      errors
    }
  }

  private static createStandardConfig(
    componentId: string,
    dataSources: StandardDataSource[],
    createdAt?: number
  ): StandardDataSourceConfig {
    const now = Date.now()
    return {
      componentId,
      dataSources,
      createdAt: createdAt ?? now,
      updatedAt: now
    }
  }

  private static createStandardDataSource(
    sourceId: string,
    dataItems: StandardDataItem[],
    mergeStrategy: StandardDataSource['mergeStrategy'] = DEFAULT_MERGE_STRATEGY
  ): StandardDataSource {
    return {
      sourceId,
      dataItems,
      mergeStrategy
    }
  }

  private static createStandardItem(
    type: unknown,
    config: Record<string, any>,
    processing: Partial<StandardProcessing> = {}
  ): StandardDataItem {
    return {
      item: {
        type: normalizePersistedDataSourceType(type),
        config
      },
      processing: {
        filterPath: processing.filterPath ?? DEFAULT_FILTER_PATH,
        customScript: processing.customScript,
        defaultValue: processing.defaultValue
      }
    }
  }
}

/**
 * 文件用途: DataFormatNormalizer 的历史配置兼容 helper。
 * 核心逻辑: 识别旧配置形状，并把旧数据源字段、原始 data item 和 mergeStrategy 归一化。
 * 关键注意事项: 只能收敛兼容判断，不能改写已持久化的 SimpleConfigurationEditor、rawData、_id 语义。
 * 重构建议: 后续若恢复配置编辑器组件，应继续复用这里的纯函数，避免在 UI 层重复兼容链。
 */

import type { StandardDataItem, StandardDataSourceConfig } from './DataFormatNormalizer'

type StandardMergeStrategy = StandardDataSourceConfig['dataSources'][number]['mergeStrategy']
type StandardDataSourceType = StandardDataItem['item']['type']

const ALLOWED_MERGE_STRATEGY_TYPES: StandardMergeStrategy['type'][] = ['object', 'array', 'replace']
const ALLOWED_DATA_SOURCE_TYPES: StandardDataSourceType[] = [
  'static',
  'http',
  'json',
  'websocket',
  'file',
  'data-source-bindings'
]

export function normalizePersistedDataSourceType(type: unknown): StandardDataSourceType {
  if (type === 'api') {
    return 'http'
  }

  if (ALLOWED_DATA_SOURCE_TYPES.includes(type as StandardDataSourceType)) {
    return type as StandardDataSourceType
  }

  throw new Error(`UNSUPPORTED_DATA_SOURCE_TYPE:${String(type)}`)
}

export function isStandardDataItem(item: any): item is StandardDataItem {
  return !!(
    item &&
    typeof item === 'object' &&
    item.item &&
    typeof item.item === 'object' &&
    ALLOWED_DATA_SOURCE_TYPES.includes(item.item.type) &&
    item.item.config &&
    typeof item.item.config === 'object' &&
    item.processing &&
    typeof item.processing === 'object' &&
    typeof item.processing.filterPath === 'string'
  )
}

export function isSimpleConfigEditorFormat(data: any): boolean {
  return !!(
    data &&
    typeof data === 'object' &&
    'dataSources' in data &&
    Array.isArray(data.dataSources) &&
    data.dataSources.some((ds: any) => ds && ('sourceId' in ds || 'id' in ds) && Array.isArray(ds.dataItems))
  )
}

export function isImportExportFormat(data: any): boolean {
  return !!(
    data &&
    typeof data === 'object' &&
    'dataSourceConfig' in data &&
    data.dataSourceConfig?.dataItems &&
    Array.isArray(data.dataSourceConfig.dataItems)
  )
}

export function normalizePersistedSourceId(source: any, fallback: string): string {
  return source?.sourceId || source?.id || fallback
}

export function normalizePersistedMergeStrategy(strategy: any): StandardMergeStrategy {
  if (
    typeof strategy === 'string' &&
    ALLOWED_MERGE_STRATEGY_TYPES.includes(strategy as StandardMergeStrategy['type'])
  ) {
    return { type: strategy as StandardMergeStrategy['type'] }
  }

  if (strategy && typeof strategy === 'object' && ALLOWED_MERGE_STRATEGY_TYPES.includes(strategy.type)) {
    return strategy as StandardMergeStrategy
  }

  return { type: 'object' }
}

export function normalizePersistedDataItem(rawItem: any): StandardDataItem {
  if (isStandardDataItem(rawItem)) {
    return rawItem
  }

  const wrappedItem = rawItem?.item && typeof rawItem.item === 'object' ? rawItem.item : rawItem ?? {}
  const processing = rawItem?.processing ?? {}

  return {
    item: {
      type: normalizePersistedDataSourceType(wrappedItem.type ?? 'static'),
      config: wrappedItem.config ?? wrappedItem.data ?? wrappedItem
    },
    processing: {
      filterPath: processing.filterPath ?? rawItem?.filterPath ?? '$',
      customScript: processing.customScript ?? rawItem?.customScript ?? rawItem?.processScript,
      defaultValue: processing.defaultValue ?? rawItem?.defaultValue
    }
  }
}

/**
 * 文件用途: Data Source Binding Config 的测试文件。
 * 核心逻辑: 构造局部 fixture、mock 依赖并断言公开契约和关键边界行为。
 * 关键注意事项: 测试应覆盖可观察行为，避免绑定无关实现细节导致重构成本过高。
 * 重构建议: 补充历史配置、异常输入和回归场景，提升重构保护力度。
 */

import { describe, expect, it, vi } from 'vitest'

import {
  dataSourceBindingConfig,
  DataSourceBindingConfig,
  installDataSourceBindingConfigDebugGlobal
} from './DataSourceBindingConfig'

const createComponentConfig = () => ({
  base: {
    deviceId: 'device-001',
    metricsList: ['temperature', 'humidity']
  },
  component: {
    startTime: new Date('2026-06-27T00:00:00.000Z'),
    endTime: new Date('2026-06-27T01:00:00.000Z'),
    dataType: 'telemetry',
    refreshInterval: '45',
    filterCondition: 'status=online',
    tenantId: 'tenant-a'
  }
})

describe('DataSourceBindingConfig', () => {
  it('builds HTTP params from default visualization data bindings', () => {
    const config = new DataSourceBindingConfig()

    expect(config.buildHttpParams(createComponentConfig())).toEqual({
      deviceId: 'device-001',
      metrics: 'temperature,humidity',
      startTime: '2026-06-27T00:00:00.000Z',
      endTime: '2026-06-27T01:00:00.000Z',
      dataType: 'telemetry',
      refreshInterval: 45,
      filter: 'status=online'
    })
  })

  it('honors strict, loose, disabled, and custom auto-bind modes', () => {
    const config = new DataSourceBindingConfig()
    const componentConfig = createComponentConfig()

    expect(
      config.buildAutoBindParams(componentConfig, {
        enabled: true,
        mode: 'strict',
        includeProperties: ['base.deviceId', 'component.refreshInterval']
      })
    ).toEqual({
      deviceId: 'device-001',
      refreshInterval: 45
    })

    expect(
      config.buildAutoBindParams(componentConfig, {
        enabled: true,
        mode: 'loose',
        excludeProperties: ['base.metricsList', 'component.filterCondition']
      })
    ).toEqual({
      deviceId: 'device-001',
      startTime: '2026-06-27T00:00:00.000Z',
      endTime: '2026-06-27T01:00:00.000Z',
      dataType: 'telemetry',
      refreshInterval: 45
    })

    expect(
      config.buildAutoBindParams(componentConfig, {
        enabled: true,
        mode: 'custom',
        customRules: [
          {
            propertyPath: 'component.tenantId',
            paramName: 'tenant_id',
            transform: (value) => String(value).toUpperCase()
          }
        ]
      })
    ).toEqual({ tenant_id: 'TENANT-A' })

    expect(config.buildAutoBindParams(componentConfig, { enabled: false, mode: 'strict' })).toMatchObject({
      deviceId: 'device-001',
      metrics: 'temperature,humidity'
    })
  })

  it('falls back to the original value when a binding transform fails', () => {
    const config = new DataSourceBindingConfig()
    const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => undefined)

    config.registerBindingRule({
      propertyPath: 'component.tenantId',
      paramName: 'tenant_id',
      transform: () => {
        throw new Error('transform failed')
      }
    })

    expect(config.buildHttpParams(createComponentConfig())).toMatchObject({
      tenant_id: 'tenant-a'
    })
    expect(warnSpy).toHaveBeenCalledTimes(1)

    warnSpy.mockRestore()
  })

  it('applies dynamic rules, component-specific rules, and trigger gates', () => {
    const config = new DataSourceBindingConfig()

    config.addCustomBindingRule({
      propertyPath: 'component.tenantId',
      paramName: 'tenantId'
    })
    config.addCustomTriggerRule({
      propertyPath: 'component.tenantId',
      enabled: true,
      debounceMs: 50
    })
    config.setComponentConfig('rdi-card', {
      componentType: 'rdi-card',
      additionalBindings: [{ propertyPath: 'component.filterCondition', paramName: 'rdi_filter' }],
      additionalTriggers: [{ propertyPath: 'component.filterCondition', enabled: true, debounceMs: 10 }]
    })

    expect(config.getBindingRule('component.tenantId')?.paramName).toBe('tenantId')
    expect(config.shouldTriggerDataSource('component.tenantId')).toBe(true)
    expect(config.shouldTriggerDataSource('component.refreshInterval')).toBe(false)
    expect(config.getBindingRule('component.filterCondition', 'rdi-card')?.paramName).toBe('filter')
    expect(config.getAllBindingRules('rdi-card').some((rule) => rule.paramName === 'rdi_filter')).toBe(true)
    expect(config.getTriggerRule('component.filterCondition', 'rdi-card')?.debounceMs).toBe(250)

    expect(config.removeCustomBindingRule('component.tenantId')).toBe(true)
    expect(config.removeCustomTriggerRule('component.tenantId')).toBe(true)
    expect(config.getBindingRule('component.tenantId')).toBeUndefined()
    expect(config.shouldTriggerDataSource('component.tenantId')).toBe(false)
  })

  it('reports debug information without touching private implementation-only fields', () => {
    const config = new DataSourceBindingConfig()

    const debugInfo = config.getDebugInfo('rdi-card')

    expect(debugInfo.baseBindingRules).toBe(7)
    expect(debugInfo.baseTriggerRules).toBe(7)
    expect(debugInfo.currentBindingRules).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ propertyPath: 'base.deviceId', paramName: 'deviceId', required: true }),
        expect.objectContaining({ propertyPath: 'base.metricsList', paramName: 'metrics' })
      ])
    )
    expect(debugInfo.currentTriggerRules).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ propertyPath: 'base.deviceId', enabled: true, debounceMs: 100 })
      ])
    )
  })

  it('keeps default v1-v2 binding rules as retained runtime contract until migrated through rule APIs', () => {
    const config = new DataSourceBindingConfig()

    expect(config.buildHttpParams(createComponentConfig())).toMatchObject({
      deviceId: 'device-001',
      metrics: 'temperature,humidity'
    })

    expect(config.removeBindingRule('base.deviceId')).toBe(true)
    expect(config.buildHttpParams(createComponentConfig())).not.toHaveProperty('deviceId')

    config.registerBindingRule({
      propertyPath: 'base.deviceId',
      paramName: 'device_id'
    })

    expect(config.buildHttpParams(createComponentConfig())).toMatchObject({
      device_id: 'device-001'
    })
  })

  it('clears only base rules while preserving custom and component extensions', () => {
    const config = new DataSourceBindingConfig()

    config.addCustomBindingRule({
      propertyPath: 'component.tenantId',
      paramName: 'tenantId'
    })
    config.addCustomTriggerRule({
      propertyPath: 'component.tenantId',
      enabled: true
    })
    config.setComponentConfig('rdi-card', {
      componentType: 'rdi-card',
      additionalBindings: [{ propertyPath: 'component.cardId', paramName: 'cardId' }],
      additionalTriggers: [{ propertyPath: 'component.cardId', enabled: true }]
    })

    config.clearAllRules()

    expect(config.getDebugInfo('rdi-card')).toMatchObject({
      baseBindingRules: 0,
      baseTriggerRules: 0,
      customBindingRules: 1,
      customTriggerRules: 1
    })
    expect(config.getBindingRule('base.deviceId')).toBeUndefined()
    expect(config.getBindingRule('component.tenantId')?.paramName).toBe('tenantId')
    expect(config.getTriggerRule('component.tenantId')?.enabled).toBe(true)
    expect(config.getBindingRule('component.cardId', 'rdi-card')?.paramName).toBe('cardId')
    expect(config.getTriggerRule('component.cardId', 'rdi-card')?.enabled).toBe(true)
    expect(config.getComponentConfig('rdi-card')?.componentType).toBe('rdi-card')
  })

  it('installs and reversibly cleans up the explicit debug global', () => {
    const emptyTarget: Record<string, any> = {}
    const removeNewValue = installDataSourceBindingConfigDebugGlobal(emptyTarget)

    expect(emptyTarget.__dataSourceBindingConfig).toBe(dataSourceBindingConfig)
    removeNewValue()
    removeNewValue()
    expect(emptyTarget).not.toHaveProperty('__dataSourceBindingConfig')

    const previousValue = { host: true }
    const targetWithPreviousValue: Record<string, any> = {
      __dataSourceBindingConfig: previousValue
    }
    const restorePreviousValue = installDataSourceBindingConfigDebugGlobal(targetWithPreviousValue)

    expect(targetWithPreviousValue.__dataSourceBindingConfig).toBe(dataSourceBindingConfig)
    restorePreviousValue()
    expect(targetWithPreviousValue.__dataSourceBindingConfig).toBe(previousValue)

    const hostReplacement = { host: 'replacement' }
    const targetOverwrittenByHost: Record<string, any> = {}
    const preserveHostReplacement = installDataSourceBindingConfigDebugGlobal(targetOverwrittenByHost)
    targetOverwrittenByHost.__dataSourceBindingConfig = hostReplacement
    preserveHostReplacement()

    expect(targetOverwrittenByHost.__dataSourceBindingConfig).toBe(hostReplacement)
  })
})

/**
 * 文件用途: 集中管理属性到 HTTP 参数的绑定规则和数据源触发规则。
 * 核心逻辑: 保留可移除、可替换的 v1-v2 默认兼容表，并允许通过公开 API 注册基础、
 * 自定义及组件级附加规则。
 * 关键注意事项: 默认规则和 debug 信息属于 visual-editor 数据源兼容契约，字段名变更会影响已保存配置。
 */

/**
 * 参数绑定规则接口
 */
export interface BindingRule {
  /** 属性路径，如 'base.deviceId' */
  propertyPath: string
  /** HTTP参数名 */
  paramName: string
  /** 数据转换函数（可选） */
  transform?: (value: any) => any
  /** 兼容必填元数据；当前参数构建不会据此强制校验缺失值 */
  required?: boolean
  /** 参数说明 */
  description?: string
}

/**
 * 触发规则接口
 */
export interface TriggerRule {
  /** 属性路径 */
  propertyPath: string
  /** 是否启用 */
  enabled: boolean
  /** 防抖时间（毫秒），默认使用全局配置 */
  debounceMs?: number
  /** 规则说明 */
  description?: string
}

/**
 * 组件特定配置接口
 */
export interface ComponentBindingConfig {
  /** 组件类型 */
  componentType: string
  /** 额外的绑定规则 */
  additionalBindings?: BindingRule[]
  /** 额外的触发规则 */
  additionalTriggers?: TriggerRule[]
  /** 是否启用自动绑定 */
  autoBindEnabled?: boolean
}

/**
 * 自动绑定配置接口
 * 用于简化数据源配置，提供autoBind选项
 */
export interface AutoBindConfig {
  /** 是否启用自动绑定 */
  enabled: boolean
  /** 绑定模式 */
  mode: 'strict' | 'loose' | 'custom'
  /** 自定义绑定规则 */
  customRules?: BindingRule[]
  /** 排除的属性列表 */
  excludeProperties?: string[]
  /** 包含的属性列表（仅在strict模式下生效） */
  includeProperties?: string[]
}

/**
 * 数据源绑定配置中心。
 * 默认基础规则是保留的 v1-v2 运行时兼容契约；调用方可通过注册、移除、
 * 自定义和组件级 API 逐步迁移到新的配置结构。
 */
export class DataSourceBindingConfig {
  private bindingRules: Map<string, BindingRule> = new Map()
  private triggerRules: Map<string, TriggerRule> = new Map()

  constructor() {
    this.initializeDefaultRules()
  }

  /**
   * 注册可通过公开规则 API 替换或删除的 v1-v2 默认兼容表。
   */
  private initializeDefaultRules(): void {
    // 注册默认绑定规则
    this.registerBindingRule({
      propertyPath: 'base.deviceId',
      paramName: 'deviceId',
      required: true,
      description: '设备ID - 默认规则，可修改或删除'
    })

    this.registerBindingRule({
      propertyPath: 'base.metricsList',
      paramName: 'metrics',
      transform: (value: any[]) => (Array.isArray(value) ? value.join(',') : value),
      description: '指标列表 - 默认规则，可修改或删除'
    })

    this.registerBindingRule({
      propertyPath: 'component.startTime',
      paramName: 'startTime',
      transform: (value: any) => (value instanceof Date ? value.toISOString() : value),
      description: '开始时间 - 默认规则，可修改或删除'
    })

    this.registerBindingRule({
      propertyPath: 'component.endTime',
      paramName: 'endTime',
      transform: (value: any) => (value instanceof Date ? value.toISOString() : value),
      description: '结束时间 - 默认规则，可修改或删除'
    })

    this.registerBindingRule({
      propertyPath: 'component.dataType',
      paramName: 'dataType',
      description: '数据类型 - 默认规则，可修改或删除'
    })

    this.registerBindingRule({
      propertyPath: 'component.refreshInterval',
      paramName: 'refreshInterval',
      transform: (value: any) => parseInt(value) || 30,
      description: '刷新间隔 - 默认规则，可修改或删除'
    })

    this.registerBindingRule({
      propertyPath: 'component.filterCondition',
      paramName: 'filter',
      description: '过滤条件 - 默认规则，可修改或删除'
    })

    // 注册默认触发规则
    this.registerTriggerRule({
      propertyPath: 'base.deviceId',
      enabled: true,
      debounceMs: 100,
      description: '设备ID触发 - 默认规则，可修改或删除'
    })

    this.registerTriggerRule({
      propertyPath: 'base.metricsList',
      enabled: true,
      debounceMs: 200,
      description: '指标列表触发 - 默认规则，可修改或删除'
    })

    this.registerTriggerRule({
      propertyPath: 'component.startTime',
      enabled: true,
      debounceMs: 300,
      description: '开始时间触发 - 默认规则，可修改或删除'
    })

    this.registerTriggerRule({
      propertyPath: 'component.endTime',
      enabled: true,
      debounceMs: 300,
      description: '结束时间触发 - 默认规则，可修改或删除'
    })

    this.registerTriggerRule({
      propertyPath: 'component.dataType',
      enabled: true,
      debounceMs: 150,
      description: '数据类型触发 - 默认规则，可修改或删除'
    })

    this.registerTriggerRule({
      propertyPath: 'component.refreshInterval',
      enabled: false,
      description: '刷新间隔触发 - 默认规则，可修改或删除'
    })

    this.registerTriggerRule({
      propertyPath: 'component.filterCondition',
      enabled: true,
      debounceMs: 250,
      description: '过滤条件触发 - 默认规则，可修改或删除'
    })
  }

  /** 注册或替换基础绑定规则。 */
  registerBindingRule(rule: BindingRule): void {
    this.bindingRules.set(rule.propertyPath, rule)
  }

  /** 注册或替换基础触发规则。 */
  registerTriggerRule(rule: TriggerRule): void {
    this.triggerRules.set(rule.propertyPath, rule)
  }

  /** 移除基础绑定规则。 */
  removeBindingRule(propertyPath: string): boolean {
    const removed = this.bindingRules.delete(propertyPath)
    return removed
  }

  /** 移除基础触发规则。 */
  removeTriggerRule(propertyPath: string): boolean {
    const removed = this.triggerRules.delete(propertyPath)
    return removed
  }

  /**
   * 清空基础绑定和触发规则；自定义规则及组件配置保持不变。
   */
  clearAllRules(): void {
    this.bindingRules.clear()
    this.triggerRules.clear()
  }

  // 组件特定配置
  private componentConfigs: Map<string, ComponentBindingConfig> = new Map()

  // 用户自定义规则
  private customBindingRules: BindingRule[] = []
  private customTriggerRules: TriggerRule[] = []

  /**
   * 按基础、自定义、组件附加的顺序返回绑定规则。
   * 同一路径查询使用首个匹配项，因此较早的规则优先。
   */
  getAllBindingRules(componentType?: string): BindingRule[] {
    const rules = Array.from(this.bindingRules.values())
    rules.push(...this.customBindingRules)

    if (componentType) {
      const componentConfig = this.componentConfigs.get(componentType)
      if (componentConfig?.additionalBindings) {
        rules.push(...componentConfig.additionalBindings)
      }
    }

    return rules
  }

  /**
   * 按基础、自定义、组件附加的顺序返回已启用的触发规则。
   * 同一路径查询使用首个匹配项，因此较早的规则优先。
   */
  getAllTriggerRules(componentType?: string): TriggerRule[] {
    const rules = Array.from(this.triggerRules.values())
    rules.push(...this.customTriggerRules)

    if (componentType) {
      const componentConfig = this.componentConfigs.get(componentType)
      if (componentConfig?.additionalTriggers) {
        rules.push(...componentConfig.additionalTriggers)
      }
    }

    return rules.filter(rule => rule.enabled)
  }

  /**
   * 根据属性路径获取绑定规则
   */
  getBindingRule(propertyPath: string, componentType?: string): BindingRule | undefined {
    const allRules = this.getAllBindingRules(componentType)
    return allRules.find(rule => rule.propertyPath === propertyPath)
  }

  /**
   * 根据属性路径获取触发规则
   */
  getTriggerRule(propertyPath: string, componentType?: string): TriggerRule | undefined {
    const allRules = this.getAllTriggerRules(componentType)
    return allRules.find(rule => rule.propertyPath === propertyPath)
  }

  /**
   * 检查属性是否应该触发数据源执行
   */
  shouldTriggerDataSource(propertyPath: string, componentType?: string): boolean {
    const triggerRule = this.getTriggerRule(propertyPath, componentType)
    return triggerRule?.enabled === true
  }

  private buildParamsFromRules(componentConfig: any, bindingRules: BindingRule[]): Record<string, any> {
    const httpParams: Record<string, any> = {}

    for (const rule of bindingRules) {
      const propertyValue = this.readPropertyValue(componentConfig, rule.propertyPath)

      if (!propertyValue.exists) {
        continue
      }

      httpParams[rule.paramName] = this.transformRuleValue(rule, propertyValue.value)
    }

    return httpParams
  }

  private readPropertyValue(componentConfig: any, propertyPath: string): { exists: boolean; value?: any } {
    const pathParts = propertyPath.split('.').filter(Boolean)
    let currentValue = componentConfig

    for (const part of pathParts) {
      if (currentValue == null || !Object.prototype.hasOwnProperty.call(currentValue, part)) {
        return { exists: false }
      }

      currentValue = currentValue[part]
    }

    return { exists: true, value: currentValue }
  }

  private transformRuleValue(rule: BindingRule, value: any): any {
    if (!rule.transform || typeof rule.transform !== 'function') {
      return value
    }

    try {
      return rule.transform(value)
    } catch (error) {
      console.warn(`⚠️ [DataSourceBindingConfig] 参数转换失败:`, {
        propertyPath: rule.propertyPath,
        paramName: rule.paramName,
        originalValue: value,
        error: error instanceof Error ? error.message : error
      })
      return value
    }
  }

  /**
   * 构建HTTP参数对象
   */
  buildHttpParams(componentConfig: any, componentType?: string): Record<string, any> {
    const bindingRules = this.getAllBindingRules(componentType)
    return this.buildParamsFromRules(componentConfig, bindingRules)
  }

  /**
   * 🚀 新增：使用autoBind配置自动构建HTTP参数
   * @param componentConfig 组件配置
   * @param autoBindConfig 自动绑定配置
   * @param componentType 组件类型
   * @returns 自动绑定的HTTP参数
   */
  buildAutoBindParams(
    componentConfig: any,
    autoBindConfig: AutoBindConfig,
    componentType?: string
  ): Record<string, any> {
    if (!autoBindConfig.enabled) {
      return this.buildHttpParams(componentConfig, componentType)
    }

    switch (autoBindConfig.mode) {
      case 'strict':
        // 严格模式：仅绑定指定的属性
        return this.buildStrictModeParams(componentConfig, autoBindConfig, componentType)

      case 'loose':
        // 宽松模式：绑定所有可用属性，排除指定属性
        return this.buildLooseModeParams(componentConfig, autoBindConfig, componentType)

      case 'custom':
        // 自定义模式：使用自定义绑定规则
        return this.buildCustomModeParams(componentConfig, autoBindConfig, componentType)

      default:
        return this.buildHttpParams(componentConfig, componentType)
    }
  }

  /**
   * 构建严格模式参数
   */
  private buildStrictModeParams(
    componentConfig: any,
    autoBindConfig: AutoBindConfig,
    componentType?: string
  ): Record<string, any> {
    const includeProperties = autoBindConfig.includeProperties || []

    // 只处理指定的属性
    const bindingRules = this.getAllBindingRules(componentType).filter(rule =>
      includeProperties.includes(rule.propertyPath)
    )

    return this.buildParamsFromRules(componentConfig, bindingRules)
  }

  /**
   * 构建宽松模式参数
   */
  private buildLooseModeParams(
    componentConfig: any,
    autoBindConfig: AutoBindConfig,
    componentType?: string
  ): Record<string, any> {
    const excludeProperties = autoBindConfig.excludeProperties || []

    // 处理所有属性，排除指定属性
    const bindingRules = this.getAllBindingRules(componentType).filter(
      rule => !excludeProperties.includes(rule.propertyPath)
    )

    return this.buildParamsFromRules(componentConfig, bindingRules)
  }

  /**
   * 构建自定义模式参数
   */
  private buildCustomModeParams(
    componentConfig: any,
    autoBindConfig: AutoBindConfig,
    componentType?: string
  ): Record<string, any> {
    const customRules = autoBindConfig.customRules || []
    return this.buildParamsFromRules(componentConfig, customRules)
  }

  /**
   * 添加自定义绑定规则
   */
  addCustomBindingRule(rule: BindingRule): void {
    // 检查是否已存在相同的属性路径
    const existingIndex = this.customBindingRules.findIndex(r => r.propertyPath === rule.propertyPath)
    if (existingIndex >= 0) {
      this.customBindingRules[existingIndex] = rule
    } else {
      this.customBindingRules.push(rule)
    }
  }

  /**
   * 添加自定义触发规则
   */
  addCustomTriggerRule(rule: TriggerRule): void {
    // 检查是否已存在相同的属性路径
    const existingIndex = this.customTriggerRules.findIndex(r => r.propertyPath === rule.propertyPath)
    if (existingIndex >= 0) {
      this.customTriggerRules[existingIndex] = rule
    } else {
      this.customTriggerRules.push(rule)
    }
  }

  /**
   * 设置组件特定配置
   */
  setComponentConfig(componentType: string, config: ComponentBindingConfig): void {
    this.componentConfigs.set(componentType, config)
  }

  /**
   * 获取组件特定配置
   */
  getComponentConfig(componentType: string): ComponentBindingConfig | undefined {
    return this.componentConfigs.get(componentType)
  }

  /**
   * 移除自定义规则
   */
  removeCustomBindingRule(propertyPath: string): boolean {
    const index = this.customBindingRules.findIndex(r => r.propertyPath === propertyPath)
    if (index >= 0) {
      this.customBindingRules.splice(index, 1)
      return true
    }
    return false
  }

  /**
   * 移除自定义触发规则
   */
  removeCustomTriggerRule(propertyPath: string): boolean {
    const index = this.customTriggerRules.findIndex(r => r.propertyPath === propertyPath)
    if (index >= 0) {
      this.customTriggerRules.splice(index, 1)
      return true
    }
    return false
  }

  /**
   * 获取调试信息
   */
  getDebugInfo(componentType?: string): any {
    const currentBindingRules = this.getAllBindingRules(componentType)
    const currentTriggerRules = this.getAllTriggerRules(componentType)

    return {
      baseBindingRules: this.bindingRules.size,
      baseTriggerRules: this.triggerRules.size,
      registeredBindingRules: this.bindingRules.size,
      registeredTriggerRules: this.triggerRules.size,
      customBindingRules: this.customBindingRules.length,
      customTriggerRules: this.customTriggerRules.length,
      effectiveBindingRules: currentBindingRules.length,
      effectiveTriggerRules: currentTriggerRules.length,
      componentConfigs: Array.from(this.componentConfigs.keys()),
      currentBindingRules: currentBindingRules.map(r => ({
        propertyPath: r.propertyPath,
        paramName: r.paramName,
        required: r.required
      })),
      currentTriggerRules: currentTriggerRules.map(r => ({
        propertyPath: r.propertyPath,
        enabled: r.enabled,
        debounceMs: r.debounceMs
      }))
    }
  }
}

// 共享运行时实例；模块导入本身不修改宿主全局作用域。
export const dataSourceBindingConfig = new DataSourceBindingConfig()

/**
 * 显式安装调试入口，并返回可逆清理函数。
 * 清理时不会覆盖宿主在安装后写入的新值。
 */
export function installDataSourceBindingConfigDebugGlobal(
  target: Record<string, any> = globalThis as Record<string, any>
): () => void {
  const key = '__dataSourceBindingConfig'
  const hadOwnValue = Object.prototype.hasOwnProperty.call(target, key)
  const previousValue = target[key]
  target[key] = dataSourceBindingConfig

  return () => {
    if (target[key] !== dataSourceBindingConfig) {
      return
    }

    if (hadOwnValue) {
      target[key] = previousValue
    } else {
      delete target[key]
    }
  }
}

