 * 关键注意事项: 测试应覆盖可观察行为，避免绑定无关实现细节导致重构成本过高。
 * 重构建议: 补充历史配置、异常输入和回归场景，提升重构保护力度。
 */

import { beforeEach, describe, expect, it } from 'vitest'

import { DynamicBindingAPI, installDynamicBindingDebugGlobal } from './DynamicBindingAPI'

describe('DynamicBindingAPI', () => {
  beforeEach(() => {
    delete (globalThis as any).__dynamicBindingAPI
    DynamicBindingAPI.clearAllDefaultRules()
  })

  it('does not mutate globalThis on module import', () => {
    expect((globalThis as any).__dynamicBindingAPI).toBeUndefined()
  })

  it('installs and removes the debug global explicitly', () => {
    const cleanup = installDynamicBindingDebugGlobal()

    expect((globalThis as any).__dynamicBindingAPI).toBe(DynamicBindingAPI)

    cleanup()
    expect((globalThis as any).__dynamicBindingAPI).toBeUndefined()
  })

  it('restores an existing debug global during cleanup', () => {
    const previousValue = { owner: 'host' }
    ;(globalThis as any).__dynamicBindingAPI = previousValue

    const cleanup = installDynamicBindingDebugGlobal()
    expect((globalThis as any).__dynamicBindingAPI).toBe(DynamicBindingAPI)

    cleanup()
    expect((globalThis as any).__dynamicBindingAPI).toBe(previousValue)
  })

  it('adds, lists, and removes fully custom binding and trigger rules', () => {
    DynamicBindingAPI.addCustomBinding({
      propertyPath: 'component.tenantId',
      paramName: 'tenant_id',
      required: true,
      transform: value => String(value).toUpperCase(),
      description: 'tenant binding'
    })
    DynamicBindingAPI.addCustomTrigger({
      propertyPath: 'component.tenantId',
      debounceMs: 0,
      description: 'tenant trigger'
    })

    const binding = DynamicBindingAPI.getCurrentBindingRules().find(rule => rule.propertyPath === 'component.tenantId')
    const trigger = DynamicBindingAPI.getCurrentTriggerRules().find(rule => rule.propertyPath === 'component.tenantId')

    expect(binding).toMatchObject({
      paramName: 'tenant_id',
      required: true,
      description: 'tenant binding'
    })
    expect(binding?.transform?.('tenant-a')).toBe('TENANT-A')
    expect(trigger).toMatchObject({
      enabled: true,
      debounceMs: 0,
      description: 'tenant trigger'
    })

    expect(DynamicBindingAPI.removeBinding('component.tenantId')).toBe(true)
    expect(DynamicBindingAPI.removeTrigger('component.tenantId')).toBe(true)
    expect(DynamicBindingAPI.getCurrentBindingRules().some(rule => rule.propertyPath === 'component.tenantId')).toBe(false)
    expect(DynamicBindingAPI.getCurrentTriggerRules().some(rule => rule.propertyPath === 'component.tenantId')).toBe(false)
  })

  it('registers component-specific binding and trigger rules without leaking them to other component types', () => {
    DynamicBindingAPI.configureCustomComponent('unit-rdi-device-operations', {
      bindings: [
        {
          propertyPath: 'component.metric',
          paramName: 'metric_name',
          required: true
        }
      ],
      triggers: [
        {
          propertyPath: 'component.metric',
          debounceMs: 0
        }
      ],
      autoBind: {
        enabled: true,
        mode: 'custom',
        customRules: []
      }
    })

    expect(DynamicBindingAPI.getCurrentBindingRules().some(rule => rule.paramName === 'metric_name')).toBe(false)
    expect(DynamicBindingAPI.getCurrentBindingRules('unit-rdi-device-operations')).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          propertyPath: 'component.metric',
          paramName: 'metric_name',
          required: true
        })
      ])
    )
    expect(DynamicBindingAPI.getCurrentTriggerRules('unit-rdi-device-operations')).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          propertyPath: 'component.metric',
          enabled: true,
          debounceMs: 0
        })
      ])
    )
  })

  it('applies built-in templates as removable runtime rules', () => {
    DynamicBindingAPI.applyTemplate('iot-device')

    const bindings = DynamicBindingAPI.getCurrentBindingRules()
    const sensorBinding = bindings.find(rule => rule.propertyPath === 'component.sensorIds')

    expect(bindings).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ propertyPath: 'base.deviceId', paramName: 'device_id', required: true }),
        expect.objectContaining({ propertyPath: 'base.deviceType', paramName: 'device_type' })
      ])
    )
    expect(sensorBinding?.transform?.(['temperature', 'humidity'])).toBe('temperature,humidity')
    expect(DynamicBindingAPI.getCurrentTriggerRules()).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ propertyPath: 'base.deviceId', enabled: true, debounceMs: 50 }),
        expect.objectContaining({ propertyPath: 'component.sensorIds', enabled: true, debounceMs: 200 })
      ])
    )

    DynamicBindingAPI.applyTemplate('custom')

    expect(DynamicBindingAPI.getCurrentBindingRules()).toEqual([])
    expect(DynamicBindingAPI.getCurrentTriggerRules()).toEqual([])
    expect(DynamicBindingAPI.getSystemStatus()).toMatchObject({
      totalBindingRules: 0,
      totalTriggerRules: 0,
      hasDefaultRules: false,
      isFullyCustomized: true
    })
  })

  it('removes device defaults through the same public API used by runtime configuration', () => {
    DynamicBindingAPI.applyTemplate('iot-device')
    DynamicBindingAPI.removeBinding('base.deviceId')
    DynamicBindingAPI.removeTrigger('base.deviceId')

    const remainingBindings = DynamicBindingAPI.getCurrentBindingRules()
    const remainingTriggers = DynamicBindingAPI.getCurrentTriggerRules()

    expect(remainingBindings.some(rule => rule.propertyPath === 'base.deviceId')).toBe(false)
    expect(remainingTriggers.some(rule => rule.propertyPath === 'base.deviceId')).toBe(false)
    expect(remainingBindings.length).toBeGreaterThan(0)
    expect(remainingTriggers.length).toBeGreaterThan(0)
    expect(DynamicBindingAPI.getSystemStatus()).toMatchObject({
      hasDefaultRules: true,
      isFullyCustomized: false
    })
  })
})

/**
 * 文件用途: 动态绑定 API facade，暴露运行时配置 binding/trigger 规则的高层入口。
 * 核心逻辑: 代理 DataSourceBindingConfig 的基础规则、组件附加规则和自动绑定启用状态。
 * 关键注意事项: 清空操作只移除基础规则，自定义扩展和组件配置继续保留。
 */

import {
  dataSourceBindingConfig,
  type BindingRule,
  type TriggerRule,
  type AutoBindConfig
} from './DataSourceBindingConfig'
import { createLogger } from '@/utils/logger'

const logger = createLogger('DynamicBindingAPI')

/**
 * 运行时绑定规则配置入口；默认兼容表可替换或移除，扩展规则独立保留。
 */
export class DynamicBindingAPI {
  /**
   * 清空基础默认规则；自定义扩展和组件配置保持不变。
   */
  static clearAllDefaultRules(): void {
    dataSourceBindingConfig.clearAllRules()
    logger.debug('[DynamicBindingAPI] 已清空基础默认规则，扩展规则与组件配置保持不变')
  }

  /** 注册或替换指定属性路径的基础绑定规则。 */
  static addCustomBinding(config: {
    propertyPath: string
    paramName: string
    transform?: (value: any) => any
    required?: boolean
    description?: string
  }): void {
    dataSourceBindingConfig.registerBindingRule({
      propertyPath: config.propertyPath,
      paramName: config.paramName,
      transform: config.transform,
      required: config.required || false,
      description: config.description || `自定义绑定: ${config.propertyPath} → ${config.paramName}`
    })
  }

  /** 注册或替换指定属性路径的基础触发规则。 */
  static addCustomTrigger(config: {
    propertyPath: string
    enabled?: boolean
    debounceMs?: number
    description?: string
  }): void {
    dataSourceBindingConfig.registerTriggerRule({
      propertyPath: config.propertyPath,
      enabled: config.enabled !== false,
      debounceMs: config.debounceMs ?? 100,
      description: config.description || `自定义触发: ${config.propertyPath}`
    })
  }

  /** 移除指定属性路径的基础绑定规则。 */
  static removeBinding(propertyPath: string): boolean {
    return dataSourceBindingConfig.removeBindingRule(propertyPath)
  }

  /** 移除指定属性路径的基础触发规则。 */
  static removeTrigger(propertyPath: string): boolean {
    return dataSourceBindingConfig.removeTriggerRule(propertyPath)
  }

  /**
   * 配置组件附加绑定/触发规则和自动绑定开关；同路径基础规则仍优先。
   */
  static configureCustomComponent(
    componentType: string,
    config: {
      bindings: Array<{
        propertyPath: string
        paramName: string
        transform?: (value: any) => any
        required?: boolean
      }>
      triggers: Array<{
        propertyPath: string
        enabled?: boolean
        debounceMs?: number
      }>
      autoBind?: AutoBindConfig
    }
  ): void {
    dataSourceBindingConfig.setComponentConfig(componentType, {
      componentType,
      additionalBindings: config.bindings.map(b => ({
        propertyPath: b.propertyPath,
        paramName: b.paramName,
        transform: b.transform,
        required: b.required || false,
        description: `${componentType}组件专用绑定: ${b.propertyPath}`
      })),
      additionalTriggers: config.triggers.map(t => ({
        propertyPath: t.propertyPath,
        enabled: t.enabled !== false,
        debounceMs: t.debounceMs ?? 100,
        description: `${componentType}组件专用触发: ${t.propertyPath}`
      })),
      autoBindEnabled: config.autoBind?.enabled || false
    })

    logger.debug(`[DynamicBindingAPI] 已配置自定义组件 ${componentType}:`, {
      bindingCount: config.bindings.length,
      triggerCount: config.triggers.length,
      autoBindEnabled: config.autoBind?.enabled
    })
  }

  /** 返回基础、自定义和组件附加绑定规则的聚合结果。 */
  static getCurrentBindingRules(componentType?: string): BindingRule[] {
    return dataSourceBindingConfig.getAllBindingRules(componentType)
  }

  /** 返回对应聚合范围内已启用的触发规则。 */
  static getCurrentTriggerRules(componentType?: string): TriggerRule[] {
    return dataSourceBindingConfig.getAllTriggerRules(componentType)
  }

  /** 应用可通过公开 API 移除或替换的兼容规则模板。 */
  static applyTemplate(template: 'iot-device' | 'data-analytics' | 'user-interface' | 'custom'): void {
    switch (template) {
      case 'iot-device':
        this.applyIoTDeviceTemplate()
        break
      case 'data-analytics':
        this.applyDataAnalyticsTemplate()
        break
      case 'user-interface':
        this.applyUITemplate()
        break
      case 'custom':
        this.clearAllDefaultRules()
        break
    }
  }

  /**
   * IoT物模型 - 设备相关的绑定规则
   */
  private static applyIoTDeviceTemplate(): void {
    this.clearAllDefaultRules()

    // 设备基础属性
    this.addCustomBinding({
      propertyPath: 'base.deviceId',
      paramName: 'device_id',
      required: true,
      description: 'IoT设备ID'
    })

    this.addCustomBinding({
      propertyPath: 'base.deviceType',
      paramName: 'device_type',
      description: 'IoT设备类型'
    })

    this.addCustomBinding({
      propertyPath: 'component.sensorIds',
      paramName: 'sensors',
      transform: (ids: string[]) => ids.join(','),
      description: 'IoT传感器列表'
    })

    // 对应的触发规则
    this.addCustomTrigger({
      propertyPath: 'base.deviceId',
      debounceMs: 50,
      description: 'IoT设备切换触发'
    })

    this.addCustomTrigger({
      propertyPath: 'component.sensorIds',
      debounceMs: 200,
      description: 'IoT传感器变更触发'
    })

    logger.debug('[DynamicBindingAPI] 已应用IoT物模型')
  }

  /**
   * 数据分析模板 - 分析相关的绑定规则
   */
  private static applyDataAnalyticsTemplate(): void {
    this.clearAllDefaultRules()

    // 数据查询属性
    this.addCustomBinding({
      propertyPath: 'component.timeRange',
      paramName: 'time_range',
      transform: (range: { start: Date; end: Date }) => ({
        start: range.start.toISOString(),
        end: range.end.toISOString()
      }),
      description: '数据分析时间范围'
    })

    this.addCustomBinding({
      propertyPath: 'component.aggregationType',
      paramName: 'aggregation',
      description: '数据聚合类型'
    })

    this.addCustomBinding({
      propertyPath: 'component.groupBy',
      paramName: 'group_by',
      transform: (fields: string[]) => fields.join(','),
      description: '数据分组字段'
    })

    // 对应的触发规则
    this.addCustomTrigger({
      propertyPath: 'component.timeRange',
      debounceMs: 500,
      description: '时间范围变更触发'
    })

    this.addCustomTrigger({
      propertyPath: 'component.aggregationType',
      debounceMs: 100,
      description: '聚合类型变更触发'
    })

    logger.debug('[DynamicBindingAPI] 已应用数据分析模板')
  }

  /**
   * UI界面模板 - 界面相关的绑定规则
   */
  private static applyUITemplate(): void {
    this.clearAllDefaultRules()

    // UI状态属性
    this.addCustomBinding({
      propertyPath: 'component.selectedTab',
      paramName: 'active_tab',
      description: 'UI选中标签页'
    })

    this.addCustomBinding({
      propertyPath: 'component.filterText',
      paramName: 'search_query',
      description: 'UI搜索查询'
    })

    this.addCustomBinding({
      propertyPath: 'component.pageSize',
      paramName: 'limit',
      transform: (size: number) => Math.max(1, Math.min(100, size)),
      description: 'UI分页大小'
    })

    // 对应的触发规则
    this.addCustomTrigger({
      propertyPath: 'component.selectedTab',
      debounceMs: 50,
      description: 'UI标签页切换触发'
    })

    this.addCustomTrigger({
      propertyPath: 'component.filterText',
      debounceMs: 300,
      description: 'UI搜索输入触发'
    })

    logger.debug('[DynamicBindingAPI] 已应用UI界面模板')
  }

  /** 返回基础规则、有效聚合规则和组件配置的运行时状态。 */
  static getSystemStatus(): {
    totalBindingRules: number
    totalTriggerRules: number
    customComponentCount: number
    hasDefaultRules: boolean
    isFullyCustomized: boolean
  } {
    const allBindings = this.getCurrentBindingRules()
    const allTriggers = this.getCurrentTriggerRules()
    const debugInfo = dataSourceBindingConfig.getDebugInfo()
    const hasDefaultRules = debugInfo.baseBindingRules > 0 || debugInfo.baseTriggerRules > 0

    return {
      totalBindingRules: allBindings.length,
      totalTriggerRules: allTriggers.length,
      customComponentCount: debugInfo.componentConfigs.length,
      hasDefaultRules,
      isFullyCustomized: !hasDefaultRules
    }
  }
}

/**
 * 显式安装调试全局入口，并返回可逆清理函数。
 * 模块导入本身不会写入 globalThis；宿主调试工具可按需安装。
 */
export function installDynamicBindingDebugGlobal(target: typeof globalThis = globalThis): () => void {
  const property = '__dynamicBindingAPI'
  const hadOwnProperty = Object.prototype.hasOwnProperty.call(target, property)
  const previousValue = (target as any)[property]
  ;(target as any)[property] = DynamicBindingAPI

  return () => {
    if (hadOwnProperty) {
      ;(target as any)[property] = previousValue
    } else {
      delete (target as any)[property]
    }
  }
}

/**
 * 文件用途: 独立管理 Data Warehouse 的动态参数。
 * 核心逻辑: 支持按直接键或 scope+name 组合键存储，并在读取时清理过期参数。
 * 关键注意事项: 参数仅在 Date.now() 严格大于 expiresAt 时过期。
 */

export interface DynamicParameterStorage {
  /** 参数名称 */
  name: string
  /** 参数值 */
  value: any
  /** 参数类型 */
  type: 'string' | 'number' | 'boolean' | 'object' | 'array'
  /** 作用域 */
  scope: 'global' | 'component' | 'session'
  /** 过期时间 */
  expiresAt?: number
  /** 依赖关系 */
  dependencies?: string[]
}

export class DynamicParameterStore {
  private storage = new Map<string, DynamicParameterStorage>()

  store(nameOrScope: string, parameterOrName: DynamicParameterStorage | string, value?: any): void {
    if (typeof parameterOrName === 'string') {
      const key = `${nameOrScope}:${parameterOrName}`
      this.storage.set(key, {
        name: parameterOrName,
        value,
        type: this.inferParameterType(value),
        scope: 'component'
      })
      return
    }

    this.storage.set(nameOrScope, parameterOrName)
  }

  get(nameOrScope: string, name?: string): DynamicParameterStorage | any | null {
    const key = name ? `${nameOrScope}:${name}` : nameOrScope
    const parameter = this.storage.get(key)

    if (parameter && parameter.expiresAt && Date.now() > parameter.expiresAt) {
      this.storage.delete(key)
      return null
    }
    if (!parameter) return null

    return name ? parameter.value : parameter
  }

  getAll(scope?: string): Record<string, any> {
    const parameters: Record<string, any> = {}

    for (const [key, parameter] of this.storage.entries()) {
      if (parameter.expiresAt && Date.now() > parameter.expiresAt) {
        this.storage.delete(key)
        continue
      }

      if (!scope) {
        parameters[key] = parameter
        continue
      }

      const prefix = `${scope}:`
      if (key.startsWith(prefix)) {
        parameters[key.slice(prefix.length)] = parameter.value
      }
    }

    return parameters
  }

  clear(): void {
    this.storage.clear()
  }

  private inferParameterType(value: any): DynamicParameterStorage['type'] {
    if (Array.isArray(value)) return 'array'
    if (value === null) return 'object'

    const valueType = typeof value
    if (valueType === 'string' || valueType === 'number' || valueType === 'boolean') {
      return valueType
    }

    return 'object'
  }
}

/**
 * 文件用途: Simple Data Bridge 的测试文件。
 * 核心逻辑: 构造局部 fixture、mock 依赖并断言公开契约和关键边界行为。
 * 关键注意事项: 测试应覆盖可观察行为，避免绑定无关实现细节导致重构成本过高。
 * 重构建议: 补充历史配置、异常输入和回归场景，提升重构保护力度。
 */

import { describe, expect, it, vi } from 'vitest'

import { SimpleDataBridge, type ComponentDataRequirement } from './SimpleDataBridge'
import type { DataSourceConfiguration, ExecutionResult } from './executors/MultiLayerExecutorChain'

const createWarehouse = () => {
  const completeData = new Map<string, Record<string, any>>()

  return {
    getComponentData: vi.fn((componentId: string) => completeData.get(componentId) ?? null),
    storeComponentData: vi.fn((componentId: string, sourceId: string, data: Record<string, any>) => {
      if (sourceId === 'complete') completeData.set(componentId, data)
    }),
    clearComponentCache: vi.fn((componentId: string) => completeData.delete(componentId)),
    clearAllCache: vi.fn(() => completeData.clear()),
    destroy: vi.fn(),
    setCacheExpiry: vi.fn(),
    getPerformanceMetrics: vi.fn(() => ({})),
    getStorageStats: vi.fn(() => ({
      totalComponents: completeData.size,
      totalDataSources: 0,
      memoryUsageMB: 0
    }))
  } as any
}

const createSuccessfulExecutor = (componentData: Record<string, any>) => ({
  executeDataProcessingChain: vi.fn(
    async (_config: DataSourceConfiguration): Promise<ExecutionResult> => ({
      success: true,
      componentData,
      executionTime: 1,
      timestamp: 1000
    })
  )
})

describe('SimpleDataBridge', () => {
  it('uses an injected snapshot reader before executing the data source chain', async () => {
    const warehouse = createWarehouse()
    const executorChain = createSuccessfulExecutor({
      'snapshot-source': {
        data: { value: 42 },
        type: 'json',
        lastUpdated: 1000
      }
    })
    const snapshotReader = vi.fn(() => ({
      dataSource: {
        dataSources: [
          {
            sourceId: 'snapshot-source',
            dataItems: [
              {
                item: { type: 'json', config: { jsonContent: '{"value":42}' } },
                processing: { filterPath: '$', defaultValue: {} }
              }
            ],
            mergeStrategy: 'object'
          }
        ]
      }
    }))
    const bridge = new SimpleDataBridge({
      warehouse,
      executorChain,
      snapshotReader,
      now: () => 1000,
      random: () => 0.5
    })

    const result = await bridge.executeComponent({
      componentId: 'component-1',
      dataSources: [{ id: 'stale-source', type: 'json', config: { data: { stale: true } } }]
    })

    expect(snapshotReader).toHaveBeenCalledWith('component-1')
    expect(executorChain.executeDataProcessingChain).toHaveBeenCalledTimes(1)
    expect(executorChain.executeDataProcessingChain.mock.calls[0][0]).toMatchObject({
      componentId: 'component-1',
      dataSources: [{ sourceId: 'snapshot-source' }],
      configHash: expect.any(String)
    })
    expect(result).toEqual({
      success: true,
      data: { 'snapshot-source': { value: 42 } },
      timestamp: 1000
    })
    expect(warehouse.storeComponentData).toHaveBeenCalledWith(
      'component-1',
      'complete',
      { 'snapshot-source': { value: 42 } },
      'multi-source'
    )
  })

  it('logs snapshot reader failures and falls back to the supplied requirement', async () => {
    const warehouse = createWarehouse()
    const executorChain = createSuccessfulExecutor({ 'fallback-source': { ok: true } })
    const logError = vi.fn()
    const requirement: ComponentDataRequirement = {
      componentId: 'component-2',
      dataSources: [{ id: 'fallback-source', type: 'json', config: { data: { ok: true } } }]
    }
    const bridge = new SimpleDataBridge({
      warehouse,
      executorChain,
      snapshotReader: vi.fn(() => {
        throw 'snapshot unavailable'
      }),
      logError,
      now: () => 2000,
      random: () => 0.25
    })

    const result = await bridge.executeComponent(requirement)

    expect(logError).toHaveBeenCalledWith(
      expect.stringContaining('[SimpleDataBridge] [component-2-2000-9]'),
      'snapshot unavailable'
    )
    expect(executorChain.executeDataProcessingChain.mock.calls[0][0]).toMatchObject({
      componentId: 'component-2',
      dataSources: [{ sourceId: 'fallback-source' }]
    })
    expect(result).toEqual({
      success: true,
      data: { 'fallback-source': { ok: true } },
      timestamp: 2000,
      metadata: {
        configurationSnapshot: {
          status: 'degraded',
          errorCode: 'CONFIGURATION_SNAPSHOT_UNAVAILABLE'
        }
      }
    })
  })

  it('executes supplied requirements without a snapshot host adapter', async () => {
    const warehouse = createWarehouse()
    const executorChain = createSuccessfulExecutor({ local: { value: 7 } })
    const bridge = new SimpleDataBridge({ warehouse, executorChain, now: () => 3000, random: () => 0 })

    const result = await bridge.executeComponent({
      componentId: 'component-local',
      dataSources: [{ id: 'local', type: 'static', config: { data: { value: 7 } } }]
    })

    expect(executorChain.executeDataProcessingChain.mock.calls[0][0]).toMatchObject({
      componentId: 'component-local',
      dataSources: [{ sourceId: 'local' }]
    })
    expect(result).toEqual({ success: true, data: { local: { value: 7 } }, timestamp: 3000 })
  })

  it('propagates an external-blocked failure without caching or notifying it', async () => {
    const warehouse = createWarehouse()
    const executorChain = {
      executeDataProcessingChain: vi.fn(async (): Promise<ExecutionResult> => ({
        success: false,
        componentData: {
          stream: {
            type: 'websocket',
            data: null,
            lastUpdated: 3000,
            metadata: { success: false, errorCode: 'WS_EXTERNAL_BLOCKED' }
          }
        },
        error: 'WebSocket数据源需要外部订阅适配器',
        errorCode: 'WS_EXTERNAL_BLOCKED',
        executionTime: 1,
        timestamp: 3000
      }))
    }
    const bridge = new SimpleDataBridge({ warehouse, executorChain, now: () => 3000, random: () => 0 })
    const callback = vi.fn()
    bridge.onDataUpdate(callback)

    const result = await bridge.executeComponent({
      componentId: 'component-stream',
      dataSources: [
        { id: 'stream', type: 'websocket', config: { wsUrl: 'wss://example.test/telemetry' } }
      ]
    })

    expect(result).toMatchObject({ success: false, errorCode: 'WS_EXTERNAL_BLOCKED' })
    expect(warehouse.storeComponentData).not.toHaveBeenCalled()
    expect(callback).not.toHaveBeenCalled()
  })

  it('does not destroy an injected warehouse by default', () => {
    const warehouse = createWarehouse()
    const bridge = new SimpleDataBridge({ warehouse })

    bridge.destroy()

    expect(warehouse.destroy).not.toHaveBeenCalled()
  })

  it('destroys an explicitly owned warehouse', () => {
    const warehouse = createWarehouse()
    const bridge = new SimpleDataBridge({ warehouse, destroyWarehouseOnDispose: true })

    bridge.destroy()

    expect(warehouse.destroy).toHaveBeenCalledOnce()
  })
})

/**
 * 文件用途: 简化数据桥接器。
 * 核心逻辑: 协调组件数据需求、配置转换和多层执行器链，产出组件可消费的数据。
 * 关键注意事项: 这是旧执行器路径的替代入口，配置结构和执行结果字段必须保持兼容。
 * 重构建议: 继续拆分配置转换、执行协调和错误归一，降低桥接器职责集中度。
 */

import {
  type IMultiLayerExecutorChain,
  MultiLayerExecutorChain,
  type DataSourceConfiguration,
  type ExecutionResult
} from './executors/MultiLayerExecutorChain'

import { dataWarehouse, type EnhancedDataWarehouse } from '@/core/data-architecture/DataWarehouse'

type ConfigurationSnapshot = { config: any; timestamp: number }
type ConfigurationSnapshotReader = (componentId: string) => any | Promise<any>
type ConfigurationSnapshotStatus =
  | { status: 'not-configured' | 'unavailable' }
  | { status: 'available'; snapshot: ConfigurationSnapshot }
  | { status: 'degraded'; errorCode: 'CONFIGURATION_SNAPSHOT_UNAVAILABLE' }
type SimpleDataBridgeExecutor = Pick<IMultiLayerExecutorChain, 'executeDataProcessingChain'>

export interface SimpleDataBridgeOptions {
  warehouse?: EnhancedDataWarehouse
  /** 仅在仓库由该桥接器独占时启用；默认不销毁共享或外部注入的仓库。 */
  destroyWarehouseOnDispose?: boolean
  executorChain?: SimpleDataBridgeExecutor
  /** 可选宿主快照适配器；运行时核心不反向依赖 visual-editor。 */
  snapshotReader?: ConfigurationSnapshotReader
  now?: () => number
  random?: () => number
  logError?: (...args: unknown[]) => void
}

/**
 * 简化的数据源配置
 */
export interface SimpleDataSourceConfig {
  /** 数据源ID */
  id: string
  /** 数据源类型 */
  type: 'static' | 'http' | 'json' | 'websocket' | 'file' | 'data-source-bindings'
  /** 配置选项 */
  config: {
    // 静态数据
    data?: any
    // HTTP配置
    url?: string
    method?: 'GET' | 'POST'
    headers?: Record<string, string>
    timeout?: number
    [key: string]: any
  }
  /** 过滤路径（JSONPath 语法） */
  filterPath?: string
  /** 自定义处理脚本 */
  processScript?: string
}

/**
 * 数据执行结果
 */
export interface DataResult {
  /** 是否成功 */
  success: boolean
  /** 数据内容 */
  data?: any
  /** 错误信息 */
  error?: string
  /** 稳定错误代码 */
  errorCode?: string
  /** 执行时间戳 */
  timestamp: number
  /** 可选执行元数据；兼容旧调用方，并显式暴露快照适配器降级。 */
  metadata?: {
    configurationSnapshot?: {
      status: 'degraded'
      errorCode: 'CONFIGURATION_SNAPSHOT_UNAVAILABLE'
    }
  }
}

/**
 * 组件数据需求
 */
export interface ComponentDataRequirement {
  /** 组件ID */
  componentId: string
  /** 数据源配置列表 */
  dataSources: SimpleDataSourceConfig[]
}

/**
 * 数据更新回调类型
 */
export type DataUpdateCallback = (componentId: string, data: Record<string, any>) => void

/**
 * 简化数据桥接器类
 * 只提供最基本的配置→数据转换功能
 */
export class SimpleDataBridge {
  /** 数据更新回调列表 */
  private callbacks = new Set<DataUpdateCallback>()

  /** 数据仓库实例 */
  private warehouse: EnhancedDataWarehouse

  /** 桥接器销毁时是否同时销毁其独占仓库。 */
  private destroyWarehouseOnDispose: boolean

  /** 多层执行器链实例（符合需求文档架构） */
  private executorChain: SimpleDataBridgeExecutor

  private snapshotReader?: ConfigurationSnapshotReader

  private now: () => number

  private random: () => number

  private logError: (...args: unknown[]) => void

  private componentConfigHashes = new Map<string, string>()

  constructor(options: SimpleDataBridgeOptions = {}) {
    this.warehouse = options.warehouse ?? dataWarehouse
    this.destroyWarehouseOnDispose = options.destroyWarehouseOnDispose ?? false
    this.executorChain = options.executorChain ?? new MultiLayerExecutorChain()
    this.snapshotReader = options.snapshotReader
    this.now = options.now ?? Date.now
    this.random = options.random ?? Math.random
    this.logError = options.logError ?? console.error
  }

  /**
   * 执行组件数据获取
   * 使用 MultiLayerExecutorChain 执行数据处理链。
   * @param requirement 组件数据需求
   * @returns 执行结果
   */
  async executeComponent(requirement: ComponentDataRequirement): Promise<DataResult> {
    return await this.doExecuteComponent(requirement, this.now(), 'direct-call')
  }

  /**
   * 实际的组件执行逻辑（从executeComponent中提取）
   */
  private async doExecuteComponent(
    requirement: ComponentDataRequirement,
    _startTime: number,
    _callerInfo: string
  ): Promise<DataResult> {
    const executionId = `${requirement.componentId}-${this.now()}-${this.random().toString(36).substr(2, 9)}`

    let metadata: DataResult['metadata']

    try {
      const snapshotStatus = await this.captureConfigurationSnapshot(requirement.componentId, executionId)
      if (snapshotStatus.status === 'available') {
        requirement = this.reconstructRequirementFromSnapshot(requirement, snapshotStatus.snapshot)
      } else if (snapshotStatus.status === 'degraded') {
        metadata = {
          configurationSnapshot: {
            status: 'degraded',
            errorCode: snapshotStatus.errorCode
          }
        }
      }

      let dataSourceConfig: DataSourceConfiguration

      const isDataSourceConfigFormat = this.isDataSourceConfiguration(requirement)

      if (isDataSourceConfigFormat) {
        dataSourceConfig = requirement as any
      } else {
        if (requirement.dataSources?.[0]?.dataSources) {
          const innerConfig = requirement.dataSources[0] as any
          dataSourceConfig = {
            componentId: requirement.componentId,
            dataSources: innerConfig.dataSources,
            createdAt: innerConfig.createdAt || this.now(),
            updatedAt: innerConfig.updatedAt || this.now()
          }
        } else {
          dataSourceConfig = this.convertToDataSourceConfiguration(requirement)
        }
      }

      const configHash = this.calculateConfigHash(dataSourceConfig)
      const cachedData = this.warehouse.getComponentData(requirement.componentId)
      const existingConfigHash = this.componentConfigHashes.get(requirement.componentId)

      if (cachedData && existingConfigHash === configHash) {
        return {
          success: true,
          data: cachedData,
          timestamp: this.now(),
          ...(metadata && { metadata })
        }
      }

      if (existingConfigHash && existingConfigHash !== configHash) {
        this.warehouse.clearComponentCache(requirement.componentId)
      }

      const enhancedDataSourceConfig = {
        ...dataSourceConfig,
        configHash
      }

      const executionResult: ExecutionResult = await this.executorChain.executeDataProcessingChain(
        enhancedDataSourceConfig,
        true
      )

      if (executionResult.success && executionResult.componentData) {
        const componentData = this.normalizeComponentData(executionResult.componentData)

        if (executionResult.componentData && typeof executionResult.componentData === 'object') {
          this.warehouse.clearComponentCache(requirement.componentId)

          Object.entries(componentData).forEach(([sourceId, sourceData]) => {
            this.warehouse.storeComponentData(requirement.componentId, sourceId, sourceData, 'multi-source')
          })

          this.warehouse.storeComponentData(requirement.componentId, 'complete', componentData, 'multi-source')
          this.componentConfigHashes.set(requirement.componentId, configHash)
        }

        this.notifyDataUpdate(requirement.componentId, componentData)
        return {
          success: true,
          data: componentData,
          timestamp: this.now(),
          ...(metadata && { metadata })
        }
      } else {
        return {
          success: false,
          error: executionResult.error || '执行失败',
          errorCode: executionResult.errorCode,
          timestamp: this.now(),
          ...(metadata && { metadata })
        }
      }
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error)
      return {
        success: false,
        error: errorMsg,
        timestamp: this.now(),
        ...(metadata && { metadata })
      }
    }
  }

  /**
   * 检查是否为 DataSourceConfiguration 格式
   * @param data 待检查的数据
   * @returns 是否为 DataSourceConfiguration 格式
   */
  private isDataSourceConfiguration(data: any): boolean {
    return (
      data &&
      typeof data === 'object' &&
      'componentId' in data &&
      'dataSources' in data &&
      Array.isArray(data.dataSources) &&
      data.dataSources.length > 0 &&
      'sourceId' in data.dataSources[0] &&
      'dataItems' in data.dataSources[0] &&
      'mergeStrategy' in data.dataSources[0]
    )
  }

  /**
   * 转换为 DataSourceConfiguration 格式
   * 将 SimpleDataBridge 的配置格式转换为 MultiLayerExecutorChain 所需的格式
   * @param requirement 组件数据需求
   * @returns DataSourceConfiguration 格式的配置
   */
  private convertToDataSourceConfiguration(requirement: ComponentDataRequirement): DataSourceConfiguration {
    const dataSources = requirement.dataSources.map(dataSource => ({
      sourceId: dataSource.id,
      dataItems: [
        {
          item: {
            type: dataSource.type,
            config: dataSource.config
          },
          processing: {
            filterPath: dataSource.filterPath || '$',
            customScript: dataSource.processScript,
            defaultValue: {}
          }
        }
      ],
      mergeStrategy: 'object' as const // 默认使用对象合并策略
    }))

    return {
      componentId: requirement.componentId,
      dataSources,
      createdAt: this.now(),
      updatedAt: this.now()
    }
  }

  private normalizeComponentData(data: Record<string, any>): Record<string, any> {
    const normalized: Record<string, any> = {}

    for (const [sourceId, sourceData] of Object.entries(data)) {
      if (
        sourceData &&
        typeof sourceData === 'object' &&
        'data' in sourceData &&
        ('type' in sourceData || 'lastUpdated' in sourceData || 'metadata' in sourceData)
      ) {
        normalized[sourceId] = sourceData.data ?? null
      } else {
        normalized[sourceId] = sourceData
      }
    }

    return normalized
  }

  /**
   * 通知数据更新
   * @param componentId 组件ID
   * @param data 数据
   */
  private notifyDataUpdate(componentId: string, data: Record<string, any>): void {
    this.callbacks.forEach(callback => {
      try {
        callback(componentId, data)
      } catch (_error) {
        // Keep one failing subscriber from blocking the remaining callbacks.
      }
    })
  }

  /**
   * 注册数据更新回调
   * @param callback 回调函数
   * @returns 取消注册的函数
   */
  onDataUpdate(callback: DataUpdateCallback): () => void {
    this.callbacks.add(callback)

    return () => {
      this.callbacks.delete(callback)
    }
  }

  /**
   * 获取组件数据（缓存接口）
   * @param componentId 组件ID
   * @returns 组件数据或null
   */
  getComponentData(componentId: string): Record<string, any> | null {
    return this.warehouse.getComponentData(componentId)
  }

  /**
   * 清除组件缓存
   * @param componentId 组件ID
   */
  clearComponentCache(componentId: string): void {
    this.warehouse.clearComponentCache(componentId)
    this.componentConfigHashes.delete(componentId)
  }

  /**
   * 清除所有缓存
   */
  clearAllCache(): void {
    this.warehouse.clearAllCache()
    this.componentConfigHashes.clear()
  }

  /**
   * 设置缓存过期时间
   * @param milliseconds 过期时间（毫秒）
   */
  setCacheExpiry(milliseconds: number): void {
    this.warehouse.setCacheExpiry(milliseconds)
  }

  /**
   * 获取数据仓库性能指标
   */
  getWarehouseMetrics() {
    return this.warehouse.getPerformanceMetrics()
  }

  /**
   * 获取存储统计信息
   */
  getStorageStats() {
    return this.warehouse.getStorageStats()
  }

  /**
   * 获取简单统计信息，包含数据仓库数据
   */
  getStats() {
    const warehouseStats = this.warehouse.getStorageStats()
    return {
      activeCallbacks: this.callbacks.size,
      timestamp: this.now(),
      warehouse: {
        totalComponents: warehouseStats.totalComponents,
        totalDataSources: warehouseStats.totalDataSources,
        memoryUsageMB: warehouseStats.memoryUsageMB
      }
    }
  }

  /**
   * 捕获可选宿主配置快照；适配器失败时返回明确降级状态。
   */
  private async captureConfigurationSnapshot(
    componentId: string,
    executionId: string
  ): Promise<ConfigurationSnapshotStatus> {
    if (!this.snapshotReader) {
      return { status: 'not-configured' }
    }

    try {
      const config = await this.snapshotReader(componentId)
      if (!config) {
        return { status: 'unavailable' }
      }

      return {
        status: 'available',
        snapshot: {
          config: JSON.parse(JSON.stringify(config)),
          timestamp: this.now()
        }
      }
    } catch (error) {
      this.logError(`❌ [SimpleDataBridge] [${executionId}] 配置快照捕获失败:`, error)
      return {
        status: 'degraded',
        errorCode: 'CONFIGURATION_SNAPSHOT_UNAVAILABLE'
      }
    }
  }

  /**
   * 基于配置快照重构数据需求。
   */
  private reconstructRequirementFromSnapshot(
    originalRequirement: ComponentDataRequirement,
    snapshot: ConfigurationSnapshot
  ): ComponentDataRequirement {
    if (snapshot.config.dataSource) {
      return {
        ...originalRequirement,
        dataSources: this.convertSnapshotToDataSources(snapshot.config)
      }
    }
    return originalRequirement
  }

  /**
   * 将配置快照转换为数据源格式。
   */
  private convertSnapshotToDataSources(config: any): any[] {
    if (config.dataSource && config.dataSource.dataSources) {
      return config.dataSource.dataSources
    }
    return []
  }

  /**
   * 计算配置哈希值，用于检测配置变化。
   */
  private calculateConfigHash(config: any): string {
    try {
      const configString = JSON.stringify(config, (key, value) =>
        ['createdAt', 'updatedAt', 'configHash'].includes(key) ? undefined : value
      )
      let hash = 0
      for (let i = 0; i < configString.length; i++) {
        const char = configString.charCodeAt(i)
        hash = (hash << 5) - hash + char
        hash = hash & hash
      }
      return Math.abs(hash).toString(36)
    } catch (_error) {
      return this.now().toString(36)
    }
  }

  /**
   * 清理桥接器自身资源；仅在调用方明确声明独占仓库时联动销毁仓库。
   */
  destroy(): void {
    this.callbacks.clear()
    this.componentConfigHashes.clear()
    if (this.destroyWarehouseOnDispose) {
      this.warehouse.destroy()
    }
  }
}

