    await vi.advanceTimersByTimeAsync(1)
    expect(bridgeMock.updateComponentExecutor).toHaveBeenCalledTimes(1)
    expect(bridgeMock.updateComponentExecutor).toHaveBeenCalledWith(
      'card-debounce',
      'rdi-card',
      expect.objectContaining({
        base: { deviceId: 'device-2' }
      })
    )
  })

  it('does not execute when the changed value is unchanged or not whitelisted', async () => {
    registerDataComponent('card-flow')

    flow().updateComponentConfig('card-flow', 'base', { deviceId: 'old-device' })
    flow().updateComponentConfig('card-flow', 'component', { title: 'New title' })

    await vi.advanceTimersByTimeAsync(150)
    expect(bridgeMock.updateComponentExecutor).toHaveBeenCalledTimes(0)
  })

  it('manual trigger executes registered data-source configs and skips missing or empty configs', async () => {
    await flow().triggerDataSource('missing-card', 'manual-check')
    expect(bridgeMock.updateComponentExecutor).toHaveBeenCalledTimes(0)

    flow().registerComponent('card-empty', { componentType: 'widget', base: {} })
    await flow().triggerDataSource('card-empty', 'manual-check')
    expect(bridgeMock.updateComponentExecutor).toHaveBeenCalledTimes(0)

    registerDataComponent('card-manual')
    await flow().triggerDataSource('card-manual', 'manual-check')

    expect(bridgeMock.updateComponentExecutor).toHaveBeenCalledWith(
      'card-manual',
      'rdi-card',
      expect.objectContaining({
        _httpParams: { device_id: 'built-device' }
      })
    )
  })

  it('unregistering a component cancels pending debounce execution', async () => {
    bindingConfigMock.shouldTriggerDataSource.mockReturnValue(true)
    registerDataComponent('card-unregister')

    flow().updateComponentConfig('card-unregister', 'base', { deviceId: 'new-device' })
    flow().unregisterComponent('card-unregister')

    await vi.advanceTimersByTimeAsync(150)
    expect(bridgeMock.updateComponentExecutor).toHaveBeenCalledTimes(0)
  })

  it('property watchers can unsubscribe and a failing watcher does not block others', () => {
    const failingWatcher = vi.fn(() => {
      throw new Error('watcher failed')
    })
    const activeWatcher = vi.fn()
    const removedWatcher = vi.fn()

    const unsubscribeRemoved = flow().addPropertyWatcher('base.deviceId', removedWatcher)
    flow().addPropertyWatcher('base.deviceId', failingWatcher)
    const unsubscribeActive = flow().addPropertyWatcher('base.deviceId', activeWatcher)
    unsubscribeRemoved()
    registerDataComponent('card-watch')

    flow().updateComponentConfig('card-watch', 'base', { deviceId: 'watch-device' })

    expect(removedWatcher).toHaveBeenCalledTimes(0)
    expect(failingWatcher).toHaveBeenCalledTimes(1)
    expect(activeWatcher).toHaveBeenCalledTimes(1)

    unsubscribeActive()
  })

  it('proxies trigger, binding, component, and debug configuration operations', () => {
    flow().addTriggerProperty('base.productId', false, 250)
    flow().addBindingRule('base.deviceId', 'device_id', value => String(value), true)
    flow().setComponentBindingConfig('rdi-card', { triggerRules: [], bindingRules: [] } as any)

    expect(flow().getTriggerWhitelist('rdi-card')).toEqual(['base.deviceId', 'component.metricsList'])
    expect(flow().getBindingDebugInfo('rdi-card')).toEqual({ rules: 2 })
    expect(bindingConfigMock.addCustomTriggerRule).toHaveBeenCalledWith({
      propertyPath: 'base.productId',
      enabled: false,
      debounceMs: 250,
      description: '动态添加的触发规则: base.productId'
    })
    expect(bindingConfigMock.addCustomBindingRule).toHaveBeenCalledWith(
      expect.objectContaining({
        propertyPath: 'base.deviceId',
        paramName: 'device_id',
        required: true
      })
    )
    expect(bindingConfigMock.setComponentConfig).toHaveBeenCalledWith('rdi-card', {
      triggerRules: [],
      bindingRules: []
    })
    expect(bindingConfigMock.getDebugInfo).toHaveBeenCalledWith('rdi-card')
  })

  it('installs and removes the debug instance only when explicitly requested', () => {
    const target = {} as unknown as typeof globalThis
    const debugTarget = target as typeof globalThis & Record<string, unknown>
    const cleanup = installSimpleDataFlowDebugGlobal(target)

    expect(debugTarget.__simpleDataFlow).toBe(simpleDataFlow)

    cleanup()
    expect(Object.prototype.hasOwnProperty.call(debugTarget, '__simpleDataFlow')).toBe(false)
  })

  it('restores an existing debug instance during cleanup', () => {
    const previousValue = { owner: 'host' }
    const target = { __simpleDataFlow: previousValue } as unknown as typeof globalThis
    const debugTarget = target as typeof globalThis & Record<string, unknown>
    const cleanup = installSimpleDataFlowDebugGlobal(target)

    expect(debugTarget.__simpleDataFlow).toBe(simpleDataFlow)
    cleanup()
    expect(debugTarget.__simpleDataFlow).toBe(previousValue)
  })

  it('does not overwrite a host value assigned after debug installation', () => {
    const target = {} as unknown as typeof globalThis
    const debugTarget = target as typeof globalThis & Record<string, unknown>
    const cleanup = installSimpleDataFlowDebugGlobal(target)
    const hostValue = { owner: 'host-after-install' }

    debugTarget.__simpleDataFlow = hostValue
    cleanup()

    expect(debugTarget.__simpleDataFlow).toBe(hostValue)
  })
})

/**
 * 文件用途: 简化数据流管理器。
 * 核心逻辑: 通过显式配置更新按绑定规则触发数据源刷新，连接编辑器属性和运行时数据。
 * 关键注意事项: 白名单、绑定路径和触发规则会直接影响组件数据刷新频率和正确性。
 * 重构建议: 把属性监听、触发判定和数据执行拆成独立服务，进一步缩小单例状态范围。
 */

import { simpleDataBridge } from './SimpleDataBridge'
import { dataSourceBindingConfig, type ComponentBindingConfig } from './DataSourceBindingConfig'
import { createLogger } from '@/utils/logger'

const logger = createLogger('SimpleDataFlow')

/**
 * 属性变更事件接口
 */
export interface PropertyChangeEvent {
  componentId: string
  propertyPath: string // 如 'base.deviceId' 或 'component.startTime'
  oldValue: any
  newValue: any
  timestamp: number
}

/**
 * 数据源执行配置接口
 */
export interface DataSourceExecutionConfig {
  componentId: string
  componentType: string
  httpParams: Record<string, any>
  forceRefresh?: boolean
}

/**
 * 简化数据流管理器类
 */
export class SimpleDataFlow {
  private static instance: SimpleDataFlow | null = null

  // 组件配置仅通过显式 API 更新，不需要 Vue 响应式代理。
  private componentConfigs = new Map<string, any>()

  // 属性变更监听器
  private propertyWatchers = new Map<string, Set<(event: PropertyChangeEvent) => void>>()

  // 防抖控制
  private debounceTimers = new Map<string, ReturnType<typeof setTimeout>>()
  private readonly DEBOUNCE_TIME = 100 // 100ms 防抖

  // 执行中的组件集合（防止重复执行）
  private executingComponents = new Set<string>()

  private constructor() {}

  /**
   * 获取单例实例
   */
  static getInstance(): SimpleDataFlow {
    if (!SimpleDataFlow.instance) {
      SimpleDataFlow.instance = new SimpleDataFlow()
    }
    return SimpleDataFlow.instance
  }

  /**
   * 注册组件配置
   * @param componentId 组件ID
   * @param config 组件完整配置
   */
  registerComponent(componentId: string, config: any): void {
    logger.debug(`[SimpleDataFlow] 注册组件:`, { componentId, hasConfig: !!config })
    this.componentConfigs.set(componentId, config)
  }

  /**
   * 更新组件配置的某个部分
   * @param componentId 组件ID
   * @param section 配置节 (base, component, dataSource, interaction)
   * @param newConfig 新配置内容
   */
  updateComponentConfig(componentId: string, section: string, newConfig: any): void {
    const currentConfig = this.componentConfigs.get(componentId) || {}
    const oldSectionConfig = currentConfig[section] || {}

    // 更新配置
    currentConfig[section] = { ...oldSectionConfig, ...newConfig }
    this.componentConfigs.set(componentId, currentConfig)

    logger.debug(`[SimpleDataFlow] 组件配置更新:`, {
      componentId,
      section,
      hasChanges: true,
      newConfigKeys: Object.keys(newConfig)
    })

    // 检查是否有属性变更需要触发数据源
    this.checkAndTriggerDataSource(componentId, section, oldSectionConfig, newConfig)
  }

  /**
   * 检查属性变更并触发数据源（如果需要）
   */
  private checkAndTriggerDataSource(componentId: string, section: string, oldConfig: any, newConfig: any): void {
    const changedProperties: PropertyChangeEvent[] = []

    // 检测具体的属性变更
    for (const [key, newValue] of Object.entries(newConfig)) {
      const oldValue = oldConfig[key]
      if (oldValue !== newValue) {
        const propertyPath = `${section}.${key}`

        changedProperties.push({
          componentId,
          propertyPath,
          oldValue,
          newValue,
          timestamp: Date.now()
        })
      }
    }

    if (changedProperties.length === 0) {
      return
    }

    logger.debug(`[SimpleDataFlow] 检测到属性变更:`, {
      componentId,
      section,
      changedProperties: changedProperties.map(p => ({
        property: p.propertyPath,
        oldValue: p.oldValue,
        newValue: p.newValue
      }))
    })

    // 检查是否有任何变更的属性在触发白名单中
    const config = this.componentConfigs.get(componentId)
    const componentType = config?.componentType

    const triggerProperties = changedProperties.filter(change =>
      this.shouldTriggerDataSource(change.propertyPath, componentType)
    )

    if (triggerProperties.length > 0) {
      logger.debug(`[SimpleDataFlow] 触发数据源更新:`, {
        componentId,
        triggerProperties: triggerProperties.map(p => p.propertyPath)
      })

      // 防抖执行数据源更新
      this.debounceDataSourceExecution(componentId, triggerProperties)
    }

    // 触发属性变更监听器
    changedProperties.forEach(change => {
      this.notifyPropertyWatchers(change)
    })
  }

  /**
   * 检查属性是否在触发白名单中
   */
  private shouldTriggerDataSource(propertyPath: string, componentType?: string): boolean {
    return dataSourceBindingConfig.shouldTriggerDataSource(propertyPath, componentType)
  }

  /**
   * 防抖执行数据源更新
   */
  private debounceDataSourceExecution(componentId: string, triggerProperties: PropertyChangeEvent[]): void {
    // 清除之前的定时器
    const existingTimer = this.debounceTimers.get(componentId)
    if (existingTimer) {
      clearTimeout(existingTimer)
    }

    // 设置新的定时器
    const timer = setTimeout(() => {
      this.executeDataSource(componentId, triggerProperties)
      this.debounceTimers.delete(componentId)
    }, this.DEBOUNCE_TIME)

    this.debounceTimers.set(componentId, timer)
  }

  /**
   * 执行数据源更新
   */
  private async executeDataSource(componentId: string, triggerProperties: PropertyChangeEvent[]): Promise<void> {
    // 防止重复执行
    if (this.executingComponents.has(componentId)) {
      logger.debug(`[SimpleDataFlow] 组件正在执行中，跳过:`, { componentId })
      return
    }

    this.executingComponents.add(componentId)

    try {
      logger.debug(`[SimpleDataFlow] 开始执行数据源:`, {
        componentId,
        triggerProperties: triggerProperties.map(p => p.propertyPath)
      })

      // 获取组件配置
      const config = this.componentConfigs.get(componentId)
      if (!config || !config.dataSource) {
        logger.debug(`[SimpleDataFlow] 组件无数据源配置:`, { componentId })
        return
      }

      // 构建HTTP参数
      const httpParams = this.buildHttpParams(componentId, config)

      logger.debug(`[SimpleDataFlow] 构建HTTP参数:`, {
        componentId,
        httpParams
      })

      // 清除缓存，确保获取最新数据
      simpleDataBridge.clearComponentCache(componentId)

      // 使用 VisualEditorBridge 执行数据源
      const { getVisualEditorBridge } = await import('./VisualEditorBridge')
      const visualEditorBridge = getVisualEditorBridge()

      // 构建完整配置对象
      const executionConfig = {
        base: config.base || {},
        dataSource: config.dataSource,
        component: config.component || {},
        interaction: config.interaction || {},
        // 注入构建的HTTP参数
        _httpParams: httpParams
      }

      // 执行数据源
      const result = await visualEditorBridge.updateComponentExecutor(
        componentId,
        config.componentType || 'widget',
        executionConfig
      )

      logger.debug(`[SimpleDataFlow] 数据源执行完成:`, {
        componentId,
        success: !!result
      })
    } catch (error) {
      logger.error(`[SimpleDataFlow] 数据源执行失败:`, {
        componentId,
        error: error instanceof Error ? error.message : error
      })
    } finally {
      this.executingComponents.delete(componentId)
    }
  }

  /**
   * 构建HTTP参数
   * 根据自动绑定规则将组件属性映射到HTTP参数
   */
  private buildHttpParams(componentId: string, config: any): Record<string, any> {
    const componentType = config.componentType

    // 🚀 新增：检查是否有autoBind配置
    const autoBindConfig = this.getAutoBindConfig(config)

    if (autoBindConfig) {
      return dataSourceBindingConfig.buildAutoBindParams(config, autoBindConfig, componentType)
    }

    return dataSourceBindingConfig.buildHttpParams(config, componentType)
  }

  /**
   * 按数据源、组件实例、组件类型的优先级解析 autoBind 配置。
   * 组件类型配置只保存启用状态，启用时使用兼容的 loose 模式。
   */
  private getAutoBindConfig(config: any): import('./DataSourceBindingConfig').AutoBindConfig | null {
    if (config.dataSource?.autoBind) {
      return config.dataSource.autoBind
    }

    if (config.autoBind) {
      return config.autoBind
    }

    const componentConfig = dataSourceBindingConfig.getComponentConfig(config.componentType)
    if (componentConfig?.autoBindEnabled) {
      return {
        enabled: true,
        mode: 'loose'
      }
    }

    return null
  }

  /**
   * 添加属性变更监听器
   */
  addPropertyWatcher(propertyPath: string, callback: (event: PropertyChangeEvent) => void): () => void {
    if (!this.propertyWatchers.has(propertyPath)) {
      this.propertyWatchers.set(propertyPath, new Set())
    }

    this.propertyWatchers.get(propertyPath)!.add(callback)

    // 返回移除监听器的函数
    return () => {
      const watchers = this.propertyWatchers.get(propertyPath)
      if (watchers) {
        watchers.delete(callback)
        if (watchers.size === 0) {
          this.propertyWatchers.delete(propertyPath)
        }
      }
    }
  }

  /**
   * 通知属性变更监听器
   */
  private notifyPropertyWatchers(event: PropertyChangeEvent): void {
    const watchers = this.propertyWatchers.get(event.propertyPath)
    if (watchers) {
      watchers.forEach(callback => {
        try {
          callback(event)
        } catch (error) {
          logger.error(`[SimpleDataFlow] 属性监听器执行出错:`, {
            propertyPath: event.propertyPath,
            error: error instanceof Error ? error.message : error
          })
        }
      })
    }
  }

  /**
   * 手动触发组件数据源执行
   * @param componentId 组件ID
   * @param reason 触发原因
   */
  async triggerDataSource(componentId: string, reason: string = 'manual'): Promise<void> {
    logger.debug(`[SimpleDataFlow] 手动触发数据源:`, { componentId, reason })

    const config = this.componentConfigs.get(componentId)
    if (!config) {
      logger.warn(`[SimpleDataFlow] 组件配置不存在:`, { componentId })
      return
    }

    // 创建一个虚拟的属性变更事件来触发执行
    const virtualEvent: PropertyChangeEvent = {
      componentId,
      propertyPath: 'manual.trigger',
      oldValue: null,
      newValue: reason,
      timestamp: Date.now()
    }

    await this.executeDataSource(componentId, [virtualEvent])
  }

  /**
   * 移除组件注册
   */
  unregisterComponent(componentId: string): void {
    logger.debug(`[SimpleDataFlow] 注销组件:`, { componentId })

    this.componentConfigs.delete(componentId)

    // 清除相关的防抖定时器
    const timer = this.debounceTimers.get(componentId)
    if (timer) {
      clearTimeout(timer)
      this.debounceTimers.delete(componentId)
    }

    // 移除执行状态
    this.executingComponents.delete(componentId)
  }

  /**
   * 获取当前触发白名单
   */
  getTriggerWhitelist(componentType?: string): string[] {
    return dataSourceBindingConfig.getAllTriggerRules(componentType).map(rule => rule.propertyPath)
  }

  /**
   * 动态添加触发属性到白名单
   */
  addTriggerProperty(propertyPath: string, enabled: boolean = true, debounceMs?: number): void {
    dataSourceBindingConfig.addCustomTriggerRule({
      propertyPath,
      enabled,
      debounceMs,
      description: `动态添加的触发规则: ${propertyPath}`
    })
  }

  /**
   * 动态添加自动绑定规则
   */
  addBindingRule(propertyPath: string, paramName: string, transform?: (value: any) => any, required?: boolean): void {
    dataSourceBindingConfig.addCustomBindingRule({
      propertyPath,
      paramName,
      transform,
      required,
      description: `动态添加的绑定规则: ${propertyPath} → ${paramName}`
    })
  }

  /**
   * 设置组件特定的绑定配置
   */
  setComponentBindingConfig(componentType: string, config: ComponentBindingConfig): void {
    dataSourceBindingConfig.setComponentConfig(componentType, config)
  }

  /**
   * 获取绑定配置的调试信息
   */
  getBindingDebugInfo(componentType?: string): any {
    return dataSourceBindingConfig.getDebugInfo(componentType)
  }
}

// 共享实例保持现有运行时契约，但模块导入不会写入宿主全局。
export const simpleDataFlow = SimpleDataFlow.getInstance()

const SIMPLE_DATA_FLOW_DEBUG_GLOBAL = '__simpleDataFlow'

/**
 * 按需安装调试实例。返回的清理函数只撤销本次安装，不覆盖宿主后续写入。
 */
export function installSimpleDataFlowDebugGlobal(target: typeof globalThis = globalThis): () => void {
  const debugTarget = target as typeof globalThis & Record<string, unknown>
  const hadOwnValue = Object.prototype.hasOwnProperty.call(debugTarget, SIMPLE_DATA_FLOW_DEBUG_GLOBAL)
  const previousValue = debugTarget[SIMPLE_DATA_FLOW_DEBUG_GLOBAL]

  debugTarget[SIMPLE_DATA_FLOW_DEBUG_GLOBAL] = simpleDataFlow

  return () => {
    if (debugTarget[SIMPLE_DATA_FLOW_DEBUG_GLOBAL] !== simpleDataFlow) {
      return
    }

    if (hadOwnValue) {
      debugTarget[SIMPLE_DATA_FLOW_DEBUG_GLOBAL] = previousValue
    } else {
      delete debugTarget[SIMPLE_DATA_FLOW_DEBUG_GLOBAL]
    }
  }
}

/**
 * 文件用途: Type Compatibility Checker 的测试文件。
 * 核心逻辑: 构造局部 fixture、mock 依赖并断言公开契约和关键边界行为。
 * 关键注意事项: 测试应覆盖可观察行为，避免绑定无关实现细节导致重构成本过高。
 * 重构建议: 补充历史配置、异常输入和回归场景，提升重构保护力度。
 */

import { beforeEach, describe, expect, it } from 'vitest'

import {
  installTypeCompatibilityDebugGlobal,
  TypeCompatibilityChecker
} from './TypeCompatibilityChecker'
import type { ComponentDataRequirement, HttpConfig } from './types/unified-types'

const checker = TypeCompatibilityChecker.getInstance()

beforeEach(() => {
  checker.clearCheckHistory()
})

const validHttpConfig = (): HttpConfig => ({
  url: '/api/v1/devices/:device_id/telemetry',
  method: 'GET',
  timeout: 5000,
  params: [
    {
      key: 'start_time',
      value: '2026-06-27T00:00:00Z',
      enabled: true,
      isDynamic: false,
      dataType: 'string',
      variableName: '',
      description: 'query start time',
      paramType: 'query',
      valueMode: 'manual'
    }
  ],
  headers: [
    {
      key: 'X-Tenant-ID',
      value: 'tenant-a',
      enabled: true,
      isDynamic: true,
      dataType: 'string',
      variableName: 'tenantId',
      description: 'tenant header',
      paramType: 'header',
      valueMode: 'property'
    }
  ],
  pathParameter: {
    key: 'device_id',
    value: 'device-001',
    isDynamic: true,
    dataType: 'string',
    variableName: 'deviceId',
    description: 'device id'
  }
})

const validRequirement = (): ComponentDataRequirement => ({
  componentId: 'rdi-card-001',
  componentName: 'RDI Card',
  staticParams: [
    {
      key: 'title',
      name: 'Title',
      type: 'string',
      description: 'Card title',
      required: true
    }
  ],
  dataSources: [
    {
      key: 'telemetry',
      name: 'Telemetry',
      description: 'RDI telemetry source',
      supportedTypes: ['api'],
      fieldMappings: {
        value: {
          targetField: 'temperature',
          type: 'value',
          required: true
        }
      },
      required: true
    }
  ]
})

describe('TypeCompatibilityChecker', () => {
  it('accepts a valid dynamic HTTP data-source configuration', () => {
    const result = checker.checkHttpConfigCompatibility(validHttpConfig())

    expect(result.valid).toBe(true)
    expect(result.level).toBe('compatible')
    expect(result.errors).toEqual([])
    expect(result.affectedItems).toEqual([])
  })

  it('flags invalid HTTP config fields and weak dynamic parameter definitions', () => {
    const result = checker.checkHttpConfigCompatibility({
      ...validHttpConfig(),
      url: 'ftp://example.com/devices',
      method: 'TRACE' as HttpConfig['method'],
      timeout: 500,
      params: [
        {
          key: '',
          value: 'x',
          enabled: true,
          isDynamic: true,
          dataType: 'json' as never,
          variableName: '',
          description: 'broken param',
          paramType: 'header' as never,
          valueMode: 'invalid' as never
        }
      ],
      pathParameter: {
        value: true,
        isDynamic: true,
        dataType: 'array' as never,
        variableName: 'deviceId',
        description: 'invalid path parameter'
      },
      pathParams: [
        {
          key: '',
          value: '',
          enabled: true,
          isDynamic: true,
          dataType: 'string',
          variableName: '',
          description: 'broken path param',
          paramType: 'query' as never,
          valueMode: 'manual'
        }
      ]
    })

    expect(result.valid).toBe(false)
    expect(result.level).toBe('incompatible')
    expect(result.affectedItems).toEqual(
      expect.arrayContaining([
        'url',
        'method',
        'params[0].key',
        'params[0].paramType',
        'params[0].variableName',
        'params[0].valueMode',
        'pathParameter',
        'pathParams[0].key',
        'pathParams[0].paramType',
        'pathParams[0].variableName',
        'timeout'
      ])
    )
    expect(result.errors.join('\n')).toContain('URL格式错误')
    expect(result.warnings.join('\n')).toContain('超时时间设置可能不合理')
  })

  it('validates component data requirements for visual editor cards', () => {
    const compatible = checker.checkComponentDataRequirementCompatibility(validRequirement())

    expect(compatible.valid).toBe(true)
    expect(compatible.level).toBe('compatible')

    const missingSources = checker.checkComponentDataRequirementCompatibility({
      componentId: 'card-with-static-data',
      componentName: 'Static Card',
      dataSources: []
    })

    expect(missingSources.valid).toBe(true)
    expect(missingSources.level).toBe('warning')
    expect(missingSources.warnings).toContain('组件没有定义任何数据源需求')

    const invalid = checker.checkComponentDataRequirementCompatibility({
      ...validRequirement(),
      componentId: '',
      staticParams: [
        {
          key: 'title',
          name: 'Title',
          type: 'string',
          description: 'title'
        },
        {
          key: 'title',
          name: '',
          type: 'unsupported' as never,
          description: 'duplicate invalid title'
        }
      ],
      dataSources: [
        {
          key: '',
          name: 'Broken',
          description: 'Missing key and supported types',
          supportedTypes: [],
          fieldMappings: {}
        }
      ]
    })

    expect(invalid.valid).toBe(false)
    expect(invalid.affectedItems).toEqual(
      expect.arrayContaining(['componentId', 'staticParams[1]', 'dataSources[0]', 'staticParams.title'])
    )
    expect(invalid.errors.join('\n')).toContain('静态参数字段名重复')
  })

  it('reports compatible, warning, and incompatible data type conversions', () => {
    expect(checker.checkDataTypeCompatibility('number', 'number')).toMatchObject({
      valid: true,
      level: 'compatible',
      warnings: []
    })

    expect(checker.checkDataTypeCompatibility('string', 'number')).toMatchObject({
      valid: true,
      level: 'warning',
      suggestions: ['使用转换函数: stringToNumber']
    })

    expect(checker.checkDataTypeCompatibility('string', 'array')).toMatchObject({
      valid: false,
      level: 'incompatible'
    })
  })

  it('aggregates batch compatibility results with item ids and exposes mapping stats', () => {
    const result = checker.batchCompatibilityCheck([
      { id: 'valid-http', type: 'httpConfig', data: validHttpConfig() },
      {
        id: 'needs-cast',
        type: 'dataType',
        data: { sourceType: 'string', targetType: 'boolean' }
      },
      {
        id: 'broken-card',
        type: 'componentRequirement',
        data: { componentId: '', componentName: 'Broken', dataSources: [] }
      }
    ])

    expect(result.valid).toBe(false)
    expect(result.level).toBe('incompatible')
    expect(result.errors.join('\n')).toContain('[broken-card] 组件ID无效或缺失')
    expect(result.warnings.join('\n')).toContain('[needs-cast] 需要进行类型转换')
    expect(result.affectedItems).toEqual(expect.arrayContaining(['broken-card.componentId']))

    expect(checker.getTypeMappingStats()).toMatchObject({
      categories: ['basic', 'httpParameter'],
      categoryStats: {
        basic: 17,
        httpParameter: 3
      },
      totalMappings: 20
    })
  })

  it('records results and returns history snapshots that callers cannot mutate', () => {
    checker.checkDataTypeCompatibility('string', 'number')

    const history = checker.getCheckHistory()
    expect(history).toHaveLength(1)
    expect(history[0]).toMatchObject({
      checkType: 'DataTypeCompatibility',
      level: 'warning'
    })

    history[0].warnings.push('caller mutation')
    history[0].suggestions.length = 0

    expect(checker.getCheckHistory()[0]).toMatchObject({
      warnings: ['需要进行类型转换: string -> number'],
      suggestions: ['使用转换函数: stringToNumber']
    })

    checker.clearCheckHistory()
    expect(checker.getCheckHistory()).toEqual([])
  })

  it('installs and removes the debug API only when explicitly requested', () => {
    const target = {} as unknown as typeof globalThis
    const debugTarget = target as typeof globalThis & Record<string, unknown>
    const cleanup = installTypeCompatibilityDebugGlobal(target)

    expect(debugTarget.__TYPE_COMPATIBILITY_CHECKER__).toMatchObject({ checker })

    cleanup()
    expect(Object.prototype.hasOwnProperty.call(debugTarget, '__TYPE_COMPATIBILITY_CHECKER__')).toBe(false)
  })

  it('restores an existing debug global during cleanup', () => {
    const previousValue = { owner: 'host' }
    const target = {
      __TYPE_COMPATIBILITY_CHECKER__: previousValue
    } as unknown as typeof globalThis
    const debugTarget = target as typeof globalThis & Record<string, unknown>
    const cleanup = installTypeCompatibilityDebugGlobal(target)

    expect(debugTarget.__TYPE_COMPATIBILITY_CHECKER__).not.toBe(previousValue)
    cleanup()
    expect(debugTarget.__TYPE_COMPATIBILITY_CHECKER__).toBe(previousValue)
  })

  it('does not overwrite a host value assigned after debug installation', () => {
    const target = {} as unknown as typeof globalThis
    const debugTarget = target as typeof globalThis & Record<string, unknown>
    const cleanup = installTypeCompatibilityDebugGlobal(target)
    const hostValue = { owner: 'host-after-install' }

    debugTarget.__TYPE_COMPATIBILITY_CHECKER__ = hostValue
    cleanup()

    expect(debugTarget.__TYPE_COMPATIBILITY_CHECKER__).toBe(hostValue)
  })
})

/**
 * 文件用途: 类型兼容性检查机制。
 * 核心逻辑: 验证组件需求、HTTP 配置、字段映射和数据源配置之间的类型兼容。
 * 关键注意事项: 兼容判断会影响配置保存和运行前校验，宽松规则需要配套测试说明。
 * 重构建议: 将不同数据源类型的校验规则插件化，并输出结构化诊断信息。
 */

import type {
  HttpConfig,
  HttpParameter,
  PathParameter,
  ComponentDataRequirement,
  DataSourceRequirement,
  FieldRequirement,
  StaticParamRequirement,
  ValidationResult,
  DataType,
  ParamType,
  ValueMode,
  FieldType
} from './types/unified-types'

/**
 * 兼容性检查结果
 */
export interface CompatibilityCheckResult extends ValidationResult {
  /** 兼容性级别 */
  level: 'compatible' | 'warning' | 'incompatible'
  /** 检查类型 */
  checkType: string
  /** 影响的组件/字段 */
  affectedItems: string[]
  /** 建议的修复方案 */
  suggestions: string[]
  /** 检查时间戳 */
  timestamp: number
}

/**
 * 类型映射兼容性
 */
interface TypeMappingCompatibility {
  /** 源类型 */
  sourceType: string
  /** 目标类型 */
  targetType: string
  /** 是否兼容 */
  isCompatible: boolean
  /** 是否需要转换 */
  needsConversion: boolean
  /** 转换函数名 */
  conversionFunction?: string
}

type CompatibilityDiagnostics = Pick<CompatibilityCheckResult, 'errors' | 'warnings' | 'affectedItems' | 'suggestions'>

/**
 * 类型兼容性检查器
 */
export class TypeCompatibilityChecker {
  private static instance: TypeCompatibilityChecker | null = null

  /** 类型映射表 */
  private typeMappingTable = new Map<string, TypeMappingCompatibility[]>()

  /** 检查历史记录 */
  private checkHistory: CompatibilityCheckResult[] = []

  private constructor() {
    this.initializeTypeMappingTable()
  }

  public static getInstance(): TypeCompatibilityChecker {
    if (!this.instance) {
      this.instance = new TypeCompatibilityChecker()
    }
    return this.instance
  }

  private createDiagnostics(): CompatibilityDiagnostics {
    return {
      errors: [],
      warnings: [],
      affectedItems: [],
      suggestions: []
    }
  }

  private recordResult(result: CompatibilityCheckResult): CompatibilityCheckResult {
    this.checkHistory.push({
      ...result,
      errors: [...result.errors],
      warnings: [...result.warnings],
      affectedItems: [...result.affectedItems],
      suggestions: [...result.suggestions]
    })
    return result
  }

  private buildCompatibilityResult(checkType: string, diagnostics: CompatibilityDiagnostics): CompatibilityCheckResult {
    const level =
      diagnostics.errors.length > 0 ? 'incompatible' : diagnostics.warnings.length > 0 ? 'warning' : 'compatible'

    return this.recordResult({
      valid: diagnostics.errors.length === 0,
      errors: diagnostics.errors,
      warnings: diagnostics.warnings,
      level,
      checkType,
      affectedItems: diagnostics.affectedItems,
      suggestions: diagnostics.suggestions,
      timestamp: Date.now()
    })
  }

  private buildCompatibilityFailure(
    checkType: string,
    errorMessage: string,
    affectedItem: string | string[],
    suggestion: string
  ): CompatibilityCheckResult {
    return this.recordResult({
      valid: false,
      errors: [errorMessage],
      warnings: [],
      level: 'incompatible',
      checkType,
      affectedItems: Array.isArray(affectedItem) ? affectedItem : [affectedItem],
      suggestions: [suggestion],
      timestamp: Date.now()
    })
  }

  private mergeCompatibilityResult(
    diagnostics: CompatibilityDiagnostics,
    result: Pick<CompatibilityCheckResult, 'errors' | 'warnings' | 'affectedItems' | 'suggestions'>,
    affectedItem?: string
  ): void {
    diagnostics.errors.push(...result.errors)
    diagnostics.warnings.push(...result.warnings)
    diagnostics.affectedItems.push(...(affectedItem ? [affectedItem] : result.affectedItems))
    diagnostics.suggestions.push(...result.suggestions)
  }

  /**
   * 初始化类型映射表
   */
  private initializeTypeMappingTable(): void {
    // 基础类型兼容性映射
    const basicTypeMappings: TypeMappingCompatibility[] = [
      // string类型映射
      { sourceType: 'string', targetType: 'string', isCompatible: true, needsConversion: false },
      {
        sourceType: 'string',
        targetType: 'number',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'stringToNumber'
      },
      {
        sourceType: 'string',
        targetType: 'boolean',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'stringToBoolean'
      },

      // number类型映射
      { sourceType: 'number', targetType: 'number', isCompatible: true, needsConversion: false },
      {
        sourceType: 'number',
        targetType: 'string',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'numberToString'
      },
      {
        sourceType: 'number',
        targetType: 'boolean',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'numberToBoolean'
      },

      // boolean类型映射
      { sourceType: 'boolean', targetType: 'boolean', isCompatible: true, needsConversion: false },
      {
        sourceType: 'boolean',
        targetType: 'string',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'booleanToString'
      },
      {
        sourceType: 'boolean',
        targetType: 'number',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'booleanToNumber'
      },

      // json类型映射
      { sourceType: 'json', targetType: 'json', isCompatible: true, needsConversion: false },
      { sourceType: 'json', targetType: 'object', isCompatible: true, needsConversion: false },
      { sourceType: 'object', targetType: 'json', isCompatible: true, needsConversion: false },

      // any类型映射（兼容所有类型）
      {
        sourceType: 'any',
        targetType: 'string',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'anyToString'
      },
      {
        sourceType: 'any',
        targetType: 'number',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'anyToNumber'
      },
      {
        sourceType: 'any',
        targetType: 'boolean',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'anyToBoolean'
      },
      { sourceType: 'any', targetType: 'object', isCompatible: true, needsConversion: false },
      { sourceType: 'any', targetType: 'array', isCompatible: true, needsConversion: false }
    ]

    this.typeMappingTable.set('basic', basicTypeMappings)

    // HTTP参数类型映射
    const httpParameterMappings: TypeMappingCompatibility[] = [
      { sourceType: 'path', targetType: 'query', isCompatible: false, needsConversion: false },
      {
        sourceType: 'query',
        targetType: 'header',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'queryToHeader'
      },
      {
        sourceType: 'header',
        targetType: 'query',
        isCompatible: true,
        needsConversion: true,
        conversionFunction: 'headerToQuery'
      }
    ]

    this.typeMappingTable.set('httpParameter', httpParameterMappings)
  }

  /**
   * 检查HTTP配置兼容性
   */
  public checkHttpConfigCompatibility(config: HttpConfig): CompatibilityCheckResult {
    const diagnostics = this.createDiagnostics()
    const { errors, warnings, suggestions, affectedItems } = diagnostics

    try {
      // 1. 检查URL格式兼容性
      const urlCheck = this.checkUrlFormat(config.url)
      if (!urlCheck.isValid) {
        errors.push(`URL格式错误: ${urlCheck.error}`)
        affectedItems.push('url')
        suggestions.push('请使用标准的HTTP URL格式')
      }

      // 2. 检查HTTP方法兼容性
      const methodCheck = this.checkHttpMethod(config.method)
      if (!methodCheck.isValid) {
        errors.push(`HTTP方法不支持: ${config.method}`)
        affectedItems.push('method')
        suggestions.push('请使用标准的HTTP方法: GET, POST, PUT, DELETE, PATCH')
      }

      // 3. 检查参数类型兼容性
      if (config.params) {
        const paramsCheck = this.checkHttpParametersCompatibility(config.params, 'query')
        this.mergeCompatibilityResult(diagnostics, paramsCheck)
      }

      // 4. 检查请求头兼容性
      if (config.headers) {
        const headersCheck = this.checkHttpParametersCompatibility(config.headers, 'header')
        this.mergeCompatibilityResult(diagnostics, headersCheck)
      }

      // 5. 检查路径参数兼容性
      if (config.pathParameter) {
        const pathParamCheck = this.checkPathParameterCompatibility(config.pathParameter, config.url)
        if (!pathParamCheck.valid) {
          this.mergeCompatibilityResult(diagnostics, pathParamCheck, 'pathParameter')
        }
      }
      if (config.pathParams) {
        const pathParamsCheck = this.checkHttpParametersCompatibility(config.pathParams, 'path', 'pathParams')
        this.mergeCompatibilityResult(diagnostics, pathParamsCheck)
      }

      // 6. 检查超时值合理性
      if (config.timeout && (config.timeout < 1000 || config.timeout > 300000)) {
        warnings.push(`超时时间设置可能不合理: ${config.timeout}ms`)
        affectedItems.push('timeout')
        suggestions.push('建议超时时间设置在1秒到5分钟之间')
      }

      return this.buildCompatibilityResult('HttpConfig', diagnostics)
    } catch (error) {
      return this.buildCompatibilityFailure(
        'HttpConfig',
        `HTTP配置兼容性检查失败: ${error.message}`,
        'entire_config',
        '请检查HTTP配置格式是否正确'
      )
    }
  }

  /**
   * 检查组件数据需求兼容性
   */
  public checkComponentDataRequirementCompatibility(requirement: ComponentDataRequirement): CompatibilityCheckResult {
    const diagnostics = this.createDiagnostics()
    const { errors, warnings, suggestions, affectedItems } = diagnostics

    try {
      // 1. 检查组件ID格式
      if (!requirement.componentId || typeof requirement.componentId !== 'string') {
        errors.push('组件ID无效或缺失')
        affectedItems.push('componentId')
        suggestions.push('请提供有效的组件ID字符串')
      }

      // 2. 检查静态参数兼容性
      if (requirement.staticParams) {
        for (let i = 0; i < requirement.staticParams.length; i++) {
          const param = requirement.staticParams[i]
          const paramCheck = this.checkStaticParamCompatibility(param, i)
          if (!paramCheck.valid) {
            this.mergeCompatibilityResult(diagnostics, { ...paramCheck, affectedItems: [] }, `staticParams[${i}]`)
          }
        }
      }

      // 3. 检查数据源需求兼容性
      if (requirement.dataSources && requirement.dataSources.length > 0) {
        for (let i = 0; i < requirement.dataSources.length; i++) {
          const dataSource = requirement.dataSources[i]
          const dataSourceCheck = this.checkDataSourceRequirementCompatibility(dataSource, i)
          if (!dataSourceCheck.valid) {
            this.mergeCompatibilityResult(diagnostics, { ...dataSourceCheck, affectedItems: [] }, `dataSources[${i}]`)
          }
        }
      } else {
        warnings.push('组件没有定义任何数据源需求')
        suggestions.push('考虑添加数据源需求以支持动态数据')
      }

      // 4. 检查字段命名冲突
      const fieldNames = new Set<string>()
      if (requirement.staticParams) {
        requirement.staticParams.forEach(param => {
          if (fieldNames.has(param.key)) {
            errors.push(`静态参数字段名重复: ${param.key}`)
            affectedItems.push(`staticParams.${param.key}`)
            suggestions.push(`请为字段 ${param.key} 使用唯一的名称`)
          }
          fieldNames.add(param.key)
        })
      }

      return this.buildCompatibilityResult('ComponentDataRequirement', diagnostics)
    } catch (error) {
      return this.buildCompatibilityFailure(
        'ComponentDataRequirement',
        `组件数据需求兼容性检查失败: ${error.message}`,
        'entire_requirement',
        '请检查组件数据需求格式是否正确'
      )
    }
  }

  /**
   * 检查数据类型兼容性
   */
  public checkDataTypeCompatibility(
    sourceType: DataType | FieldType,
    targetType: DataType | FieldType
  ): CompatibilityCheckResult {
    const basicMappings = this.typeMappingTable.get('basic') || []
    const mapping = basicMappings.find(m => m.sourceType === sourceType && m.targetType === targetType)

    if (!mapping) {
      return this.buildCompatibilityFailure(
        'DataTypeCompatibility',
        `不支持从 ${sourceType} 到 ${targetType} 的类型转换`,
        [sourceType, targetType],
        `考虑使用兼容的数据类型或添加类型转换逻辑`
      )
    }

    const diagnostics = this.createDiagnostics()
    diagnostics.affectedItems.push(sourceType, targetType)

    if (mapping.needsConversion) {
      diagnostics.warnings.push(`需要进行类型转换: ${sourceType} -> ${targetType}`)
      diagnostics.suggestions.push(`使用转换函数: ${mapping.conversionFunction}`)
    }
    return this.recordResult({
      valid: mapping.isCompatible,
      errors: [],
      warnings: diagnostics.warnings,
      level: mapping.isCompatible ? (diagnostics.warnings.length > 0 ? 'warning' : 'compatible') : 'incompatible',
      checkType: 'DataTypeCompatibility',
      affectedItems: diagnostics.affectedItems,
      suggestions: diagnostics.suggestions,
      timestamp: Date.now()
    })
  }

  /**
   * 批量检查兼容性
   */
  public batchCompatibilityCheck(
    items: Array<{
      type: 'httpConfig' | 'componentRequirement' | 'dataType'
      data: any
      id: string
    }>
  ): CompatibilityCheckResult {
    const diagnostics = this.createDiagnostics()

    for (const item of items) {
      let result: CompatibilityCheckResult

      switch (item.type) {
        case 'httpConfig':
          result = this.checkHttpConfigCompatibility(item.data)
          break
        case 'componentRequirement':
          result = this.checkComponentDataRequirementCompatibility(item.data)
          break
        case 'dataType':
          result = this.checkDataTypeCompatibility(item.data.sourceType, item.data.targetType)
          break
        default:
          continue
      }

      if (!result.valid) {
        diagnostics.errors.push(...result.errors.map(error => `[${item.id}] ${error}`))
      }
      diagnostics.warnings.push(...result.warnings.map(warning => `[${item.id}] ${warning}`))
      diagnostics.suggestions.push(...result.suggestions.map(suggestion => `[${item.id}] ${suggestion}`))
      diagnostics.affectedItems.push(...result.affectedItems.map(affectedItem => `${item.id}.${affectedItem}`))
    }

    return this.buildCompatibilityResult('BatchCompatibilityCheck', diagnostics)
  }

  /**
   * URL格式检查
   */
  private checkUrlFormat(url: string): { isValid: boolean; error?: string } {
    if (!url || typeof url !== 'string') {
      return { isValid: false, error: 'URL不能为空' }
    }

    try {
      // 检查是否是相对路径（允许）
      if (url.startsWith('/')) {
        return { isValid: true }
      }

      // 检查是否是完整URL
      const urlObj = new URL(url)
      if (!['http:', 'https:'].includes(urlObj.protocol)) {
        return { isValid: false, error: '只支持HTTP和HTTPS协议' }
      }

      return { isValid: true }
    } catch {
      return { isValid: false, error: 'URL格式不正确' }
    }
  }

  /**
   * HTTP方法检查
   */
  private checkHttpMethod(method: string): { isValid: boolean } {
    const validMethods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS']
    return { isValid: validMethods.includes(method.toUpperCase()) }
  }

  /**
   * HTTP参数兼容性检查
   */
  private checkHttpParametersCompatibility(
    parameters: HttpParameter[],
    paramType: ParamType,
    pathPrefix = 'params'
  ): CompatibilityCheckResult {
    const errors: string[] = []
    const warnings: string[] = []
    const suggestions: string[] = []
    const affectedItems: string[] = []

    for (let i = 0; i < parameters.length; i++) {
      const param = parameters[i]

      // 检查必填字段
      if (!param.key) {
        errors.push(`参数[${i}]缺少key字段`)
        affectedItems.push(`${pathPrefix}[${i}].key`)
        suggestions.push(`为参数[${i}]提供有效的key值`)
      }

      // 检查数据类型
      if (!['string', 'number', 'boolean', 'json'].includes(param.dataType)) {
        errors.push(`参数[${i}]数据类型无效: ${param.dataType}`)
        affectedItems.push(`${pathPrefix}[${i}].dataType`)
        suggestions.push(`使用有效的数据类型: string, number, boolean, json`)
      }

      // 检查参数类型匹配
      if (param.paramType && param.paramType !== paramType) {
        warnings.push(`参数[${i}]类型不匹配，期望: ${paramType}, 实际: ${param.paramType}`)
        affectedItems.push(`${pathPrefix}[${i}].paramType`)
        suggestions.push(`统一参数类型为: ${paramType}`)
      }

      // 检查动态参数的变量名
      if (param.isDynamic && !param.variableName) {
        errors.push(`动态参数[${i}]缺少variableName`)
        affectedItems.push(`${pathPrefix}[${i}].variableName`)
        suggestions.push(`为动态参数[${i}]提供变量名`)
      }

      // 检查值模式兼容性
      if (param.valueMode && !['manual', 'dropdown', 'property', 'component'].includes(param.valueMode)) {
        errors.push(`参数[${i}]值模式无效: ${param.valueMode}`)
        affectedItems.push(`${pathPrefix}[${i}].valueMode`)
        suggestions.push(`使用有效的值模式: manual, dropdown, property, component`)
      }
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      level: errors.length > 0 ? 'incompatible' : warnings.length > 0 ? 'warning' : 'compatible',
      checkType: `HttpParameter_${paramType}`,
      affectedItems,
      suggestions,
      timestamp: Date.now()
    }
  }

  /**
   * 路径参数兼容性检查
   */
  private checkPathParameterCompatibility(pathParam: PathParameter, url: string): CompatibilityCheckResult {
    const errors: string[] = []
    const warnings: string[] = []
    const suggestions: string[] = []

    // 检查URL是否包含路径参数占位符
    if (pathParam.isDynamic && !url.includes('{') && !url.includes(':')) {
      warnings.push('URL中没有找到路径参数占位符，但参数被标记为动态')
      suggestions.push('请在URL中添加路径参数占位符，如: /api/device/{id}')
    }

    // 检查数据类型
    if (!['string', 'number', 'boolean', 'json'].includes(pathParam.dataType)) {
      errors.push(`路径参数数据类型无效: ${pathParam.dataType}`)
      suggestions.push('使用有效的数据类型: string, number, boolean, json')
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      level: errors.length > 0 ? 'incompatible' : warnings.length > 0 ? 'warning' : 'compatible',
      checkType: 'PathParameter',
      affectedItems: ['pathParameter'],
      suggestions,
      timestamp: Date.now()
    }
  }

  /**
   * 静态参数兼容性检查
   */
  private checkStaticParamCompatibility(
    param: StaticParamRequirement,
    index: number
  ): ValidationResult & { suggestions: string[] } {
    const errors: string[] = []
    const warnings: string[] = []
    const suggestions: string[] = []

    if (!param.key) {
      errors.push('静态参数缺少key字段')
      suggestions.push('提供唯一的参数键名')
    }

    if (!param.name) {
      errors.push('静态参数缺少name字段')
      suggestions.push('提供参数显示名称')
    }

    if (!['string', 'number', 'boolean', 'object', 'array'].includes(param.type)) {
      errors.push(`静态参数类型无效: ${param.type}`)
      suggestions.push('使用有效的类型: string, number, boolean, object, array')
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      suggestions
    }
  }

  /**
   * 数据源需求兼容性检查
   */
  private checkDataSourceRequirementCompatibility(
    requirement: DataSourceRequirement,
    index: number
  ): ValidationResult & { suggestions: string[] } {
    const errors: string[] = []
    const warnings: string[] = []
    const suggestions: string[] = []

    if (!requirement.key) {
      errors.push('数据源需求缺少key字段')
      suggestions.push('提供唯一的数据源键名')
    }

    if (!requirement.supportedTypes || requirement.supportedTypes.length === 0) {
      errors.push('数据源需求没有定义支持的类型')
      suggestions.push('至少定义一种支持的数据源类型')
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      suggestions
    }
  }

  /**
   * 获取检查历史
   */
  public getCheckHistory(): CompatibilityCheckResult[] {
    return this.checkHistory.map(result => ({
      ...result,
      errors: [...result.errors],
      warnings: [...result.warnings],
      affectedItems: [...result.affectedItems],
      suggestions: [...result.suggestions]
    }))
  }

  /**
   * 清除检查历史
   */
  public clearCheckHistory(): void {
    this.checkHistory = []
  }

  /**
   * 获取类型映射统计
   */
  public getTypeMappingStats() {
    const stats = new Map<string, number>()

    for (const [category, mappings] of this.typeMappingTable) {
      stats.set(category, mappings.length)
    }

    return {
      categories: Array.from(this.typeMappingTable.keys()),
      totalMappings: Array.from(stats.values()).reduce((sum, count) => sum + count, 0),
      categoryStats: Object.fromEntries(stats)
    }
  }
}

/**
 * 导出单例实例
 */
export const typeCompatibilityChecker = TypeCompatibilityChecker.getInstance()

/**
 * 便捷的兼容性检查方法
 */
export function checkHttpConfigCompatibility(config: HttpConfig): CompatibilityCheckResult {
  return typeCompatibilityChecker.checkHttpConfigCompatibility(config)
}

export function checkComponentDataRequirementCompatibility(
  requirement: ComponentDataRequirement
): CompatibilityCheckResult {
  return typeCompatibilityChecker.checkComponentDataRequirementCompatibility(requirement)
}

export function checkDataTypeCompatibility(
  sourceType: DataType | FieldType,
  targetType: DataType | FieldType
): CompatibilityCheckResult {
  return typeCompatibilityChecker.checkDataTypeCompatibility(sourceType, targetType)
}

const TYPE_COMPATIBILITY_DEBUG_GLOBAL = '__TYPE_COMPATIBILITY_CHECKER__'

/**
 * 按需安装调试接口。模块导入本身不会污染宿主全局；返回的清理函数仅撤销本次安装。
 */
export function installTypeCompatibilityDebugGlobal(target: typeof globalThis = globalThis): () => void {
  const debugTarget = target as typeof globalThis & Record<string, unknown>
  const hadOwnValue = Object.prototype.hasOwnProperty.call(debugTarget, TYPE_COMPATIBILITY_DEBUG_GLOBAL)
  const previousValue = debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL]
  const debugApi = {
    checker: typeCompatibilityChecker,
    checkHttpConfig: checkHttpConfigCompatibility,
    checkComponentRequirement: checkComponentDataRequirementCompatibility,
    checkDataType: checkDataTypeCompatibility,
    getStats: () => typeCompatibilityChecker.getTypeMappingStats(),
    getHistory: () => typeCompatibilityChecker.getCheckHistory(),
    clearHistory: () => typeCompatibilityChecker.clearCheckHistory()
  }

  debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL] = debugApi

  return () => {
    if (debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL] !== debugApi) {
      return
    }

    if (hadOwnValue) {
      debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL] = previousValue
    } else {
      delete debugTarget[TYPE_COMPATIBILITY_DEBUG_GLOBAL]
    }
  }
}

