function passthrough(className: string) {
  return defineComponent({
    props: ['value', 'modelValue', 'show', 'visible'],
    emits: [
      'click',
      'input',
      'update:value',
      'update:show',
      'update:visible',
      'change',
      'confirm',
      'cancel',
      'parameters-generated',
      'parameters-selected',
      'parameters-updated'
    ],
    setup(props, { emit, slots }) {
      return () =>
        h(
          'div',
          {
            class: className,
            onClick: () => emit('click')
          },
          [slots.header?.(), slots.default?.(), slots.action?.(), slots.footer?.()]
        )
    }
  })
}

