/**
 * 文件用途: data-architecture 运行时数据项获取器。
 * 核心逻辑: 解析 HTTP 参数、绑定路径、缓存键、请求 payload、脚本执行和 fallback，再返回组件运行时数据。
 * 关键注意事项: cache key、绑定路径恢复、参数别名和脚本前后处理是 persisted 配置兼容热点。
 * 重构建议: 按 json/http/websocket/script fetch strategy 拆分，并先锁定缓存键与绑定路径测试。
 */
import { defaultScriptEngine } from '@/core/script-engine'
import type { HttpConfig, HttpParameter, PathParameter } from '@/core/data-architecture/types/http-config'
import { request } from '@/service/request'
import { useEditorStore } from '@/components/visual-editor/store/editor'
import {
  buildHttpRequestPlan as buildResolvedHttpRequestPlan,
  collectHttpRequestParameterInputs,
  type HttpRequestPlan,
  type ResolvedHttpParameter
} from './DataItemFetcherRequestPlan'
import {
  logHttpParametersLifecycle,
  resolveHttpParameterValue,
  validateParameterBindingPaths
} from './DataItemFetcherParameterResolution'

type HttpExecutionContext = {
  preparedConfig: HttpDataItemConfig
  requestPlan: HttpRequestPlan
}

type HttpRequestDispatcher = () => Promise<any>

export type DataItem =
  | {
      type: 'json'
      config: JsonDataItemConfig
    }
  | {
      type: 'http'
      config: HttpDataItemConfig
    }
  | {
      type: 'websocket'
      config: WebSocketDataItemConfig
    }
  | {
      type: 'script'
      config: ScriptDataItemConfig
    }

export interface JsonDataItemConfig {
  jsonString: string
}

// Runtime HTTP configs intentionally accept both current editor fields and saved aliases.
export interface HttpDataItemConfig {
  url: string
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH'
  headers?: Record<string, string>
  body?: any
  timeout?: number

  addressType?: 'internal' | 'external'
  selectedInternalAddress?: string
  enableParams?: boolean

  pathParameter?: PathParameter
  pathParams?: HttpParameter[]
  params?: HttpParameter[]
  parameters?: HttpParameter[]

  preRequestScript?: string
  postResponseScript?: string
}

export type HttpDataItemConfigV2 = HttpConfig

export interface WebSocketDataItemConfig {
  url: string
  protocols?: string[]
  reconnectInterval?: number
}

export interface ScriptDataItemConfig {
  script: string
  context?: Record<string, any>
}

export interface UnsupportedDataSourceResult {
  success: false
  unsupported: true
  error: {
    code: 'UNSUPPORTED_DATA_SOURCE'
    message: string
    type: DataItem['type']
  }
}

export interface IDataItemFetcher {
  fetchData(item: DataItem): Promise<any>
  setCurrentComponentId(componentId: string): void
}

export class DataItemFetcher implements IDataItemFetcher {
  private requestCache = new Map<string, Promise<any>>()
  private currentComponentId?: string

  setCurrentComponentId(componentId: string): void {
    this.currentComponentId = componentId
  }

  private async getComponentPropertyValue(bindingPath: string): Promise<any> {
    try {
      const resolvedBinding = this.resolveComponentBinding(bindingPath)
      if (!resolvedBinding) {
        return undefined
      }

      const { componentId, propertyPath } = resolvedBinding
      const configurationValue = await this.readComponentValueFromConfiguration(componentId, propertyPath)
      if (configurationValue !== undefined) {
        return configurationValue
      }

      const targetComponent = this.findEditorStoreComponent(componentId)
      return targetComponent ? this.getNestedProperty(targetComponent.properties, propertyPath) : undefined
    } catch (error) {
      console.error('[DataItemFetcher] Component property binding failed:', error)
      return undefined
    }
  }

  private resolveComponentBinding(bindingPath: string): { componentId: string; propertyPath: string } | null {
    if (!bindingPath || typeof bindingPath !== 'string' || !bindingPath.includes('.')) {
      return null
    }

    const parts = bindingPath.split('.')
    const propertyPath = parts.slice(1).join('.')
    const componentId = this.resolveBindingComponentId(parts[0])
    if (!componentId || !propertyPath) {
      return null
    }

    return { componentId, propertyPath }
  }

  private resolveBindingComponentId(componentId: string): string | undefined {
    if (componentId !== '__CURRENT_COMPONENT__') {
      return componentId
    }
    return this.currentComponentId
  }

  private async readComponentValueFromConfiguration(componentId: string, propertyPath: string): Promise<any> {
    try {
      const { configurationIntegrationBridge } = await import(
        '@/components/visual-editor/configuration/ConfigurationIntegrationBridge'
      )
      const latestConfig = this.getPreferredConfiguration(componentId, configurationIntegrationBridge)
      if (!latestConfig) {
        return undefined
      }
      return this.resolveFromConfiguration(latestConfig, propertyPath)
    } catch {
      return undefined
    }
  }

  private getPreferredConfiguration(componentId: string, configurationIntegrationBridge: any): any {
    const directConfig = configurationIntegrationBridge.getConfiguration(componentId)
    if (directConfig || !this.currentComponentId || this.currentComponentId === componentId) {
      return directConfig
    }
    return configurationIntegrationBridge.getConfiguration(this.currentComponentId)
  }

  private findEditorStoreComponent(componentId: string): any {
    const editorStore = useEditorStore()
    const exactMatch = editorStore.nodes?.find((node) => node.id === componentId)
    if (exactMatch) {
      return exactMatch
    }

    const fuzzyMatch = editorStore.nodes?.find((node) => node.id.includes(componentId) || componentId.includes(node.id))
    if (fuzzyMatch) {
      return fuzzyMatch
    }

    if (!this.currentComponentId) {
      return undefined
    }
    return editorStore.nodes?.find((node) => node.id === this.currentComponentId)
  }

  private resolveFromConfiguration(latestConfig: any, propertyPath: string): any {
    if (propertyPath.startsWith('customize.')) {
      const actualPath = propertyPath.replace('customize.', '')
      return this.firstDefined(
        this.getNestedProperty(latestConfig.component, actualPath),
        this.getNestedProperty(latestConfig.base, actualPath)
      )
    }

    if (propertyPath.startsWith('base.')) {
      const actualPath = propertyPath.replace('base.', '')
      return this.firstDefined(
        this.getNestedProperty(latestConfig.base, actualPath),
        this.getNestedProperty(latestConfig.component, actualPath)
      )
    }

    if (propertyPath.startsWith('component.')) {
      const actualPath = propertyPath.replace('component.', '')
      return this.firstDefined(
        this.getNestedProperty(latestConfig.component, actualPath),
        this.getNestedProperty(latestConfig.base, actualPath)
      )
    }

    return this.firstDefined(
      this.getNestedProperty(latestConfig.base, propertyPath),
      this.getNestedProperty(latestConfig.component, propertyPath)
    )
  }

  private firstDefined(...values: any[]): any {
    return values.find(
      (value) => value !== undefined && value !== null && !(typeof value === 'string' && value.trim() === '')
    )
  }

  private formatError(error: unknown): string {
    return error instanceof Error ? error.message : String(error)
  }

  private toLoggableError(error: unknown): unknown {
    return error instanceof Error ? error.message : error
  }

  private logFetcherError(scope: string, details: Record<string, unknown>): void {
    console.error(`[DataItemFetcher] ${scope}:`, details)
  }

  private getNestedProperty(obj: any, path: string): any {
    if (!obj || !path) return undefined

    const keys = path.split('.')
    let current = obj

    for (const key of keys) {
      if (current && typeof current === 'object' && key in current) {
        current = current[key]
      } else {
        return undefined
      }
    }

    return current
  }

  private async resolveParameterValue(param: HttpParameter): Promise<any> {
    return resolveHttpParameterValue(param, (bindingPath) => this.getComponentPropertyValue(bindingPath))
  }

  async fetchData(item: DataItem): Promise<any> {
    try {
      return await this.fetchByDataItemType(item)
    } catch (error) {
      this.logFetcherError('fetchData failed', {
        type: item.type,
        error: this.toLoggableError(error)
      })
      return {}
    }
  }

  private async fetchByDataItemType(item: DataItem): Promise<any> {
    switch (item.type) {
      case 'json':
        return await this.fetchJsonData(item.config)
      case 'http':
        return await this.fetchHttpData(item.config)
      case 'websocket':
        return await this.fetchWebSocketData(item.config)
      case 'script':
        return await this.fetchScriptData(item.config)
      default:
        return {}
    }
  }

  private async fetchJsonData(config: JsonDataItemConfig): Promise<any> {
    try {
      return JSON.parse(config.jsonString)
    } catch (error) {
      this.logFetcherError('JSON data source parse failed', {
        error: this.formatError(error)
      })
      return {}
    }
  }

  private async fetchHttpData(config: HttpDataItemConfig): Promise<any> {
    const executionContext = await this.buildExecutionContext(config)
    return await this.fetchHttpDataWithCache(executionContext)
  }

  private async buildExecutionContext(config: HttpDataItemConfig): Promise<HttpExecutionContext> {
    const preparedConfig = { ...config }
    await this.prepareHttpConfigForExecution(preparedConfig)

    return {
      preparedConfig,
      requestPlan: await this.buildHttpRequestPlan(preparedConfig)
    }
  }

  private async fetchHttpDataWithCache(executionContext: HttpExecutionContext): Promise<any> {
    const { preparedConfig, requestPlan } = executionContext
    const requestPromise = this.getOrCreateHttpRequestPromise(executionContext)
    return await this.normalizeHttpResponse(preparedConfig, await requestPromise)
  }

  private getOrCreateHttpRequestPromise(executionContext: HttpExecutionContext): Promise<any> {
    // requestCache only de-duplicates in-flight requests; it is not a durable response cache.
    // The key must stay aligned with the fully resolved request plan after compatibility aliases and scripts run.
    const requestKey = this.generateRequestKey(executionContext.requestPlan)
    const existingRequest = this.requestCache.get(requestKey)
    if (existingRequest) {
      return existingRequest
    }

    const requestPromise = this.executeHttpRequest(executionContext.preparedConfig, executionContext.requestPlan)
    const trackedPromise = requestPromise.finally(() => {
      if (this.requestCache.get(requestKey) === trackedPromise) {
        this.requestCache.delete(requestKey)
      }
    })
    this.requestCache.set(requestKey, trackedPromise)
    return trackedPromise
  }

  private async prepareHttpConfigForExecution(config: HttpDataItemConfig): Promise<void> {
    logHttpParametersLifecycle(config, 'before request')
    validateParameterBindingPaths(config)
    logHttpParametersLifecycle(config, 'after validation')
    await this.applyPreRequestScript(config)
    logHttpParametersLifecycle(config, 'before parameter handling')
  }

  private async buildHttpRequestPlan(config: HttpDataItemConfig): Promise<HttpRequestPlan> {
    const resolvedParameters = await this.resolveHttpRequestParameters(config)
    return buildResolvedHttpRequestPlan(config, resolvedParameters)
  }

  private async resolveHttpRequestParameters(config: HttpDataItemConfig): Promise<ResolvedHttpParameter[]> {
    const resolvedParameters: ResolvedHttpParameter[] = []
    for (const parameterInput of collectHttpRequestParameterInputs(config)) {
      resolvedParameters.push({
        ...parameterInput,
        resolvedValue: await this.resolveParameterValue(parameterInput.param)
      })
    }
    return resolvedParameters
  }

  private async applyPreRequestScript(config: HttpDataItemConfig): Promise<void> {
    if (!config.preRequestScript) {
      return
    }

    try {
      const scriptResult = await defaultScriptEngine.execute(config.preRequestScript, {
        config
      })
      if (scriptResult.success && scriptResult.data) {
        Object.assign(config, scriptResult.data)
      }
    } catch (error) {
      console.error('[DataItemFetcher] Pre-request script failed:', error)
    }
  }

  private async executeHttpRequest(config: HttpDataItemConfig, requestPlan: HttpRequestPlan): Promise<any> {
    try {
      logHttpParametersLifecycle(config, 'before send')
      return await this.dispatchHttpRequest(config, requestPlan)
    } catch (error) {
      this.logFetcherError('fetchHttpData failed', {
        url: config.url,
        method: config.method,
        error: this.toLoggableError(error)
      })
      return {}
    }
  }

  private async dispatchHttpRequest(config: HttpDataItemConfig, requestPlan: HttpRequestPlan): Promise<any> {
    const dispatcher = this.getHttpRequestDispatcher(config, requestPlan)
    return await dispatcher()
  }

  private getHttpRequestDispatcher(
    config: HttpDataItemConfig,
    requestPlan: HttpRequestPlan
  ): HttpRequestDispatcher {
    const dispatchers: Record<HttpRequestPlan['method'], HttpRequestDispatcher> = {
      GET: () => request.get(requestPlan.finalUrl, requestPlan.requestConfig),
      POST: () => request.post(requestPlan.finalUrl, requestPlan.requestBody, requestPlan.requestConfig),
      PUT: () => request.put(requestPlan.finalUrl, requestPlan.requestBody, requestPlan.requestConfig),
      PATCH: () => request.patch(requestPlan.finalUrl, requestPlan.requestBody, requestPlan.requestConfig),
      DELETE: () => request.delete(requestPlan.finalUrl, requestPlan.requestConfig)
    }

    const dispatcher = dispatchers[requestPlan.method]
    if (!dispatcher) {
      throw new Error(`Unsupported HTTP method: ${config.method}`)
    }

    return dispatcher
  }

  private async normalizeHttpResponse(config: HttpDataItemConfig, response: any): Promise<any> {
    return await this.applyPostResponseScript(config, response)
  }

  private async applyPostResponseScript(config: HttpDataItemConfig, response: any): Promise<any> {
    if (!config.postResponseScript) {
      return response
    }

    try {
      const scriptResult = await defaultScriptEngine.execute(config.postResponseScript, { response })
      if (scriptResult.success) {
        return scriptResult.data !== undefined ? scriptResult.data : response
      }
    } catch (error) {
      console.error('[DataItemFetcher] Post-response script failed:', error)
    }

    return response
  }

  private generateRequestKey(requestPlan: HttpRequestPlan): string {
    return `http_${requestPlan.keyMaterial}`
  }

  private async fetchWebSocketData(config: WebSocketDataItemConfig): Promise<UnsupportedDataSourceResult> {
    const message = 'WebSocket data sources are not supported by DataItemFetcher fetchData.'
    this.logFetcherError('Unsupported data source', {
      type: 'websocket',
      url: config.url,
      message
    })
    return this.buildUnsupportedDataSourceResult('websocket', message)
  }

  private buildUnsupportedDataSourceResult(
    type: DataItem['type'],
    message: string
  ): UnsupportedDataSourceResult {
    return {
      success: false,
      unsupported: true,
      error: {
        code: 'UNSUPPORTED_DATA_SOURCE',
        message,
        type
      }
    }
  }

  private async fetchScriptData(config: ScriptDataItemConfig): Promise<any> {
    try {
      const result = await defaultScriptEngine.execute(config.script, config.context || {})
      if (!result.success) {
        this.logFetcherError('Script data source failed', {
          error: result.error ?? 'Script execution returned an unsuccessful result.'
        })
        return {}
      }

      // 保留 0、false 和空字符串等有效脚本结果，仅空值回退为空对象。
      return result.data !== null && result.data !== undefined ? result.data : {}
    } catch (error) {
      this.logFetcherError('Script data source failed', {
        error: this.formatError(error)
      })
      return {}
    }
  }
}

/**
 * Runtime HTTP parameter normalization for DataItemFetcher.
 *
 * This file keeps persisted-config compatibility rules, damaged binding-path
 * recovery, and data-type conversion separate from request orchestration.
 */
import type { HttpParameter } from '@/core/data-architecture/types/http-config'
import { convertValue } from '@/core/data-architecture/types/http-config'
import {
  isDamagedComponentBindingPath,
  isValidComponentBindingPath,
  recoverComponentBindingPathFromVariableName,
  resolveRecoverableComponentBindingPath
} from '@/core/data-architecture/utils/binding-path-recovery'

import type { HttpDataItemConfig } from './DataItemFetcher'
import { collectHttpParameters } from './DataItemFetcherRequestPlan'

interface ComponentBoundParameterValue {
  invalidBinding: boolean
  value: any
}

export type ComponentPropertyReader = (bindingPath: string) => Promise<any>

export function logHttpParametersLifecycle(config: HttpDataItemConfig, stage: string): void {
  collectHttpParameters(config).forEach(({ source, param, index }) => {
    if (param.value && typeof param.value === 'string') {
      const isSuspiciousPath = !param.value.includes('.') && param.value.length < 10 && param.variableName
      if (isSuspiciousPath) {
        console.error(`[${source}[${index}]] Suspicious binding path:`, {
          key: param.key,
          value: param.value,
          variableName: param.variableName,
          stage
        })
      }
    }
  })
}

export function validateParameterBindingPaths(config: HttpDataItemConfig): void {
  collectHttpParameters(config).forEach(({ param, index }) => {
    if (param.selectedTemplate === 'component-property-binding' || param.valueMode === 'component') {
      const recoveredPath = resolveRecoverableComponentBindingPath(param.value, param.variableName)
      if (!recoveredPath.isValid) {
        console.error('[DataItemFetcher] Invalid parameter binding path:', {
          index,
          key: param.key,
          value: recoveredPath.bindingPath,
          param
        })
      }
    }
  })
}

export async function resolveHttpParameterValue(
  param: HttpParameter,
  readComponentProperty: ComponentPropertyReader
): Promise<any> {
  const runtimeParam = normalizeRuntimeParameter(param)
  let resolvedValue = runtimeParam.value

  if (shouldResolveComponentBinding(runtimeParam)) {
    const componentBoundValue = await resolveComponentBoundParameterValue(runtimeParam, readComponentProperty)
    if (componentBoundValue.invalidBinding) {
      return componentBoundValue.value
    }
    resolvedValue = componentBoundValue.value
  }

  if (isEmptyParameterValue(resolvedValue)) {
    resolvedValue = resolveEmptyParameterFallback(runtimeParam)
    if (resolvedValue === null) {
      return null
    }
  }

  return convertValue(resolvedValue, runtimeParam.dataType)
}

function normalizeRuntimeParameter(param: HttpParameter): HttpParameter {
  if (detectRuntimeIsDynamic(param) && !param.isDynamic) {
    return { ...param, isDynamic: true }
  }

  return param
}

function detectRuntimeIsDynamic(param: HttpParameter): boolean {
  return Boolean(
    param.valueMode === 'component' ||
      param.selectedTemplate === 'component-property-binding' ||
      (typeof param.value === 'string' &&
        param.value.includes('.') &&
        param.value.split('.').length >= 3 &&
        param.value.length > 10 &&
        !/^\d{1,4}$/.test(param.value)) ||
      (param.variableName &&
        !param.variableName.startsWith('var_') &&
        param.variableName.includes('_') &&
        param.variableName.length > 5)
  )
}

function shouldResolveComponentBinding(param: HttpParameter): boolean {
  return Boolean(
    param.isDynamic || param.selectedTemplate === 'component-property-binding' || param.valueMode === 'component'
  )
}

function normalizeComponentBindingPath(param: HttpParameter): any {
  let bindingPath = param.value

  if (isDamagedComponentBindingPath(bindingPath, param.variableName)) {
    console.error('[DataItemFetcher] Damaged binding path detected:', {
      key: param.key,
      bindingPath,
      variableName: param.variableName
    })
    bindingPath = recoverComponentBindingPathFromVariableName(param.variableName) || bindingPath
  }

  return bindingPath
}

async function resolveComponentBoundParameterValue(
  param: HttpParameter,
  readComponentProperty: ComponentPropertyReader
): Promise<ComponentBoundParameterValue> {
  const bindingPath = normalizeComponentBindingPath(param)

  if (!isValidComponentBindingPath(bindingPath)) {
    return {
      invalidBinding: true,
      value: param.defaultValue ?? null
    }
  }

  const actualValue = await readComponentProperty(bindingPath)
  return {
    invalidBinding: false,
    value: isEmptyParameterValue(actualValue) ? undefined : actualValue
  }
}

function resolveEmptyParameterFallback(param: HttpParameter): any {
  if (param.defaultValue !== undefined && param.defaultValue !== null) {
    return param.defaultValue
  }

  return null
}

function isEmptyParameterValue(value: any): boolean {
  return value === null || value === undefined || value === '' || (typeof value === 'string' && value.trim() === '')
}

/**
 * 文件用途：DataItemFetcher request-plan helper 的 focused 单元测试。
 * 核心逻辑：验证已解析参数如何构建 URL、query、headers、body 和缓存 key。
 * 关键注意事项：这些测试不 mock request wrapper，避免把网络执行细节绑进纯函数测试。
 * 重构建议：新增 legacy/raw 兼容规则时先补这里，再补 DataItemFetcher 行为测试。
 */
import { describe, expect, it } from 'vitest'

import type { HttpParameter } from '@/core/data-architecture/types/http-config'

import type { HttpDataItemConfig } from './DataItemFetcher'
import {
  buildHttpRequestPlan,
  collectHttpRequestParameterInputs,
  type ResolvedHttpParameter
} from './DataItemFetcherRequestPlan'

const httpParam = (overrides: Partial<HttpParameter> = {}): HttpParameter =>
  ({
    key: 'q',
    value: 'value',
    enabled: true,
    isDynamic: false,
    dataType: 'string',
    variableName: '',
    description: 'request param',
    paramType: 'query',
    ...overrides
  }) as HttpParameter

const httpConfig = (overrides: Partial<HttpDataItemConfig>): HttpDataItemConfig =>
  ({
    url: '/api/devices',
    method: 'GET',
    ...overrides
  }) as HttpDataItemConfig

const resolveInputsByValue = (config: HttpDataItemConfig): ResolvedHttpParameter[] =>
  collectHttpRequestParameterInputs(config).map(input => ({
    ...input,
    resolvedValue: input.param.value
  }))

describe('DataItemFetcherRequestPlan', () => {
  it('collects only request-affecting parameter inputs in runtime resolution order', () => {
    const config = httpConfig({
      pathParams: [
        httpParam({ key: 'disabled_path', value: 'ignored', enabled: false, paramType: 'path' }),
        httpParam({ key: 'device_id', value: 'dev-1', paramType: 'path' })
      ],
      pathParameter: httpParam({ key: 'device_id', value: 'stale-path-alias', paramType: 'path' }),
      params: [
        httpParam({ key: 'limit', value: '10' }),
        httpParam({ key: '', value: 'ignored-empty-key' }),
        httpParam({ key: 'disabled', value: 'ignored-disabled', enabled: false })
      ],
      parameters: [
        httpParam({ key: 'page', value: '2', paramType: 'query' }),
        httpParam({ key: 'X-Trace', value: 'trace-1', paramType: 'header' })
      ]
    })

    expect(
      collectHttpRequestParameterInputs(config).map(input => ({
        source: input.source,
        key: input.param.key,
        index: input.index
      }))
    ).toEqual([
      { source: 'pathParams', key: 'device_id', index: 1 },
      { source: 'params', key: 'limit', index: 0 },
      { source: 'parameters', key: 'page', index: 0 },
      { source: 'parameters', key: 'X-Trace', index: 1 }
    ])
  })

  it('builds URL, query params, headers, parsed body, and key material from current schema values', () => {
    const config = httpConfig({
      url: '/api/devices/{device_id}/telemetry',
      method: 'POST',
      timeout: 3000,
      headers: { Authorization: 'Bearer token' },
      body: '{"enabled":true}',
      pathParams: [httpParam({ key: 'device_id', value: 'dev-1', paramType: 'path' })],
      params: [httpParam({ key: 'limit', value: 10, dataType: 'number' })]
    })

    const plan = buildHttpRequestPlan(config, resolveInputsByValue(config))

    expect(plan).toEqual({
      method: 'POST',
      finalUrl: '/api/devices/dev-1/telemetry',
      requestConfig: {
        timeout: 3000,
        headers: { Authorization: 'Bearer token' },
        params: { limit: 10 }
      },
      requestBody: { enabled: true },
      keyMaterial:
        '{"body":{"enabled":true},"headers":{"Authorization":"Bearer token"},"method":"POST","params":{"limit":10},"timeout":3000,"url":"/api/devices/dev-1/telemetry"}'
    })
  })

  it('preserves legacy parameters compatibility without letting ignored aliases affect the cache key', () => {
    const baseConfig = httpConfig({
      url: '/api/device',
      method: 'PUT',
      body: '{not-json',
      headers: { 'X-Trace': 'trace-current' },
      params: [httpParam({ key: 'page', value: 2, dataType: 'number', paramType: 'query' })],
      parameters: [
        httpParam({ key: 'device_id', value: 'dev-legacy', paramType: 'path' }),
        httpParam({ key: 'page', value: 99, dataType: 'number', paramType: 'query' }),
        httpParam({ key: 'X-Trace', value: 'trace-legacy-a', paramType: 'header' }),
        httpParam({ key: 'X-Legacy', value: 'legacy-header', paramType: 'header' })
      ]
    })
    const changedIgnoredAliases = httpConfig({
      ...baseConfig,
      parameters: [
        httpParam({ key: 'device_id', value: 'dev-legacy', paramType: 'path' }),
        httpParam({ key: 'page', value: 100, dataType: 'number', paramType: 'query' }),
        httpParam({ key: 'X-Trace', value: 'trace-legacy-b', paramType: 'header' }),
        httpParam({ key: 'X-Legacy', value: 'legacy-header', paramType: 'header' })
      ]
    })

    const firstPlan = buildHttpRequestPlan(baseConfig, resolveInputsByValue(baseConfig))
    const secondPlan = buildHttpRequestPlan(changedIgnoredAliases, resolveInputsByValue(changedIgnoredAliases))

    expect(firstPlan.finalUrl).toBe('/api/device/dev-legacy')
    expect(firstPlan.requestConfig).toEqual({
      timeout: 10000,
      headers: { 'X-Trace': 'trace-current', 'X-Legacy': 'legacy-header' },
      params: { page: 2 }
    })
    expect(firstPlan.requestBody).toBe('{not-json')
    expect(secondPlan.keyMaterial).toBe(firstPlan.keyMaterial)
  })

  it('uses the persisted pathParameter alias when current pathParams are absent', () => {
    const config = httpConfig({
      url: '/api/devices/{device_id}/telemetry',
      pathParameter: httpParam({ key: '', value: 'dev-legacy', paramType: 'path' })
    })

    const plan = buildHttpRequestPlan(config, resolveInputsByValue(config))

    expect(plan.finalUrl).toBe('/api/devices/dev-legacy/telemetry')
    expect(plan.requestConfig).toEqual({ timeout: 10000 })
  })

  it.each(['__proto__', 'prototype', 'constructor'])('skips the unsafe current query key %s', key => {
    const config = httpConfig({
      params: [
        httpParam({ key: 'safe', value: 'value' }),
        httpParam({ key, value: 'polluted' })
      ]
    })

    const plan = buildHttpRequestPlan(config, resolveInputsByValue(config))

    expect(plan.requestConfig.params).toEqual({ safe: 'value' })
    expect(Object.getPrototypeOf(plan.requestConfig.params!)).toBe(Object.prototype)
  })

  it.each(['__proto__', 'prototype', 'constructor'])('skips the unsafe compatibility header key %s', key => {
    const config = httpConfig({
      parameters: [
        httpParam({ key: 'X-Safe', value: 'value', paramType: 'header' }),
        httpParam({ key, value: 'polluted', paramType: 'header' })
      ]
    })

    const plan = buildHttpRequestPlan(config, resolveInputsByValue(config))

    expect(plan.requestConfig.headers).toEqual({ 'X-Safe': 'value' })
    expect(Object.getPrototypeOf(plan.requestConfig.headers!)).toBe(Object.prototype)
  })
})

/**
 * 文件用途：DataItemFetcher HTTP request plan 的纯构建逻辑。
 * 核心逻辑：在动态参数已经解析后，按 current schema 与 compatibility alias 规则构建 URL、query、header、body 和缓存 key。
 * 关键注意事项：保持 pathParameter、parameters、raw body 与 request wrapper 的历史行为一致。
 * 重构建议：只在这里扩展 request-plan 规则，动态组件取值仍留在 DataItemFetcher。
 */
import type { HttpParameter } from '@/core/data-architecture/types/http-config'

import type { HttpDataItemConfig } from './DataItemFetcher'

export type HttpParameterSource = 'pathParams' | 'pathParameter' | 'params' | 'parameters'

export interface CollectedHttpParameter {
  source: HttpParameterSource
  param: HttpParameter
  index: number
}

export interface ResolvedHttpParameter extends CollectedHttpParameter {
  resolvedValue: any
}

export interface HttpRequestPlan {
  method: string
  finalUrl: string
  requestConfig: {
    timeout: number
    headers?: Record<string, string>
    params?: Record<string, any>
  }
  requestBody: any
  keyMaterial: string
}

export type HttpRequestConfig = HttpRequestPlan['requestConfig']

export function collectHttpParameters(config: HttpDataItemConfig): CollectedHttpParameter[] {
  const allParams: CollectedHttpParameter[] = []

  config.pathParams?.forEach((param, index) => {
    allParams.push({ source: 'pathParams', param, index })
  })

  if (config.pathParameter) {
    allParams.push({ source: 'pathParameter', param: config.pathParameter as HttpParameter, index: 0 })
  }

  config.params?.forEach((param, index) => {
    allParams.push({ source: 'params', param, index })
  })

  config.parameters?.forEach((param, index) => {
    allParams.push({ source: 'parameters', param, index })
  })

  return allParams
}

export function collectHttpRequestParameterInputs(config: HttpDataItemConfig): CollectedHttpParameter[] {
  return [
    ...collectEnabledPathParameters(config),
    ...collectCurrentQueryParameters(config),
    ...collectEnabledCompatibilityParameters(config).map(({ param, index }) => ({
      source: 'parameters' as const,
      param,
      index
    }))
  ]
}

export function buildHttpRequestPlan(
  config: HttpDataItemConfig,
  resolvedParameters: ResolvedHttpParameter[]
): HttpRequestPlan {
  const requestConfig = createBaseHttpRequestConfig(config)
  const queryParams: Record<string, any> = {}
  const currentFinalUrl = applyCurrentPathParameters(config.url, resolvedParameters)

  applyCurrentQueryParameters(queryParams, resolvedParameters)
  const finalUrl = applyCompatibilityParameters(config, currentFinalUrl, queryParams, requestConfig, resolvedParameters)

  if (Object.keys(queryParams).length > 0) {
    requestConfig.params = queryParams
  }

  const method = normalizeHttpMethod(config)
  const requestBody = buildHttpRequestBody(config)

  return {
    method,
    finalUrl,
    requestConfig,
    requestBody,
    keyMaterial: createRequestKeyMaterial(method, finalUrl, requestConfig, requestBody)
  }
}

const FORBIDDEN_REQUEST_KEYS = new Set(['__proto__', 'prototype', 'constructor'])

function isSafeRequestKey(key: unknown): key is string {
  return typeof key === 'string' && key.length > 0 && !FORBIDDEN_REQUEST_KEYS.has(key)
}

function collectEnabledPathParameters(config: HttpDataItemConfig): CollectedHttpParameter[] {
  const currentPathParams =
    config.pathParams
      ?.map((param, index) => ({ source: 'pathParams' as const, param, index }))
      .filter(({ param }) => param.enabled) ?? []

  if (currentPathParams.length > 0) {
    return currentPathParams
  }

  // Saved visual-editor configs may still contain the single pathParameter alias.
  return config.pathParameter
    ? [{ source: 'pathParameter', param: config.pathParameter as HttpParameter, index: 0 }]
    : []
}

function collectCurrentQueryParameters(config: HttpDataItemConfig): CollectedHttpParameter[] {
  return (
    config.params
      ?.map((param, index) => ({ source: 'params' as const, param, index }))
      .filter(({ param }) => param.enabled && isSafeRequestKey(param.key)) ?? []
  )
}

function collectEnabledCompatibilityParameters(
  config: HttpDataItemConfig,
  paramType?: HttpParameter['paramType']
): Array<{ param: HttpParameter; index: number }> {
  return (
    config.parameters
      ?.map((param, index) => ({ param, index }))
      .filter(({ param }) => {
        if (!param.enabled || !param.key) return false
        const effectiveType = param.paramType || 'query'
        if (effectiveType !== 'path' && !isSafeRequestKey(param.key)) return false
        return !paramType || effectiveType === paramType
      }) ?? []
  )
}

function createBaseHttpRequestConfig(config: HttpDataItemConfig): HttpRequestConfig {
  const requestConfig: HttpRequestConfig = {
    timeout: config.timeout || 10000
  }

  if (config.headers) {
    const safeHeaders = Object.fromEntries(Object.entries(config.headers).filter(([key]) => isSafeRequestKey(key)))
    if (Object.keys(safeHeaders).length > 0) {
      requestConfig.headers = safeHeaders
    }
  }

  return requestConfig
}

function applyCurrentPathParameters(initialUrl: string, resolvedParameters: ResolvedHttpParameter[]): string {
  let finalUrl = initialUrl

  for (const { param, resolvedValue } of resolvedParameters.filter(
    ({ source }) => source === 'pathParams' || source === 'pathParameter'
  )) {
    if (hasResolvedPathValue(resolvedValue)) {
      finalUrl = replacePathPlaceholder(finalUrl, param, resolvedValue)
    }
  }

  return finalUrl
}

function applyCurrentQueryParameters(
  queryParams: Record<string, any>,
  resolvedParameters: ResolvedHttpParameter[]
): void {
  for (const { param, resolvedValue } of resolvedParameters.filter(({ source }) => source === 'params')) {
    if (resolvedValue !== null) {
      queryParams[param.key] = resolvedValue
    }
  }
}

function applyCompatibilityParameters(
  config: HttpDataItemConfig,
  initialUrl: string,
  queryParams: Record<string, any>,
  requestConfig: HttpRequestConfig,
  resolvedParameters: ResolvedHttpParameter[]
): string {
  let finalUrl = initialUrl
  const currentQueryKeys = currentQueryParameterKeys(config)
  const currentHeaderKeys = currentHeaderKeysForConfig(config)

  for (const { param, resolvedValue } of resolvedParameters.filter(({ source }) => source === 'parameters')) {
    if (resolvedValue === null) {
      continue
    }

    switch (param.paramType || 'query') {
      case 'path':
        finalUrl = applyCompatibilityPathParameter(config, finalUrl, param, resolvedValue)
        break
      case 'query':
        applyCompatibilityQueryParameter(queryParams, currentQueryKeys, param, resolvedValue)
        break
      case 'header':
        applyCompatibilityHeaderParameter(requestConfig, currentHeaderKeys, param, resolvedValue)
        break
    }
  }

  return finalUrl
}

function applyCompatibilityPathParameter(
  config: HttpDataItemConfig,
  finalUrl: string,
  param: HttpParameter,
  resolvedValue: any
): string {
  if (hasCurrentPathParameters(config) || !hasResolvedPathValue(resolvedValue)) {
    return finalUrl
  }

  const nextUrl = replacePathPlaceholder(finalUrl, param, resolvedValue)
  if (nextUrl !== finalUrl) {
    return nextUrl
  }

  const separator = finalUrl.endsWith('/') ? '' : '/'
  return `${finalUrl}${separator}${String(resolvedValue)}`
}

function applyCompatibilityQueryParameter(
  queryParams: Record<string, any>,
  currentQueryKeys: Set<string>,
  param: HttpParameter,
  resolvedValue: any
): void {
  if (!currentQueryKeys.has(param.key)) {
    queryParams[param.key] = resolvedValue
  }
}

function applyCompatibilityHeaderParameter(
  requestConfig: HttpRequestConfig,
  currentHeaderKeys: Set<string>,
  param: HttpParameter,
  resolvedValue: any
): void {
  requestConfig.headers = requestConfig.headers || {}
  if (!currentHeaderKeys.has(param.key)) {
    requestConfig.headers[param.key] = String(resolvedValue)
  }
}

function hasCurrentPathParameters(config: HttpDataItemConfig): boolean {
  return collectEnabledPathParameters(config).length > 0
}

function currentQueryParameterKeys(config: HttpDataItemConfig): Set<string> {
  return new Set(config.params?.filter(param => param.enabled && param.key).map(param => param.key) ?? [])
}

function currentHeaderKeysForConfig(config: HttpDataItemConfig): Set<string> {
  return new Set(Object.keys(config.headers ?? {}))
}

function replacePathPlaceholder(url: string, param: HttpParameter, resolvedValue: any): string {
  let placeholder = param.key ? `{${param.key}}` : null

  if (!placeholder || placeholder === '{}') {
    placeholder = url.match(/\{([^}]+)\}/)?.[0] ?? null
  }

  return placeholder && url.includes(placeholder) ? url.replace(placeholder, String(resolvedValue)) : url
}

function hasResolvedPathValue(resolvedValue: any): boolean {
  return resolvedValue !== null && String(resolvedValue).trim() !== ''
}

function normalizeHttpMethod(config: HttpDataItemConfig): string {
  return config.method.toUpperCase()
}

function buildHttpRequestBody(config: HttpDataItemConfig): any {
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(config.method) || !config.body) {
    return undefined
  }

  try {
    return typeof config.body === 'string' ? JSON.parse(config.body) : config.body
  } catch {
    return config.body
  }
}

function createRequestKeyMaterial(
  method: string,
  finalUrl: string,
  requestConfig: HttpRequestPlan['requestConfig'],
  requestBody: any
): string {
  return stableStringify({
    method,
    url: finalUrl,
    timeout: requestConfig.timeout,
    headers: requestConfig.headers ?? {},
    params: requestConfig.params ?? {},
    body: requestBody
  })
}

function stableStringify(value: any): string {
  if (Array.isArray(value)) {
    return `[${value.map(item => stableStringify(item)).join(',')}]`
  }

  if (value && typeof value === 'object') {
    return `{${Object.keys(value)
      .sort()
      .map(key => `${JSON.stringify(key)}:${stableStringify(value[key])}`)
      .join(',')}}`
  }

  return JSON.stringify(value)
}

