  widgetId?: string
  data?: any
  timestamp: number
}

/**
 * 编辑器大数据管理器接口
 * 职责：
 * 1. 管理组件树的增删改查
 * 2. 管理画布配置和全局设置
 * 3. 提供数据持久化（保存/加载）
 * 4. 发出数据变更事件，但不直接操作组件配置或运行时数据
 */
export interface IEditorDataManager {
  /**
   * 获取当前编辑器数据
   */
  getCurrentData(): EditorData

  /**
   * 加载编辑器数据
