          {
            sourceId: 'test-source',
            dataItems: [
              {
                item: {
                  type: 'json',
                  config: { jsonString: '{"test": true}' }
                },
                processing: {}
              }
            ],
            mergeStrategy: { type: 'object' }
          }
        ],
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      expect(adapter.detectVersion(v1Config)).toBe('v1.0')
      expect(detectConfigVersion(v1Config)).toBe('v1.0')
    })

    test('检测v2.0配置', () => {
      const v2Config: EnhancedDataSourceConfiguration = {
        componentId: 'test-component',
        version: '2.0.0',
        dataSources: [
          {
            sourceId: 'test-source',
            dataItems: [
              {
                item: {
                  type: 'json',
                  id: 'json-item-1',
                  config: { jsonData: '{"test": true}' }
                },
                processing: {}
              }
            ],
            mergeStrategy: { type: 'object' }
          }
        ],
        dynamicParams: [],
        enhancedFeatures: DEFAULT_ENHANCED_FEATURES,
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      expect(adapter.detectVersion(v2Config)).toBe('v2.0')
      expect(detectConfigVersion(v2Config)).toBe('v2.0')
    })

    test('检测历史v2版本字符串配置', () => {
      const historicalV2Config = {
        componentId: 'test-component',
        version: ' V2.1 ',
        dataSources: [
          {
            sourceId: 'test-source',
            dataItems: [
              {
                item: {
                  type: 'json',
                  config: { jsonData: '{"test": true}' }
                },
                processing: {}
              }
            ],
            mergeStrategy: { type: 'object' }
          }
        ],
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      expect(adapter.detectVersion(historicalV2Config)).toBe('v2.0')
      expect(detectConfigVersion(historicalV2Config)).toBe('v2.0')
    })
  })

  describe('配置适配入口兼容性', () => {
    test('adaptToVersion保留历史v2字符串配置为同版本数据', () => {
      const adapter = createConfigurationAdapter()
      const historicalV2Config = {
        componentId: 'test-component',
        version: 'v2.0',
        dataSources: [
          {
            sourceId: 'test-source',
            dataItems: [
              {
                item: {
                  type: 'json',
                  config: { jsonData: '{"test": true}' }
                },
                processing: {}
              }
            ],
            mergeStrategy: { type: 'object' }
          }
        ],
        dynamicParams: [],
        enhancedFeatures: DEFAULT_ENHANCED_FEATURES,
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      const result = adapter.adaptToVersion(historicalV2Config, 'v2.0')

      expect(result.success).toBe(true)
      expect(result.data).toEqual(historicalV2Config)
      expect(result.data).not.toBe(historicalV2Config)
      expect(result.metadata.sourceVersion).toBe('v2.0')
      expect(result.metadata.targetVersion).toBe('v2.0')
      expect(result.errors).toEqual([])
      expect(result.warnings).toEqual([])
    })
  })

  describe('配置升级测试', () => {
    test('v1升级到v2（JSON数据项）', () => {
      const v1Config: BaseDataSourceConfiguration = {
        componentId: 'test-component',
        dataSources: [
          {
            sourceId: 'json-source',
            dataItems: [
              {
                item: {
                  type: 'json',
                  config: { jsonString: '{"sensor": "temperature", "value": 25.6}' }
                },
                processing: {
                  filterPath: '$.sensor',
                  defaultValue: {}
                }
              }
            ],
            mergeStrategy: { type: 'object' }
          }
