      const dataItem = v2Config.dataSources[0].dataItems[0].item as DataItemConfig
      expect(dataItem.id).toBe('json-source_item_0')
      expect(dataItem.type).toBe('json')
      expect(dataItem.metadata).toMatchObject({
        displayName: 'json数据项',
        description: '从v1.0升级的json数据项',
        enabled: true,
        tags: ['upgraded']
      })

      // 检查JSON配置字段重命名
      const jsonConfig = dataItem.config as EnhancedJsonDataItemConfig
      expect(jsonConfig.jsonData).toBe('{"sensor": "temperature", "value": 25.6}')
      expect(jsonConfig.validation).toEqual({ enableFormat: true, enableStructure: false })
    })

    test('v1升级到v2（HTTP数据项）', () => {
      const v1Config: BaseDataSourceConfiguration = {
        componentId: 'test-component',
        dataSources: [
          {
            sourceId: 'api-source',
            dataItems: [
              {
                item: {
                  type: 'http',
                  config: {
                    url: '/api/v1/telemetry/datas/current',
                    method: 'GET',
                    headers: {
                      Authorization: 'Bearer token123',
                      'Content-Type': 'application/json'
                    },
                    timeout: 5000
                  }
                },
                processing: {}
              }
            ],
            mergeStrategy: { type: 'array' }
          }
        ],
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      const v2Config = upgradeToV2(v1Config)
      const dataItem = v2Config.dataSources[0].dataItems[0].item as DataItemConfig
      const httpConfig = dataItem.config as EnhancedHttpDataItemConfig

      // 检查HTTP配置升级
      expect(httpConfig.url).toBe('/api/v1/telemetry/datas/current')
      expect(httpConfig.method).toBe('GET')
      expect(httpConfig.headers).toHaveLength(2)
      expect(httpConfig.params).toEqual([])
      expect(httpConfig.retry).toEqual({ maxRetries: 3, retryDelay: 1000 })

      // 检查headers格式转换
      expect(httpConfig.headers[0].key).toBe('Authorization')
      expect(httpConfig.headers[0].value).toBe('Bearer token123')
      expect(httpConfig.headers[0].enabled).toBe(true)
      expect(httpConfig.headers[1].key).toBe('Content-Type')
      expect(httpConfig.headers[1].value).toBe('application/json')
    })
  })

  describe('配置降级测试', () => {
    test('v2降级到v1（JSON数据项）', () => {
      const v2Config: EnhancedDataSourceConfiguration = {
        componentId: 'test-component',
        version: '2.0.0',
        dataSources: [
          {
            sourceId: 'json-source',
            dataItems: [
              {
                item: {
                  type: 'json',
                  id: 'json-item-1',
                  config: {
                    jsonData: '{"temperature": 26.5}',
                    validation: { enableFormat: true, enableStructure: false },
                    preprocessing: { removeComments: true, formatOutput: false }
                  },
                  metadata: { displayName: '温度传感器数据', enabled: true }
                },
                processing: { filterPath: '$.temperature' }
              }
            ],
            mergeStrategy: { type: 'object' }
          }
        ],
        dynamicParams: [],
        enhancedFeatures: DEFAULT_ENHANCED_FEATURES,
        metadata: {
          name: '温度监控配置',
          description: '温度传感器数据采集配置'
        },
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      const v1Config = downgradeToV1(v2Config)

      // 检查基本字段保持
      expect(v1Config.componentId).toBe('test-component')
      expect(v1Config.dataSources).toHaveLength(1)

      // 检查数据项降级
      const dataItem = v1Config.dataSources[0].dataItems[0].item
      expect(dataItem.type).toBe('json')

      const jsonConfig = dataItem.config as BaseJsonDataItemConfig
      expect(jsonConfig.jsonString).toBe('{"temperature": 26.5}')

      // 检查v2字段被移除
      expect((v1Config as any).version).toBeUndefined()
      expect((v1Config as any).dynamicParams).toBeUndefined()
      expect((v1Config as any).enhancedFeatures).toBeUndefined()
    })

    test('v2降级到v1（HTTP数据项）', () => {
      const v2Config: EnhancedDataSourceConfiguration = {
        componentId: 'test-component',
        version: '2.0.0',
        dataSources: [
          {
            sourceId: 'api-source',
            dataItems: [
              {
                item: {
                  type: 'http',
                  id: 'http-item-1',
                  config: {
                    url: '/api/v1/telemetry/datas/current',
                    method: 'POST',
                    headers: [
                      { key: 'Authorization', value: 'Bearer token', enabled: true },
                      { key: 'Content-Type', value: 'application/json', enabled: true },
                      { key: 'X-Debug', value: 'true', enabled: false }
                    ],
                    params: [{ key: 'format', value: 'json', enabled: true }],
                    body: { type: 'json', content: { query: 'test' } },
                    timeout: 10000,
                    retry: { maxRetries: 3, retryDelay: 1000 }
                  }
                },
                processing: {}
              }
            ],
            mergeStrategy: { type: 'object' }
          }
        ],
        dynamicParams: [],
        enhancedFeatures: DEFAULT_ENHANCED_FEATURES,
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      const v1Config = downgradeToV1(v2Config)
      const dataItem = v1Config.dataSources[0].dataItems[0].item
      const httpConfig = dataItem.config as BaseHttpDataItemConfig

      // 检查HTTP配置降级
      expect(httpConfig.url).toBe('/api/v1/telemetry/datas/current')
      expect(httpConfig.method).toBe('POST')
      expect(httpConfig.timeout).toBe(10000)
      expect(httpConfig.body).toEqual({ query: 'test' })

      // 检查headers格式转换（只包含enabled的headers）
      expect(httpConfig.headers).toEqual({
        Authorization: 'Bearer token',
        'Content-Type': 'application/json'
        // X-Debug被过滤掉因为enabled: false
      })
    })
  })

  describe('转换一致性验证', () => {
    test('往返转换一致性', () => {
      const adapter = createConfigurationAdapter()

      const originalV1: BaseDataSourceConfiguration = {
        componentId: 'consistency-test',
        dataSources: [
          {
            sourceId: 'test-source',
            dataItems: [
              {
                item: {
                  type: 'json',
                  config: { jsonString: '{"test": "data"}' }
                },
                processing: { filterPath: '$.test' }
              }
            ],
            mergeStrategy: { type: 'object' }
          }
        ],
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      // v1 -> v2 -> v1 往返转换
      const upgradedV2 = adapter.upgradeV1ToV2(originalV1)
      const downgradedV1 = adapter.downgradeV2ToV1(upgradedV2)

      // 验证核心字段一致性
      expect(downgradedV1.componentId).toBe(originalV1.componentId)
      expect(downgradedV1.dataSources.length).toBe(originalV1.dataSources.length)
      expect(downgradedV1.dataSources[0].sourceId).toBe(originalV1.dataSources[0].sourceId)

      // 验证数据项类型和配置一致性
      const originalItem = originalV1.dataSources[0].dataItems[0].item
      const convertedItem = downgradedV1.dataSources[0].dataItems[0].item
      expect(convertedItem.type).toBe(originalItem.type)

      const originalJsonConfig = originalItem.config as BaseJsonDataItemConfig
      const convertedJsonConfig = convertedItem.config as BaseJsonDataItemConfig
      expect(convertedJsonConfig.jsonString).toBe(originalJsonConfig.jsonString)
    })

    test('使用适配器验证转换一致性', () => {
      const adapter = createConfigurationAdapter()

      const original: BaseDataSourceConfiguration = {
        componentId: 'validation-test',
        dataSources: [
          {
            sourceId: 'validation-source',
            dataItems: [
              {
                item: { type: 'json', config: { jsonString: '{}' } },
                processing: {}
              }
            ],
            mergeStrategy: { type: 'object' }
          }
        ],
        createdAt: Date.now(),
        updatedAt: Date.now()
      }

      const upgraded = adapter.upgradeV1ToV2(original)
      const downgraded = adapter.downgradeV2ToV1(upgraded)

      const validation = adapter.validateConversion(original, downgraded)

      expect(validation.valid).toBe(true)
      expect(validation.issues).toHaveLength(0)
    })
  })

  describe('批量转换测试', () => {
    test('批量转换多个配置', () => {
      const adapter = createConfigurationAdapter()

      const configs: BaseDataSourceConfiguration[] = [
        {
          componentId: 'batch-test-1',
          dataSources: [{ sourceId: 'test1', dataItems: [], mergeStrategy: { type: 'object' } }],
          createdAt: Date.now(),
          updatedAt: Date.now()
        },
        {
          componentId: 'batch-test-2',
          dataSources: [{ sourceId: 'test2', dataItems: [], mergeStrategy: { type: 'array' } }],
          createdAt: Date.now(),
          updatedAt: Date.now()
        }
      ]

      const results = adapter.batchConvert(configs, 'v2.0')

      expect(results).toHaveLength(2)
      expect(results[0].success).toBe(true)
      expect(results[1].success).toBe(true)
      expect(results[0].data?.version).toBe('2.0.0')
      expect(results[1].data?.version).toBe('2.0.0')
    })
  })
})

/**
 * 文件用途: 定义增强版数据架构配置和适配相关类型。
 * 核心逻辑: 扩展基础配置模型，描述泛型数据项、版本化配置和适配器输入输出。
 * 关键注意事项: 该文件承接新旧配置兼容，修改版本字段或适配类型需要配套迁移测试。
 * 重构建议: 将版本管理、适配器契约和运行时配置拆分，减少增强类型的集中膨胀。
 */
/**
 * 增强版数据架构类型定义
 * 基于现有架构扩展，保持向后兼容性
 *
 * 设计目标：
 * 1. 泛型化数据项配置，支持扩展
 * 2. 保持现有类型系统100%兼容
 * 3. 为动态参数系统预留接口
 * 4. 支持配置版本管理和自动适配
 */

// ==================== 基础类型导入 ====================
import type { ProcessingConfig } from '@/core/data-architecture/executors/DataItemProcessor'

import type { MergeStrategy } from '@/core/data-architecture/executors/DataSourceMerger'

import type { DataSourceConfiguration as BaseDataSourceConfiguration } from '../executors/MultiLayerExecutorChain'

// ==================== 泛型化数据项配置 ====================

/**
 * 判定输入是否为可在其上读取属性的对象（不含 null 与数组语义约束）。
 */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null
}

/**
 * 泛型化数据项配置基础接口
 * 支持任意类型的配置结构扩展
 */
export interface DataItemConfig<T = unknown> {
  /** 数据项类型标识 */
  type: string

  /** 数据项唯一标识符 */
  id: string

  /** 类型特定的配置参数 */
  config: T

  /** 数据处理配置（复用现有ProcessingConfig） */
  processing?: ProcessingConfig

  /** 数据项元数据 */
  metadata?: DataItemMetadata
}

/**
 * 数据项元数据接口
 * 用于存储额外的配置信息和状态
 */
export interface DataItemMetadata {
  /** 数据项显示名称 */
  displayName?: string

  /** 数据项描述 */
  description?: string

  /** 创建时间 */
  createdAt?: number

  /** 最后更新时间 */
  lastUpdated?: number

  /** 数据项启用状态 */
  enabled?: boolean

  /** 自定义标签 */
  tags?: string[]
}

// ==================== 具体数据项类型实现 ====================

/**
 * JSON数据项配置（增强版）
 * 保持与现有JsonDataItemConfig的兼容性
 */
export interface EnhancedJsonDataItemConfig {
  /** JSON数据内容 */
  jsonData: string

  /** 数据验证选项 */
  validation?: {
    /** 是否启用JSON格式验证 */
    enableFormat: boolean
    /** 是否启用数据结构验证 */
    enableStructure: boolean
    /** JSON Schema（可选） */
    schema?: unknown
  }

  /** 数据预处理选项 */
  preprocessing?: {
    /** 是否去除注释 */
    removeComments: boolean
    /** 是否格式化输出 */
    formatOutput: boolean
  }
}

/**
 * HTTP数据项配置（增强版）
 * 为动态参数系统预留扩展接口
 */
export interface EnhancedHttpDataItemConfig {
  /** 请求URL（支持模板语法 {{paramName}}） */
  url: string

  /** HTTP请求方法 */
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH'

  /** 请求头配置（数组格式，支持动态参数） */
  headers: HttpHeader[]

  /** URL参数配置（新增，支持动态参数） */
  params: HttpParam[]

  /** 请求体配置 */
  body?: HttpBody

  /** 请求超时时间（毫秒） */
  timeout?: number

  /** 请求前脚本（预留） */
  preRequestScript?: string

  /** 响应后脚本（预留） */
  responseScript?: string

  /** 重试配置 */
  retry?: {
    /** 最大重试次数 */
    maxRetries: number
    /** 重试间隔（毫秒） */
    retryDelay: number
  }
}

/**
 * HTTP头部配置
 * 支持静态值和动态参数两种模式
 */
export interface HttpHeader {
  /** 头部字段名 */
  key: string

  /** 头部字段值（静态时为实际值，动态时为种子值） */
  value: string

  /** 是否启用此头部 */
  enabled: boolean

  /** 是否为动态参数 */
  isDynamic: boolean

  /** 数据类型，用于类型转换和验证 */
  dataType: 'string' | 'number' | 'boolean' | 'json'

  /** 自动生成的变量名（格式：http_${key}） */
  variableName: string

  /** 参数说明（动态参数必填，静态参数可选） */
  description?: string
}

/**
 * HTTP参数配置
 * 支持静态值和动态参数两种模式
 */
export interface HttpParam {
  /** 参数名 */
  key: string

  /** 参数值（静态时为实际值，动态时为种子值） */
  value: string

  /** 是否启用此参数 */
  enabled: boolean

  /** 是否为动态参数 */
  isDynamic: boolean

  /** 数据类型，用于类型转换和验证 */
  dataType: 'string' | 'number' | 'boolean' | 'json'

  /** 自动生成的变量名（格式：http_${key}） */
  variableName: string

  /** 参数说明（动态参数必填，静态参数可选） */
  description?: string
}

/**
 * HTTP请求体配置
 */
export interface HttpBody {
  /** 请求体类型 */
  type: 'json' | 'form' | 'text' | 'binary'

  /** 请求体内容 */
  content: unknown

  /** 内容类型 */
  contentType?: string
}

// ==================== 动态参数系统与占位符解析 ====================

/**
 * 动态参数定义（预留接口）
 * 用于HTTP动态参数系统
 */
export interface DynamicParam {
  /** 参数名称 */
  name: string

  /** 参数类型 */
  type: 'string' | 'number' | 'boolean' | 'object'

  /** 当前参数值 */
  currentValue: unknown

  /** 种子值 */
  exampleValue?: unknown

  /** 参数描述 */
  description?: string

  /** 是否必填参数 */
  required?: boolean

  /** 参数验证规则 */
  validation?: {
    /** 最小值/最小长度 */
    min?: number
    /** 最大值/最大长度 */
    max?: number
    /** 正则表达式 */
    pattern?: string
    /** 枚举值 */
    enum?: unknown[]
  }
}

/**
 * 占位符配置接口
 * 用于{{variableName}}占位符系统
 */
export interface PlaceholderConfig {
  /** 占位符名称（不包含{{}}） */
  name: string

  /** 占位符当前值 */
  value: unknown

  /** 数据类型 */
  dataType: 'string' | 'number' | 'boolean' | 'json'

  /** 是否为必填占位符 */
  required: boolean

  /** 占位符描述 */
  description?: string

  /** 默认值 */
  defaultValue?: unknown

  /** 验证规则 */
  validation?: PlaceholderValidationRule
}

/**
 * 占位符验证规则
 */
export interface PlaceholderValidationRule {
  /** 最小值/最小长度 */
  min?: number

  /** 最大值/最大长度 */
  max?: number

