/**
 * 文件用途: 定义 HTTP 数据源配置、参数、认证和响应处理相关类型。
 * 核心逻辑: 为 HTTP 模板、配置表单和执行器提供统一的请求配置结构。
 * 关键注意事项: 类型字段会参与配置持久化和导入导出，兼容字段应谨慎删除。
 * 重构建议: 将传输层配置、认证配置和编辑器展示配置拆成独立类型模块。
 */
/**
 * HTTP配置类型定义（完善版）
 * 基于SUBTASK-008完善版文档设计
 */

/**
 * HTTP参数统一接口
 * 支持路径参数、查询参数、请求头参数的统一管理
 */
export interface HttpParameter {
  /** 参数键名 */
  key: string

  /** 参数值 - 种子值，类型与dataType匹配 */
  value: string | number | boolean

  /** 默认值 - 当value为空时使用的回退值 */
  defaultValue?: string | number | boolean

  /** 是否启用此参数 */
  enabled: boolean

  /** 是否为动态参数 */
  isDynamic: boolean

  /** 数据类型，用于类型转换和验证 */
  dataType: 'string' | 'number' | 'boolean' | 'json'

  /** 动态时自动生成：var_ + key的snake_case */
  variableName: string

  /** 参数说明，必填 */
  description: string

  /** 参数类型：路径参数直接拼接到URL后，查询参数作为query，请求头参数作为header */
  paramType?: 'path' | 'query' | 'header'

  /** 参数值模式：手动输入、下拉选择、属性绑定等 */
  valueMode?: string

  /** 选中的模板ID */
