/**
 * HTTP参数统一接口（标准化版本）
 * 整合了enhanced-types.ts和http-config.ts中的重复定义
 */
export interface HttpParameter {
  /** 参数键名 */
  key: string

  /** 参数值 - 种子值，类型与dataType匹配 */
  value: string | number | boolean

  /** 默认值 - 当value为空或绑定失败时使用的回退值 */
  defaultValue?: string | number | boolean

  /** 是否启用此参数 */
  enabled: boolean

  /** 是否为动态参数 */
  isDynamic: boolean

  /** 数据类型，用于类型转换和验证 */
  dataType: DataType

  /** 动态时自动生成的变量名 */
  variableName: string

  /** 参数说明，建议必填 */
  description: string

  /** 参数类型：路径参数、查询参数、请求头参数 */
  paramType: ParamType

  /** 参数值模式：手动输入、下拉选择、属性绑定等 */
  valueMode?: ValueMode

  /** 选中的模板ID */
  selectedTemplate?: string
}

/**
 * HTTP请求头配置 - 当前持久化配置仍使用的参数别名
 */
export interface HttpHeader extends HttpParameter {
  paramType: 'header'
}

/**
 * HTTP查询参数配置 - 当前持久化配置仍使用的参数别名
 */
export interface HttpParam extends HttpParameter {
  paramType: 'query'
}

/**
 * HTTP路径参数配置 - 当前持久化配置仍使用的参数别名
 */
export interface HttpPathParam extends HttpParameter {
  paramType: 'path'
  /** 路径参数名（不带大括号），如 'device_id' */
  key: string
  /** 在URL中的占位符格式，如 '{device_id}' */
  placeholder: string
}

/**
 * 路径参数简化配置
 * 只支持单个路径参数，直接拼接到URL后
 */
export interface PathParameter {
  /** 参数值 - 种子值，类型与dataType匹配 */
  value: string | number | boolean

  /** 默认值 - 当value为空时使用的回退值 */
  defaultValue?: string | number | boolean

  /** 是否为动态参数 */
  isDynamic: boolean

  /** 数据类型，用于类型转换和验证 */
  dataType: DataType

  /** 动态时自动生成的变量名 */
  variableName: string

  /** 参数说明 */
  description: string

  /** 参数值模式：手动输入、下拉选择、属性绑定等 */
  valueMode?: ValueMode

  /** 选中的模板ID */
  selectedTemplate?: string

  /** 参数键名（用于内部标识） */
  key?: string

  /** 是否启用（用于向后兼容） */
  enabled?: boolean
}

/**
 * HTTP请求体配置
 */
export interface HttpBody {
  /** 请求体类型 */
  type: 'json' | 'form' | 'text' | 'binary'

  /** 请求体内容 */
  content: any

  /** 内容类型 */
  contentType?: string
}

/**
 * HTTP配置接口（统一标准版本）
 * 整合了多个文件中的HTTP配置定义
 */
export interface HttpConfig {
  /** 基础请求URL（路径参数会拼接到此URL后） */
  url: string

  /** HTTP方法 */
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH'

  /** 超时时间（毫秒） */
  timeout: number

  /** 地址类型：内部地址还是外部地址 */
  addressType?: AddressType

  /** 选中的内部地址值（当addressType为internal时使用） */
  selectedInternalAddress?: string

  /** 是否启用传参（用于内部地址的路径参数配置） */
  enableParams?: boolean

  /** 路径参数配置数组（新格式，支持多个参数） */
  pathParams?: EnhancedParameter[]

  /** 路径参数（可选，单个参数直接拼接到URL后） */
  pathParameter?: PathParameter

  /** 查询参数配置 */
  params: HttpParam[]

  /** 请求头配置 */
  headers: HttpHeader[]

  /** 请求体（可选） */
  body?: string | HttpBody

  /** 请求前处理脚本（可选） */
  preRequestScript?: string

  /** 响应后处理脚本（可选） */
  postResponseScript?: string

  /** 重试配置 */
  retry?: {
    /** 最大重试次数 */
    maxRetries: number
    /** 重试间隔（毫秒） */
    retryDelay: number
  }

  // ========== 已保存配置格式字段 ==========
  /** 已保存配置的统一参数数组 */
  parameters?: HttpParameter[]
}

