/**
 * 文件用途: binding path recovery 的测试文件。
 * 核心逻辑: 构造局部 fixture、mock 依赖并断言公开契约和关键边界行为。
 * 关键注意事项: 测试应覆盖可观察行为，避免绑定无关实现细节导致重构成本过高。
 * 重构建议: 补充历史配置、异常输入和回归场景，提升重构保护力度。
 */

import { describe, expect, it } from 'vitest'

import {
  isDamagedComponentBindingPath,
  isValidComponentBindingPath,
  recoverComponentBindingPathFromVariableName,
  resolveRecoverableComponentBindingPath
} from './binding-path-recovery'

describe('binding-path-recovery', () => {
  it('recovers component binding paths from persisted variable names', () => {
    expect(recoverComponentBindingPathFromVariableName('chartA_deviceId')).toBe('chartA.base.deviceId')
    expect(recoverComponentBindingPathFromVariableName('target-card_styles.color')).toBe('target-card.base.styles.color')
    expect(recoverComponentBindingPathFromVariableName('missingSeparator')).toBeNull()
  })

  it('classifies damaged short binding-path fragments without accepting arbitrary invalid paths', () => {
    expect(isDamagedComponentBindingPath('123', 'chartA_deviceId')).toBe(true)
    expect(isDamagedComponentBindingPath('missing-dot-but-long', 'chartA_deviceId')).toBe(false)
    expect(isValidComponentBindingPath('chartA.base.deviceId')).toBe(true)
    expect(isValidComponentBindingPath('123')).toBe(false)
  })

  it('uses strict editor validation while preserving empty binding clears', () => {
    expect(isValidComponentBindingPath('', { allowEmpty: true, strict: true })).toBe(true)
    expect(isValidComponentBindingPath('card.base.undefined', { strict: true })).toBe(false)

    expect(resolveRecoverableComponentBindingPath('bad', 'targetCard_color', { strict: true })).toEqual({
      bindingPath: 'targetCard.base.color',
      isValid: true,
      recovered: true,
      wasDamaged: true
    })
  })
})

/**
 * 文件用途: 绑定路径校验与恢复工具。
 * 核心逻辑: 识别损坏的组件绑定路径，校验路径格式，并从变量名恢复候选路径。
 * 关键注意事项: 恢复规则影响历史配置兼容，过度宽松可能掩盖真实配置错误。
 * 重构建议: 把严格校验、宽松识别和恢复策略拆成可配置规则集。
 */

export interface BindingPathValidationOptions {
  allowEmpty?: boolean
  strict?: boolean
}

export interface BindingPathRecoveryResult {
  bindingPath: string | null
  isValid: boolean
  recovered: boolean
  wasDamaged: boolean
}

const STRICT_COMPONENT_BINDING_PATH_PATTERN = /^[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+\.[a-zA-Z0-9_.-]+$/

export function recoverComponentBindingPathFromVariableName(variableName?: string | null): string | null {
  if (!variableName || typeof variableName !== 'string') {
    return null
  }

  const lastUnderscoreIndex = variableName.lastIndexOf('_')

  if (lastUnderscoreIndex <= 0 || lastUnderscoreIndex === variableName.length - 1) {
    return null
  }

  const componentId = variableName.substring(0, lastUnderscoreIndex)
  const propertyName = variableName.substring(lastUnderscoreIndex + 1)

  return `${componentId}.base.${propertyName}`
}

export function isDamagedComponentBindingPath(bindingPath: unknown, variableName?: string | null): bindingPath is string {
  return (
    Boolean(bindingPath) &&
    typeof bindingPath === 'string' &&
    !bindingPath.includes('.') &&
    bindingPath.length < 10 &&
    recoverComponentBindingPathFromVariableName(variableName) !== null
  )
}

export function isValidComponentBindingPath(
  bindingPath: unknown,
  options: BindingPathValidationOptions = {}
): bindingPath is string {
  if (bindingPath === '' && options.allowEmpty) {
    return true
  }

  if (typeof bindingPath !== 'string' || !bindingPath.includes('.')) {
    return false
  }

  if (!options.strict) {
    return true
  }

  return (
    bindingPath.split('.').length >= 3 &&
    bindingPath.length > 10 &&
    !/^\d{1,4}$/.test(bindingPath) &&
    !bindingPath.includes('undefined') &&
    !bindingPath.includes('null') &&
    STRICT_COMPONENT_BINDING_PATH_PATTERN.test(bindingPath)
  )
}

export function resolveRecoverableComponentBindingPath(
  bindingPath: unknown,
  variableName?: string | null,
  options: BindingPathValidationOptions = {}
): BindingPathRecoveryResult {
  const wasDamaged = isDamagedComponentBindingPath(bindingPath, variableName)

  if (isValidComponentBindingPath(bindingPath, options)) {
    return {
      bindingPath,
      isValid: true,
      recovered: false,
      wasDamaged
    }
  }

  const recoveredPath = recoverComponentBindingPathFromVariableName(variableName)

  if (recoveredPath && isValidComponentBindingPath(recoveredPath, options)) {
    return {
      bindingPath: recoveredPath,
      isValid: true,
      recovered: true,
      wasDamaged
    }
  }

  return {
    bindingPath: typeof bindingPath === 'string' ? bindingPath : null,
    isValid: false,
    recovered: false,
    wasDamaged
  }
}

import { smartDeepClone } from '@/utils/deep-clone'

export interface ConfigurationExportProcessingResult {
  processedConfig: any
  dependencies: string[]
  statistics: {
    dataSourceCount: number
    interactionCount: number
    httpConfigCount: number
  }
  dependencyMapping: Record<string, { usage: string[]; required: boolean }>
}

function processStringValue(
  value: string,
  currentComponentId: string,
  currentComponentPlaceholder: string,
  dependencies: Set<string>
): string {
  if (value.includes(currentComponentId)) {
    return value.replace(new RegExp(currentComponentId, 'g'), currentComponentPlaceholder)
  }

  const componentIdPattern = /comp_[a-zA-Z0-9_-]+/g
  const matches = value.match(componentIdPattern)
  if (matches) {
    matches.forEach((match) => {
      if (match !== currentComponentId) {
        dependencies.add(match)
      }
    })
  }

  return value
}

function processComponentId(
  componentId: string,
  currentComponentId: string,
  currentComponentPlaceholder: string,
  dependencies: Set<string>
): string {
  if (componentId === currentComponentId) {
    return currentComponentPlaceholder
  }

  dependencies.add(componentId)
  return componentId
}

function isComponentIdField(key: string): boolean {
  const componentIdFields = ['componentId', 'targetComponentId', 'sourceComponentId']
  return componentIdFields.includes(key)
}

function findComponentUsage(componentId: string, config: any): string[] {
  const usage: string[] = []

  const findUsage = (obj: any, path: string = ''): void => {
    if (typeof obj === 'string' && obj.includes(componentId)) {
      usage.push(path || 'root')
      return
    }

    if (Array.isArray(obj)) {
      obj.forEach((item, index) => {
        findUsage(item, `${path}[${index}]`)
      })
      return
    }

    if (typeof obj === 'object' && obj !== null) {
      for (const [key, value] of Object.entries(obj)) {
        const currentPath = path ? `${path}.${key}` : key
        findUsage(value, currentPath)
      }
    }
  }

  findUsage(config)
  return usage
}

function buildDependencyMapping(dependencies: string[], processedConfig: any) {
  const mapping: Record<string, { usage: string[]; required: boolean }> = {}

  dependencies.forEach((depId) => {
    mapping[depId] = {
      usage: findComponentUsage(depId, processedConfig),
      required: true
    }
  })

  return mapping
}

export function processConfigurationForExport(
  config: any,
  currentComponentId: string,
  currentComponentPlaceholder: string
): ConfigurationExportProcessingResult {
  const dependencies = new Set<string>()
  let httpConfigCount = 0
  let interactionCount = 0

  const processValue = (obj: any, path: string = ''): any => {
    if (obj === null || obj === undefined) {
      return obj
    }

    if (typeof obj === 'string') {
      return processStringValue(obj, currentComponentId, currentComponentPlaceholder, dependencies)
    }

    if (Array.isArray(obj)) {
      return obj.map((item, index) => processValue(item, `${path}[${index}]`))
    }

    if (typeof obj === 'object') {
      const processed: any = {}

      for (const [key, value] of Object.entries(obj)) {
        const currentPath = path ? `${path}.${key}` : key

        if (key === 'responses' && Array.isArray(value)) {
          interactionCount += (value as any[]).length
        }
        if (key === 'httpConfigData' || (key === 'type' && value === 'http')) {
          httpConfigCount++
        }

        if (isComponentIdField(key) && typeof value === 'string') {
          processed[key] = processComponentId(value, currentComponentId, currentComponentPlaceholder, dependencies)
        } else {
          processed[key] = processValue(value, currentPath)
        }
      }

      return processed
    }

    return obj
  }

  const processedConfig = processValue(smartDeepClone(config))
  const dependencyList = Array.from(dependencies)

  return {
    processedConfig,
    dependencies: dependencyList,
    statistics: {
      dataSourceCount: config.dataSource?.dataSources?.length || 0,
      interactionCount,
      httpConfigCount
    },
    dependencyMapping: buildDependencyMapping(dependencyList, processedConfig)
  }
}

export interface RestorePlaceholderOptions {
  normalizeArray?: (value: any[], targetComponentId: string) => any[]
  normalizeObject?: (value: Record<string, any>, targetComponentId: string) => any
}

export function formatImportExportError(error: unknown, fallback = 'Unknown import/export error'): string {
  if (error instanceof Error) return error.message
  if (typeof error === 'string') return error
  if (error === null || error === undefined) return fallback

  try {
    return JSON.stringify(error)
  } catch (_stringifyError) {
    return String(error)
  }
}

function replaceCurrentComponentPlaceholder(value: string, placeholder: string, targetComponentId: string): string {
  if (value === placeholder) {
    return targetComponentId
  }

  if (!value.includes(placeholder)) {
    return value
  }

  return value.replace(new RegExp(placeholder, 'g'), targetComponentId)
}

export function restorePlaceholderDeep(
  value: any,
  placeholder: string,
  targetComponentId: string,
  options: RestorePlaceholderOptions = {}
): any {
  if (value === null || value === undefined) {
    return value
  }

  if (typeof value === 'string') {
    return replaceCurrentComponentPlaceholder(value, placeholder, targetComponentId)
  }

  if (Array.isArray(value)) {
    const restoredArray = value.map((item) => restorePlaceholderDeep(item, placeholder, targetComponentId, options))
    return options.normalizeArray ? options.normalizeArray(restoredArray, targetComponentId) : restoredArray
  }

  if (typeof value === 'object') {
    const restoredObject = Object.fromEntries(
      Object.entries(value).map(([key, childValue]) => [
        key,
        restorePlaceholderDeep(childValue, placeholder, targetComponentId, options)
      ])
    )
    return options.normalizeObject ? options.normalizeObject(restoredObject, targetComponentId) : restoredObject
  }

  return value
}

import type { ExportedConfiguration, ImportPreview, ImportResult } from './ConfigurationImportExport'
import {
  checkConfigurationConflicts,
  checkConfigurationDependencies,
  createMissingDependencyWarnings,
  getConfigurationImportConflictMessages,
  getMissingDependencyFailure,
  getOverwriteConflictMessages,
  getOverwriteFailure,
  processConfigurationForImport,
  type DependencyCheckResult
} from './configurationImportProcessing'

export type ConfigurationImportOptions = {
  overwriteExisting?: boolean
  skipMissingDependencies?: boolean
  availableComponents?: any[]
}

export type ConfigurationImportPlan = {
  configurationConflicts: ReturnType<typeof checkConfigurationConflicts>
  conflictMessages: string[]
  dependencyCheck: DependencyCheckResult
  effectiveMissingDependencies: string[]
  failure?: ImportResult
  processedConfig: any
  warnings: string[]
}

export const planConfigurationImport = (
  config: ExportedConfiguration,
  targetComponentId: string,
  configurationManager: any,
  currentComponentPlaceholder: string,
  options: ConfigurationImportOptions = {}
): ConfigurationImportPlan => {
  const dependencyCheck = checkConfigurationDependencies(
    config,
    targetComponentId,
    configurationManager,
    options.availableComponents
  )

  const { processedConfig, missingDependencies } = processConfigurationForImport(
    config,
    targetComponentId,
    currentComponentPlaceholder
  )

  const effectiveMissingDependencies = Array.from(new Set([...dependencyCheck.missing, ...missingDependencies]))
  const warnings = createMissingDependencyWarnings(effectiveMissingDependencies, options)

  const dependencyFailure = getMissingDependencyFailure(effectiveMissingDependencies, options, warnings)
  if (dependencyFailure) {
    const configurationConflicts = checkConfigurationConflicts(config, targetComponentId, configurationManager)
    const conflictMessages = getConfigurationImportConflictMessages(
      effectiveMissingDependencies,
      dependencyCheck.conflicts,
      getOverwriteConflictMessages(configurationConflicts)
    )
    return {
      configurationConflicts,
      conflictMessages,
      dependencyCheck,
      effectiveMissingDependencies,
      failure: dependencyFailure,
      processedConfig,
      warnings
    }
  }

  const configurationConflicts = checkConfigurationConflicts(config, targetComponentId, configurationManager)
  const overwriteConflicts = getOverwriteConflictMessages(configurationConflicts)
  const overwriteFailure = getOverwriteFailure(configurationConflicts, overwriteConflicts, options, warnings)
  const conflictMessages = getConfigurationImportConflictMessages(
    effectiveMissingDependencies,
    dependencyCheck.conflicts,
    overwriteConflicts
  )

  return {
    configurationConflicts,
    conflictMessages,
    dependencyCheck,
    effectiveMissingDependencies,
    failure: overwriteFailure,
    processedConfig,
    warnings
  }
}

export const buildConfigurationImportPreviewFromPlan = (
  config: ExportedConfiguration,
  plan: ConfigurationImportPlan
): ImportPreview => ({
  basicInfo: {
    version: config.version,
    exportTime: config.exportTime,
    componentType: config.componentType || config.metadata?.componentType || '',
    exportSource: config.metadata?.exportSource || 'AetherLink IoT'
  },
  statistics: {
    dataSourceCount: config.metadata?.statistics?.dataSourceCount || 0,
    interactionCount: config.metadata?.statistics?.interactionCount || 0,
    httpConfigCount: config.metadata?.statistics?.httpConfigCount || 0
  },
  dependencies: plan.dependencyCheck.found,
  conflicts: plan.conflictMessages
})

import type { ExportedConfiguration, ImportPreview, ImportResult } from './ConfigurationImportExport'
import { formatImportExportError, restorePlaceholderDeep } from './configurationImportExportShared'

export type ConfigurationSection = 'dataSource' | 'component' | 'interaction'

export interface ConfigurationManagerLike {
  getConfiguration?: (componentId: string, section?: string) => any
  updateConfiguration?: (componentId: string, section: ConfigurationSection, data: any) => void | Promise<void>
  updateConfigurationSection?: (componentId: string, section: ConfigurationSection, data: any) => void | Promise<void>
}

export interface DependencyCheckResult {
  found: string[]
  missing: string[]
  conflicts: string[]
}

export interface ConfigurationConflictResult {
  dataSource: boolean
  component: boolean
  interaction: boolean
  error?: string
}

export function validateConfigurationFormat(config: any): boolean {
  return !!(config && config.version && config.exportTime && config.metadata && config.data)
}

export function parseConfigurationInput(configJson: string | ExportedConfiguration): ExportedConfiguration {
  const config = typeof configJson === 'string' ? JSON.parse(configJson) : configJson

  if (!validateConfigurationFormat(config)) {
    throw new Error('Invalid configuration format')
  }

  return config
}

function getAvailableComponentIds(
  targetComponentId: string,
  configurationManager: any,
  availableComponents?: any[]
): Set<string> {
  const ids = new Set<string>([targetComponentId])

  if (Array.isArray(availableComponents)) {
    availableComponents.forEach((component) => {
      const id =
        typeof component === 'string'
          ? component
          : component?.id || component?.componentId || component?.widgetId || component?.value
      if (typeof id === 'string') {
        ids.add(id)
      }
    })
  }

  const managerCandidates = [
    configurationManager?.store?.nodes,
    configurationManager?.nodes,
    configurationManager?.getNodes?.(),
    configurationManager?.getAllComponents?.()
  ]

  managerCandidates.forEach((candidate) => {
    if (!Array.isArray(candidate)) {
      return
    }

    candidate.forEach((component) => {
      const id = component?.id || component?.componentId || component?.widgetId || component?.value
      if (typeof id === 'string') {
        ids.add(id)
      }
    })
  })

  return ids
}

export function checkConfigurationDependencies(
  config: ExportedConfiguration,
  targetComponentId: string,
  configurationManager: any,
  availableComponents?: any[]
): DependencyCheckResult {
  const dependencies = config.metadata.dependencies || []
  const availableIds = getAvailableComponentIds(targetComponentId, configurationManager, availableComponents)

  const found = dependencies.filter((dep) => availableIds.has(dep))
  const missing = dependencies.filter((dep) => !availableIds.has(dep))
  const duplicateDependencies = dependencies.filter((dep, index) => dependencies.indexOf(dep) !== index)
  const conflicts = Array.from(new Set(duplicateDependencies)).map((dep) => `重复依赖组件: ${dep}`)

  return { found, missing, conflicts }
}

export function checkConfigurationConflicts(
  config: ExportedConfiguration,
  targetComponentId: string,
  configurationManager: ConfigurationManagerLike
): ConfigurationConflictResult {
  try {
    const existingConfig = configurationManager?.getConfiguration?.(targetComponentId)

    if (!existingConfig || !configurationManager) {
      return {
        dataSource: false,
        component: false,
        interaction: false
      }
    }

    return {
      dataSource: !!(
        existingConfig?.dataSource?.dataSources?.length && config.data.dataSourceConfiguration?.dataSources?.length
      ),
      component: !!(
        existingConfig?.component?.properties &&
        Object.keys(existingConfig.component.properties).length &&
        config.data.componentConfiguration?.properties &&
        Object.keys(config.data.componentConfiguration.properties).length
      ),
      interaction: !!(
        existingConfig?.interaction &&
        Object.keys(existingConfig.interaction).length &&
        config.data.interactionConfiguration &&
        Object.keys(config.data.interactionConfiguration).length
      )
    }
  } catch (error) {
    console.error('[ConfigurationImporter] Conflict detection failed:', error)
    return {
      dataSource: false,
      component: false,
      interaction: false,
      error: formatImportExportError(error)
    }
  }
}

export function getOverwriteConflictMessages(conflicts: ConfigurationConflictResult): string[] {
  const messages: string[] = []
  if (conflicts.dataSource) messages.push('数据源配置冲突')
  if (conflicts.component) messages.push('组件配置冲突')
  if (conflicts.interaction) messages.push('交互配置冲突')
  if (conflicts.error) messages.push(`冲突检测失败: ${conflicts.error}`)
  return messages
}

export function getConfigurationImportConflictMessages(
  missingDependencies: string[],
  dependencyConflicts: string[],
  overwriteConflicts: string[]
): string[] {
  return [
    ...missingDependencies.map((dep) => `缺失依赖组件: ${dep}`),
    ...dependencyConflicts,
    ...overwriteConflicts
  ]
}

export function buildConfigurationImportPreview(
  config: ExportedConfiguration,
  targetComponentId: string,
  configurationManager: any,
  availableComponents?: any[]
): ImportPreview {
  const dependencies = checkConfigurationDependencies(
    config,
    targetComponentId,
    configurationManager,
    availableComponents
  )
  const conflicts = checkConfigurationConflicts(config, targetComponentId, configurationManager)
  const conflictList: string[] = [
    ...dependencies.missing.map((dep) => `缺失依赖组件: ${dep}`),
    ...dependencies.conflicts,
    ...getOverwriteConflictMessages(conflicts)
  ]

  return {
    basicInfo: {
      version: config.version,
      exportTime: config.exportTime,
      componentType: config.componentType || config.metadata?.componentType || '',
      exportSource: config.metadata?.exportSource || 'AetherLink IoT'
    },
    statistics: {
      dataSourceCount: config.metadata?.statistics?.dataSourceCount || 0,
      interactionCount: config.metadata?.statistics?.interactionCount || 0,
      httpConfigCount: config.metadata?.statistics?.httpConfigCount || 0
    },
    dependencies: dependencies.found,
    conflicts: conflictList
  }
}

export function createMissingDependencyWarnings(
  missingDependencies: string[],
  options: { skipMissingDependencies?: boolean }
): string[] {
  if (missingDependencies.length === 0 || !options.skipMissingDependencies) {
    return []
  }

  return [`跳过缺失的依赖组件: ${missingDependencies.join(', ')}`]
}

export function getMissingDependencyFailure(
  missingDependencies: string[],
  options: { skipMissingDependencies?: boolean },
  warnings: string[]
): ImportResult | undefined {
  if (missingDependencies.length === 0 || options.skipMissingDependencies) {
    return undefined
  }

  return {
    success: false,
    errors: [`缺失依赖组件: ${missingDependencies.join(', ')}`],
    warnings
  }
}

export function getOverwriteFailure(
  configurationConflicts: ConfigurationConflictResult,
  overwriteConflicts: string[],
  options: { overwriteExisting?: boolean },
  warnings: string[]
): ImportResult | undefined {
  if (configurationConflicts.error || (overwriteConflicts.length > 0 && !options.overwriteExisting)) {
    return {
      success: false,
      errors: overwriteConflicts,
      warnings
    }
  }

  return undefined
}

export function createSuccessfulImportResult(
  processedConfig: any,
  effectiveMissingDependencies: string[],
  dependencyCheck: DependencyCheckResult,
  warnings: string[]
): ImportResult {
  return {
    success: true,
    errors: [],
    warnings,
    importedData: processedConfig,
    dependencyValidation: {
      missing: effectiveMissingDependencies,
      found: dependencyCheck.found
    }
  }
}

export function processConfigurationForImport(
  config: ExportedConfiguration,
  targetComponentId: string,
  currentComponentPlaceholder: string
): {
  processedConfig: any
  missingDependencies: string[]
} {
  return {
    processedConfig: {
      dataSource: config.data.dataSourceConfiguration
        ? restorePlaceholderDeep(config.data.dataSourceConfiguration, currentComponentPlaceholder, targetComponentId)
        : undefined,
      component: config.data.componentConfiguration
        ? restorePlaceholderDeep(config.data.componentConfiguration, currentComponentPlaceholder, targetComponentId)
        : undefined,
      interaction: config.data.interactionConfiguration
        ? restorePlaceholderDeep(config.data.interactionConfiguration, currentComponentPlaceholder, targetComponentId)
        : undefined
    },
    missingDependencies: []
  }
}

async function updateConfigurationSection(
  configurationManager: ConfigurationManagerLike,
  componentId: string,
  section: ConfigurationSection,
  data: any
): Promise<void> {
  if (typeof configurationManager.updateConfiguration === 'function') {
    await configurationManager.updateConfiguration(componentId, section, data)
    return
  }

  await configurationManager.updateConfigurationSection!(componentId, section, data)
}

export async function applyImportedConfiguration(
  processedConfig: any,
  targetComponentId: string,
  configurationManager: ConfigurationManagerLike
): Promise<void> {
  if (
    !configurationManager ||
    (typeof configurationManager.updateConfiguration !== 'function' &&
      typeof configurationManager.updateConfigurationSection !== 'function')
  ) {
    const error = '配置管理器无效或未提供'
    console.error(`[ConfigurationImporter] ${error}`)
    throw new Error(error)
  }

  if (processedConfig.dataSource) {
    await updateConfigurationSection(configurationManager, targetComponentId, 'dataSource', processedConfig.dataSource)
  }

  if (processedConfig.component) {
    await updateConfigurationSection(configurationManager, targetComponentId, 'component', processedConfig.component)
  }

  if (processedConfig.interaction) {
    await updateConfigurationSection(
      configurationManager,
      targetComponentId,
      'interaction',
      processedConfig.interaction
    )
  }
}

/**
 * 文件用途：承接整组件配置导入的 preview / import 共享流程。
 * 核心逻辑：统一处理 parse -> plan -> preview/build 或 apply/result 的总装路径。
 * 关键注意事项：这里是 `ConfigurationImporter` 的流程层，不要把规则复制回 UI 或导入导出门面。
 */
import type {
  ConfigurationImportRuntimeManager,
  ExportedConfiguration,
  ImportPreview,
  ImportResult
} from './ConfigurationImportExport'
import {
  applyImportedConfiguration,
  createSuccessfulImportResult,
  parseConfigurationInput
} from './configurationImportProcessing'
import { formatImportExportError } from './configurationImportExportShared'
import {
  buildConfigurationImportPreviewFromPlan,
  planConfigurationImport,
  type ConfigurationImportOptions
} from './configurationImportPlan'

type GenerateConfigurationImportPreviewOptions = {
  availableComponents?: any[]
}

type ConfigurationImporterFlowOptions = {
  currentComponentPlaceholder: string
}

export const generateConfigurationImportPreview = (
  configJson: string | ExportedConfiguration,
  targetComponentId: string,
  configurationManager: ConfigurationImportRuntimeManager,
  { currentComponentPlaceholder }: ConfigurationImporterFlowOptions,
  { availableComponents }: GenerateConfigurationImportPreviewOptions = {}
): ImportPreview => {
  try {
    const config = parseConfigurationInput(configJson)
    const plan = planConfigurationImport(config, targetComponentId, configurationManager, currentComponentPlaceholder, {
      availableComponents,
      overwriteExisting: true,
      skipMissingDependencies: true
    })

    return buildConfigurationImportPreviewFromPlan(config, plan)
  } catch (error) {
    console.error('[ConfigurationImporter] 妫板嫯顫嶆径杈Е:', error)
    throw new Error(`Failed to generate import preview: ${formatImportExportError(error)}`)
  }
}

export const executeConfigurationImport = async (
  configJson: string | ExportedConfiguration,
  targetComponentId: string,
  configurationManager: ConfigurationImportRuntimeManager,
  { currentComponentPlaceholder }: ConfigurationImporterFlowOptions,
  options: ConfigurationImportOptions = {}
): Promise<ImportResult> => {
  try {
    const config = parseConfigurationInput(configJson)
    const plan = planConfigurationImport(
      config,
      targetComponentId,
      configurationManager,
      currentComponentPlaceholder,
      options
    )

    if (plan.failure) {
      return plan.failure
    }

    await applyImportedConfiguration(plan.processedConfig, targetComponentId, configurationManager)

    return createSuccessfulImportResult(
      plan.processedConfig,
      plan.effectiveMissingDependencies,
      plan.dependencyCheck,
      plan.warnings
    )
  } catch (error) {
    console.error('[ConfigurationImporter] import failed:', error)
    return {
      success: false,
      errors: [formatImportExportError(error)],
      warnings: []
    }
  }
}

/**
 * 文件用途: 设备参数生成器。
 * 核心逻辑: 根据设备选择模式生成 deviceId、metric、attribute 和 command 等参数组。
 * 关键注意事项: 参数名、角色和来源类型会被动态参数编辑器及 HTTP 模板复用。
 * 重构建议: 将不同选择模式的生成逻辑拆为策略函数，并增加真实设备选择 fixture。
 */

import type {
  DeviceParameterSourceType,
  DeviceSelectionConfig,
  DeviceParameterGroup,
  DeviceSelectionResult,
  ParameterRole,
  DeviceInfo,
  DeviceMetric
} from '../types/device-parameter-group'
import type { EnhancedParameter } from '@/core/data-architecture/types/parameter-editor'

/**
 * 生成唯一的参数组ID
 */
export function generateGroupId(sourceType: DeviceParameterSourceType): string {
  const timestamp = Date.now()
  const random = Math.random().toString(36).substring(2, 8)
  return `${sourceType}_${timestamp}_${random}`
}

/**
 * 生成唯一的参数ID
 */
export function generateParameterId(): string {
  return `param_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
}

/**
 * 根据设备ID选择器生成参数
 */
export function generateDeviceIdParameters(device: DeviceInfo): DeviceSelectionResult {
  const groupId = generateGroupId('device-id')
  const now = Date.now()

  // 生成设备ID参数
  const parameters = [
    {
      key: 'deviceId',
      value: device.deviceId,
      dataType: 'string' as const,
      description: `设备ID - ${device.deviceName}`,
      role: 'primary' as ParameterRole
    }
  ]

  // 创建参数组信息
  const groupInfo: DeviceParameterGroup = {
    groupId,
    sourceType: 'device-id',
    sourceConfig: {
      sourceType: 'device-id',
      selectedDevice: device,
      timestamp: now
    },
    relatedParams: ['deviceId'],
    dependencies: {
      deviceId: {
        dependsOn: [],
        affects: [],
        role: 'primary'
      }
    },
    createdAt: now,
    updatedAt: now
  }

  return {
    parameters,
    groupInfo,
    selectionConfig: groupInfo.sourceConfig
  }
}

/**
 * 根据设备指标选择器生成参数
 */
export function generateDeviceMetricParameters(device: DeviceInfo, metric: DeviceMetric): DeviceSelectionResult {
  const groupId = generateGroupId('device-metric')
  const now = Date.now()

  // 生成设备ID + 指标参数
  const parameters = [
    {
      key: 'deviceId',
      value: device.deviceId,
      dataType: 'string' as const,
      description: `设备ID - ${device.deviceName}`,
      role: 'primary' as ParameterRole
    },
    {
      key: 'metric',
      value: metric.metricKey,
      dataType: metric.metricType,
      description: `指标 - ${metric.metricLabel}${metric.unit ? ` (${metric.unit})` : ''}`,
      role: 'secondary' as ParameterRole
    }
  ]

  // 创建参数组信息
  const groupInfo: DeviceParameterGroup = {
    groupId,
    sourceType: 'device-metric',
    sourceConfig: {
      sourceType: 'device-metric',
      selectedDevice: device,
      selectedMetric: metric,
      timestamp: now
    },
    relatedParams: ['deviceId', 'metric'],
    dependencies: {
      deviceId: {
        dependsOn: [],
        affects: ['metric'],
        role: 'primary'
      },
      metric: {
        dependsOn: ['deviceId'],
        affects: [],
        role: 'secondary'
      }
    },
    createdAt: now,
    updatedAt: now
  }

  return {
    parameters,
    groupInfo,
    selectionConfig: groupInfo.sourceConfig
  }
}

/**
 * 将生成的参数转换为EnhancedParameter格式
 */
export function convertToEnhancedParameters(result: DeviceSelectionResult): EnhancedParameter[] {
  return result.parameters.map(param => ({
    key: param.key,
    value: param.value,
    enabled: true,
    valueMode: 'manual' as const,
    selectedTemplate: 'device-selection',
    dataType: param.dataType as any,
    variableName: '',
    description: param.description,
    _id: generateParameterId(),

    // 设备参数组信息
    deviceContext: {
      sourceType: 'device-selection',
      selectionConfig: result.selectionConfig,
      timestamp: result.groupInfo.createdAt
    },

    // 参数组归属信息
    parameterGroup: {
      groupId: result.groupInfo.groupId,
      role: param.role,
      isDerived: false
    }
  }))
}

/**
 * 参数组管理器类
 */
export class DeviceParameterGroupManager {
  private groups: Map<string, DeviceParameterGroup> = new Map()

  /**
   * 添加参数组
   */
  addGroup(group: DeviceParameterGroup): void {
    this.groups.set(group.groupId, group)
  }

  /**
   * 获取参数组
   */
  getGroup(groupId: string): DeviceParameterGroup | undefined {
    return this.groups.get(groupId)
  }

  /**
   * 移除参数组
   */
  removeGroup(groupId: string): boolean {
    return this.groups.delete(groupId)
  }

  /**
   * 根据参数key查找所属的参数组
   */
  findGroupByParameterKey(paramKey: string): DeviceParameterGroup | undefined {
    for (const group of this.groups.values()) {
      if (group.relatedParams.includes(paramKey)) {
        return group
      }
    }
    return undefined
  }

  /**
   * 获取参数组的所有相关参数
   */
  getGroupParameters(groupId: string, allParams: EnhancedParameter[]): EnhancedParameter[] {
    const group = this.getGroup(groupId)
    if (!group) return []

    return allParams.filter(param => param.parameterGroup?.groupId === groupId)
  }

  /**
   * 更新参数组
   */
  updateGroup(groupId: string, updates: Partial<DeviceParameterGroup>): boolean {
    const group = this.groups.get(groupId)
    if (!group) return false

    Object.assign(group, updates, { updatedAt: Date.now() })
    return true
  }

  /**
   * 获取所有参数组
   */
  getAllGroups(): DeviceParameterGroup[] {
    return Array.from(this.groups.values())
  }

  /**
   * 清空所有参数组
   */
  clear(): void {
    this.groups.clear()
  }
}

// 全局参数组管理器实例
export const globalParameterGroupManager = new DeviceParameterGroupManager()

type RelatedSingleDataSourceConfig = {
  interactions: any[]
  httpBindings: any[]
}

export function processSingleDataSourceForExport(
  sourceConfig: any,
  currentComponentId: string,
  currentComponentPlaceholder: string,
  dependencies: Set<string>
): any {
  const processValue = (obj: any): any => {
    if (obj === null || obj === undefined) {
      return obj
    }

    if (typeof obj === 'string') {
      return processStringValue(obj, currentComponentId, currentComponentPlaceholder, dependencies)
    }

    if (Array.isArray(obj)) {
      return obj.map((item) => processValue(item))
    }

    if (typeof obj === 'object') {
      const result: any = {}
      for (const [key, value] of Object.entries(obj)) {
        result[key] = processValue(value)
      }
      return result
    }

    return obj
  }

  return processValue(sourceConfig)
}

function processStringValue(
  value: string,
  currentComponentId: string,
  currentComponentPlaceholder: string,
  dependencies: Set<string>
): string {
  if (value.includes(currentComponentId)) {
    return value.replace(new RegExp(currentComponentId, 'g'), currentComponentPlaceholder)
  }

  const componentIdPattern = /^[a-zA-Z][a-zA-Z0-9_-]*_\d+$/
  if (componentIdPattern.test(value) && value !== currentComponentId) {
    dependencies.add(value)
  }

  return value
}

export function collectRelatedSingleDataSourceConfig(
  componentId: string,
  sourceId: string,
  configurationManager: any,
  currentComponentPlaceholder: string,
  dependencies: Set<string>
): RelatedSingleDataSourceConfig {
  const relatedConfig: RelatedSingleDataSourceConfig = {
    interactions: [],
    httpBindings: []
  }

  try {
    const interactionConfig = configurationManager.getConfiguration(componentId, 'interaction')
    if (interactionConfig) {
      const relatedInteractions = findRelatedInteractions(interactionConfig, sourceId)
      relatedConfig.interactions = relatedInteractions.map((interaction) =>
        processSingleDataSourceForExport(interaction, componentId, currentComponentPlaceholder, dependencies)
      )
    }

    const componentConfig = configurationManager.getConfiguration(componentId, 'component')
    if (componentConfig?.httpBindings) {
      const relatedHttpBindings = componentConfig.httpBindings.filter((binding: any) => binding.sourceId === sourceId)
      relatedConfig.httpBindings = relatedHttpBindings.map((binding: any) =>
        processSingleDataSourceForExport(binding, componentId, currentComponentPlaceholder, dependencies)
      )
    }
  } catch (error) {
    console.error('[SingleDataSourceExporter] failed to collect related configuration:', error)
  }

  return relatedConfig
}

function findRelatedInteractions(interactionConfig: any, sourceId: string): any[] {
  const relatedInteractions: any[] = []

  if (!interactionConfig || typeof interactionConfig !== 'object') {
    return relatedInteractions
  }

  const objectDirectlyReferencesSource = (obj: Record<string, any>) =>
    obj.sourceId === sourceId || obj.dataSourceId === sourceId || obj.dataSource?.sourceId === sourceId

  // Recursively collect the smallest interaction objects that reference sourceId.
  const searchInteractions = (obj: any): boolean => {
    if (Array.isArray(obj)) {
      return obj.some((item) => searchInteractions(item))
    }

    if (typeof obj !== 'object' || obj === null) {
      return false
    }

    if (objectDirectlyReferencesSource(obj)) {
      relatedInteractions.push(obj)
      return true
    }

    const childMatched = Object.values(obj).some((value) => searchInteractions(value))
    if (!childMatched && JSON.stringify(obj).includes(sourceId)) {
      relatedInteractions.push(obj)
      return true
    }

    return childMatched
  }

  searchInteractions(interactionConfig)
  return relatedInteractions
}

import { smartDeepClone } from '@/utils/deep-clone'
import { restorePlaceholderDeep } from './configurationImportExportShared'

interface SingleDataSourceImportPayload {
  dataSourceConfig: any
  relatedConfig: {
    interactions: any
    httpBindings: any
  }
}

function hasHttpParameterTemplateMarker(value: any): boolean {
  return !!(value && typeof value === 'object' && ('valueMode' in value || 'selectedTemplate' in value))
}

function detectIsDynamicParameter(param: any): boolean {
  const hasBindingFeatures =
    param.valueMode === 'component' ||
    param.selectedTemplate === 'component-property-binding' ||
    (typeof param.value === 'string' &&
      param.value.includes('.') &&
      param.value.split('.').length >= 3 &&
      param.value.length > 15) ||
    (param.variableName && param.variableName.includes('_') && param.variableName.length > 5) ||
    (param.description &&
      (param.description.includes('绑定') ||
        param.description.includes('属性') ||
        param.description.includes('component')))

  if (hasBindingFeatures) {
    return true
  }

  return param.isDynamic !== undefined ? param.isDynamic : false
}

function normalizeImportedHttpParameter(value: any): any {
  if (!hasHttpParameterTemplateMarker(value)) {
    return value
  }

  return {
    ...value,
    isDynamic: detectIsDynamicParameter(value)
  }
}

function protectParameterBindingPaths(params: any[]): any[] {
  if (!params || !Array.isArray(params)) return params

  return params.map((param) => {
    if (!param.isDynamic && !param.selectedTemplate && !param.valueMode) {
      return param
    }

    const isBindingCorrupted =
      param.value &&
      typeof param.value === 'string' &&
      !param.value.includes('.') &&
      param.value.length < 10 &&
      param.variableName &&
      param.variableName.includes('_')

    if (isBindingCorrupted && param.variableName.includes('_')) {
      const lastUnderscoreIndex = param.variableName.lastIndexOf('_')
      if (lastUnderscoreIndex > 0) {
        const componentId = param.variableName.substring(0, lastUnderscoreIndex)
        const propertyName = param.variableName.substring(lastUnderscoreIndex + 1)
        const reconstructedPath = `${componentId}.base.${propertyName}`

        return {
          ...param,
          value: reconstructedPath,
          isDynamic: true
        }
      }
    }

    return param
  })
}

function normalizeImportedHttpParameterArray(values: any[]): any[] {
  const normalizedArray = values.map((item) => normalizeImportedHttpParameter(item))
  return protectParameterBindingPaths(normalizedArray)
}

function normalizeImportedHttpParameterObject(value: Record<string, any>): any {
  if (!hasHttpParameterTemplateMarker(value)) {
    return value
  }

  return protectParameterBindingPaths([normalizeImportedHttpParameter(value)])[0]
}

function restoreImportedDataWithCurrentComponent(
  value: any,
  targetComponentId: string,
  currentComponentPlaceholder: string
): any {
  return restorePlaceholderDeep(value, currentComponentPlaceholder, targetComponentId, {
    normalizeArray: (restoredArray) => normalizeImportedHttpParameterArray(restoredArray),
    normalizeObject: (restoredObject) => normalizeImportedHttpParameterObject(restoredObject)
  })
}

export function processSingleDataSourceImportPayload<T extends SingleDataSourceImportPayload>(
  importData: T,
  targetComponentId: string,
  currentComponentPlaceholder: string
): T {
  const processedData = smartDeepClone(importData) as T

  processedData.dataSourceConfig = restoreImportedDataWithCurrentComponent(
    processedData.dataSourceConfig,
    targetComponentId,
    currentComponentPlaceholder
  )

  processedData.relatedConfig.interactions = restoreImportedDataWithCurrentComponent(
    processedData.relatedConfig.interactions,
    targetComponentId,
    currentComponentPlaceholder
  )
  processedData.relatedConfig.httpBindings = restoreImportedDataWithCurrentComponent(
    processedData.relatedConfig.httpBindings,
    targetComponentId,
    currentComponentPlaceholder
  )

  return processedData
}

﻿/**
 * 文件说明：
 * - 单数据源导入时的目标落点处理器。
 * - 负责查找/创建目标 slot、冲突检查、写回 dataSource 配置，并补挂相关交互与 HTTP 绑定。
 * - 这里是导入流程真正改写组件配置的入口，保护逻辑和报错文案需要保持清晰。
 */

import type { SingleDataSourceExport } from './ConfigurationImportExport'
import type { ConfigurationManagerLike } from './configurationImportProcessing'

/** 编辑器节点视图（导入工具只读取标识字段） */
interface EditorNodeLike {
  id?: unknown
  componentId?: unknown
  widgetId?: unknown
  type?: unknown
  componentType?: unknown
  [key: string]: unknown
}

/** 数据源槽位（导入落点，字段宽松） */
interface DataSourceSlotLike {
  sourceId?: unknown
  dataItems?: unknown[]
  mergeStrategy?: unknown
  processing?: Record<string, unknown> | null
  [key: string]: unknown
}

/** 组件完整配置的局部视图（导入流程只读写这些段） */
interface ComponentFullConfigLike {
  dataSource?: DataSourceConfigLike | null
  interaction?: { importedInteractions?: unknown[]; [key: string]: unknown } | null
  component?: { httpBindings?: Array<Record<string, unknown>>; [key: string]: unknown } | null
  [key: string]: unknown
}

/** 组件 dataSource 配置段 */
interface DataSourceConfigLike {
  dataSources?: DataSourceSlotLike[] | null
  createdAt?: number
  updatedAt?: number
  [key: string]: unknown
}

/** 单数据源导入目标处理所需的配置管理器视图（共享契约 + store/nodes 访问） */
type SingleDataSourceManagerLike = ConfigurationManagerLike & {
  store?: { nodes?: EditorNodeLike[] | null } | null
  nodes?: EditorNodeLike[] | null
  getNodes?: () => EditorNodeLike[] | null
  getAllComponents?: () => EditorNodeLike[] | null
}

interface SingleDataSourceTargetContext {
  fullConfig: ComponentFullConfigLike
  existingConfig: DataSourceConfigLike
  targetSlotIndex: number
}

function createDefaultMergeStrategy(): { type: 'object' } {
  return { type: 'object' }
}

function createEmptyDataSourceSlot(sourceId: string) {
  return {
    sourceId,
    dataItems: [],
    mergeStrategy: createDefaultMergeStrategy()
  }
}

function createEmptySlotPreview(slotIndex: number) {
  return {
    slotId: `dataSource${slotIndex + 1}`,
    slotIndex,
    isEmpty: true
  }
}

function getExistingComponentIds(targetComponentId: string, configurationManager: SingleDataSourceManagerLike): Set<string> {
  const ids = new Set<string>([targetComponentId])
  const candidates = [
    configurationManager?.store?.nodes,
    configurationManager?.nodes,
    configurationManager?.getNodes?.(),
    configurationManager?.getAllComponents?.()
  ]

  candidates.forEach((candidate) => {
    if (Array.isArray(candidate)) {
      candidate.forEach((item) => {
        const id = item?.id || item?.componentId || item?.widgetId
        if (typeof id === 'string') ids.add(id)
      })
    }
  })

  return ids
}

function getTargetComponentType(targetComponentId: string, configurationManager: SingleDataSourceManagerLike): string | undefined {
  const fullConfig = configurationManager?.getConfiguration?.(targetComponentId)
  const node = configurationManager?.store?.nodes?.find?.(item => item?.id === targetComponentId)

  return (
    fullConfig?.metadata?.componentType ||
    fullConfig?.component?.type ||
    fullConfig?.component?.properties?.type ||
    node?.type ||
    node?.componentType
  )
}

function ensureDataSourceSlots(dataSourceConfig: DataSourceConfigLike): void {
  if (!dataSourceConfig.dataSources || !Array.isArray(dataSourceConfig.dataSources)) {
    dataSourceConfig.dataSources = []
  }
}

function findOrCreateDataSourceSlot(dataSourceConfig: DataSourceConfigLike, targetSlotId: string): number {
  const existingSlotIndex = dataSourceConfig.dataSources.findIndex(source => source.sourceId === targetSlotId)
  if (existingSlotIndex !== -1) {
    return existingSlotIndex
  }

  dataSourceConfig.dataSources.push(createEmptyDataSourceSlot(targetSlotId))
  return dataSourceConfig.dataSources.length - 1
}

function isOccupiedDataSourceSlot(slot: DataSourceSlotLike | null | undefined): boolean {
  if (!slot || typeof slot !== 'object') {
    return false
  }

  if (Array.isArray(slot.dataItems) && slot.dataItems.length > 0) {
    return true
  }

  if (slot.processing && Object.keys(slot.processing).length > 0) {
    return true
  }

  return !!(slot.mergeStrategy && JSON.stringify(slot.mergeStrategy) !== JSON.stringify(createDefaultMergeStrategy()))
}

function assertDataSourceSlotWritable(
  targetSlot: DataSourceSlotLike | null | undefined,
  targetSlotId: string,
  options: { overwriteExisting?: boolean }
): void {
  if (isOccupiedDataSourceSlot(targetSlot) && !options.overwriteExisting) {
    throw new Error(`目标数据源槽位已存在配置: ${targetSlotId}`)
  }
}

function updateConfigurationSection(
  configurationManager: SingleDataSourceManagerLike,
  componentId: string,
  section: string,
  data: unknown
): void {
  if (typeof configurationManager.updateConfiguration === 'function') {
    configurationManager.updateConfiguration(componentId, section, data)
    return
  }

  configurationManager.updateConfigurationSection(componentId, section, data)
}

function prepareTargetDataSourceContext(
  targetComponentId: string,
  targetSlotId: string,
  configurationManager: SingleDataSourceManagerLike,
  options: { overwriteExisting?: boolean }
): SingleDataSourceTargetContext {
  const fullConfig = configurationManager.getConfiguration(targetComponentId)
  const existingConfig = fullConfig?.dataSource || {
    componentId: targetComponentId,
    dataSources: [],
    createdAt: Date.now(),
    updatedAt: Date.now()
  }

  ensureDataSourceSlots(existingConfig)
  // 导入只覆盖命中的 slot，其他数据源配置保持原样。
  const targetSlotIndex = findOrCreateDataSourceSlot(existingConfig, targetSlotId)
  assertDataSourceSlotWritable(existingConfig.dataSources[targetSlotIndex], targetSlotId, options)

  return {
    fullConfig,
    existingConfig,
    targetSlotIndex
  }
}

function applyDataSourceSlotImport(
  processedConfig: SingleDataSourceExport,
  targetSlotId: string,
  targetContext: SingleDataSourceTargetContext
): void {
  targetContext.existingConfig.dataSources[targetContext.targetSlotIndex] = {
    sourceId: targetSlotId,
    dataItems: processedConfig.dataSourceConfig?.dataItems || [],
    mergeStrategy: processedConfig.dataSourceConfig?.mergeStrategy || createDefaultMergeStrategy(),
    ...(processedConfig.dataSourceConfig?.processing && {
      processing: processedConfig.dataSourceConfig.processing
    })
  }

  targetContext.existingConfig.updatedAt = Date.now()
}

function appendImportedInteractions(
  processedConfig: SingleDataSourceExport,
  targetComponentId: string,
  configurationManager: SingleDataSourceManagerLike,
  fullConfig: ComponentFullConfigLike
): void {
  if (!processedConfig.relatedConfig?.interactions?.length) {
    return
  }

  const nextInteractionConfig = {
    ...(fullConfig?.interaction || {}),
    importedInteractions: [
      ...(fullConfig?.interaction?.importedInteractions || []),
      ...processedConfig.relatedConfig.interactions
    ]
  }
  updateConfigurationSection(configurationManager, targetComponentId, 'interaction', nextInteractionConfig)
}

function appendHttpBindings(
  processedConfig: SingleDataSourceExport,
  targetSlotId: string,
  targetComponentId: string,
  configurationManager: SingleDataSourceManagerLike,
  fullConfig: ComponentFullConfigLike
): void {
  if (!processedConfig.relatedConfig?.httpBindings?.length) {
    return
  }

  const nextComponentConfig = {
    ...(fullConfig?.component || {}),
    httpBindings: [
      ...(fullConfig?.component?.httpBindings || []),
      ...processedConfig.relatedConfig.httpBindings.map(binding => ({
        ...binding,
        sourceId: targetSlotId
      }))
    ]
  }
  updateConfigurationSection(configurationManager, targetComponentId, 'component', nextComponentConfig)
}

export function getAvailableSingleDataSourceSlots(componentId: string, configurationManager: SingleDataSourceManagerLike) {
  const slots: Array<{
    slotId: unknown
    slotIndex: number
    isEmpty: boolean
    currentConfig?: {
      dataItemCount: number
      mergeStrategy: unknown
    }
  }> = []

  try {
    const fullConfig = configurationManager?.getConfiguration?.(componentId)
    const dataSourceConfig = fullConfig?.dataSource

    if (
      !dataSourceConfig ||
      !Array.isArray(dataSourceConfig.dataSources) ||
      dataSourceConfig.dataSources.length === 0
    ) {
      for (let i = 0; i < 3; i++) {
        slots.push(createEmptySlotPreview(i))
      }
    } else {
      dataSourceConfig.dataSources.forEach((source, index) => {
        slots.push({
          slotId: source.sourceId,
          slotIndex: index,
          isEmpty: !source.dataItems || source.dataItems.length === 0,
          currentConfig:
            source.dataItems?.length > 0
              ? {
                  dataItemCount: source.dataItems.length,
                  mergeStrategy: source.mergeStrategy?.type || 'object'
                }
              : undefined
        })
      })
    }
  } catch (error) {
    console.error('[SingleDataSourceImporter] 获取数据源槽位失败', error)
  }

  return slots
}

export function checkSingleDataSourceImportConflicts(
  importData: SingleDataSourceExport,
  targetComponentId: string,
  configurationManager: SingleDataSourceManagerLike
): string[] {
  const conflicts: string[] = []

  try {
    if (importData.exportType !== 'single-datasource') {
      conflicts.push('导入文件不是单数据源配置')
    }

    if (!importData.dataSourceConfig?.dataItems?.length) {
      conflicts.push('导入文件不包含有效的数据项配置')
    }

    const dependencies = importData.mapping.dependencies || []
    const existingComponentIds = getExistingComponentIds(targetComponentId, configurationManager)
    const missingDependencies = dependencies.filter((dep) => !existingComponentIds.has(dep))
    if (missingDependencies.length > 0) {
      conflicts.push(`缺失外部依赖组件: ${missingDependencies.join(', ')}`)
    }

    const sourceComponentType = importData.sourceMetadata.componentType
    const targetComponentType = getTargetComponentType(targetComponentId, configurationManager)
    if (sourceComponentType && targetComponentType && sourceComponentType !== targetComponentType) {
      conflicts.push(`组件类型不匹配: ${sourceComponentType} -> ${targetComponentType}`)
    }
  } catch (error) {
    console.error('[SingleDataSourceImporter] 导入冲突检查失败', error)
  }

  return conflicts
}

export function applySingleDataSourceImportTarget(
  processedConfig: SingleDataSourceExport,
  targetComponentId: string,
  targetSlotId: string,
  configurationManager: SingleDataSourceManagerLike,
  options: { overwriteExisting?: boolean } = {}
): void {
  // 先写入 dataSource 主配置，再补挂导入附带的交互与 HTTP 绑定。
  const targetContext = prepareTargetDataSourceContext(
    targetComponentId,
    targetSlotId,
    configurationManager,
    options
  )

  applyDataSourceSlotImport(processedConfig, targetSlotId, targetContext)
  updateConfigurationSection(
    configurationManager,
    targetComponentId,
    'dataSource',
    targetContext.existingConfig
  )
  appendImportedInteractions(processedConfig, targetComponentId, configurationManager, targetContext.fullConfig)
  appendHttpBindings(
    processedConfig,
    targetSlotId,
    targetComponentId,
    configurationManager,
    targetContext.fullConfig
  )
}

