    await flushPromises()
    expect(hoisted.messageError).toHaveBeenCalledWith('interaction.messages.menuDataProcessFailed')

    hoisted.fetchGetUserRoutes.mockResolvedValueOnce({ data: {} })
    await wrapper.get('.radio-external').trigger('click')
