    await nextTick()

    await buttonByText(wrapper, 'interaction.template.export').trigger('click')

    expect(hoisted.messageError).toHaveBeenCalledWith('interaction.messages.exportFailed')
    expect(clickSpy).toHaveBeenCalledTimes(0)
  })
})

