import {
  buildJumpResponse,
  buildModifyResponse,
  readCompatibilityJumpEditState,
  readJumpEditState,
  readModifyEditState,
  type InteractionActionType,
  type InteractionUrlType
} from './interactionResponseProtocol'

export type TargetPropertyInfo = {
  componentId: string
  layer: string
  propertyName: string
}

export type InteractionFormState = {
  event: string
  enabled: boolean
  priority: number
  url: string
  target: string
  targetComponentId: string
  targetProperty: string
  updateValue: string
}

export type InteractionConditionFormState = {
  watchedProperty: string
  type: string
  operator: string
  value: string
}

export type InteractionTargetBindingFormState = {
  bindingPath: string
  propertyInfo: TargetPropertyInfo | null
}

export type InteractionActionFormState = {
  actionType: InteractionActionType
  urlType: InteractionUrlType
  selectedMenuPath: string
  shouldLoadMenuOptions: boolean
}

export type InteractionEditFormState = {
  interaction: InteractionFormState
  condition: InteractionConditionFormState
  targetBinding: InteractionTargetBindingFormState
  action: InteractionActionFormState
}

export type BuildInteractionDraftInput = {
  interaction: InteractionFormState
  condition: InteractionConditionFormState
  targetBinding: InteractionTargetBindingFormState
  action: InteractionActionFormState
}

export function createDefaultInteractionState(overrides: Partial<InteractionFormState> = {}): InteractionFormState {
  return {
    event: 'click',
    enabled: true,
    priority: 1,
    url: '',
    target: '_blank',
    targetComponentId: '',
    targetProperty: '',
    updateValue: '',
    ...overrides
  }
}

export function createEmptyConditionFormState(): InteractionConditionFormState {
  return {
    watchedProperty: '',
    type: '',
    operator: '',
    value: ''
  }
}

export function createEmptyTargetBindingFormState(): InteractionTargetBindingFormState {
  return {
    bindingPath: '',
    propertyInfo: null
  }
}

export function createDefaultActionFormState(
  overrides: Partial<InteractionActionFormState> = {}
): InteractionActionFormState {
  return {
    actionType: '',
    urlType: 'external',
    selectedMenuPath: '',
    shouldLoadMenuOptions: false,
    ...overrides
  }
}

export function createTargetBindingPath(componentId?: string, property?: string) {
  if (!componentId || !property) return ''
  return `${componentId}.${property}`
}

export function readInteractionEditFormState(interaction: any): InteractionEditFormState {
  const editState: InteractionEditFormState = {
    interaction: createDefaultInteractionState({
      event: interaction.event,
      enabled: interaction.enabled,
      priority: interaction.priority
    }),
    condition: readConditionFormState(interaction),
    targetBinding: createEmptyTargetBindingFormState(),
    action: createDefaultActionFormState()
  }

  applyResponseEditState(editState, interaction.responses?.[0])
  return editState
}

function readConditionFormState(interaction: any): InteractionConditionFormState {
  const conditionState = createEmptyConditionFormState()
  if (interaction.event !== 'dataChange') return conditionState

  conditionState.watchedProperty = interaction.watchedProperty || ''
  const condition = interaction.condition
  if (!condition) return conditionState

  conditionState.type = condition.type || ''
  if (condition.type === 'comparison') {
    conditionState.operator = condition.operator || ''
    conditionState.value = condition.value || ''
  } else if (condition.type === 'range' || condition.type === 'expression') {
    conditionState.value = condition.value || ''
  }

  return conditionState
}

function applyResponseEditState(editState: InteractionEditFormState, response: any) {
  if (!response) return

  if (response.action === 'jump') {
    const state = readJumpEditState(response)
    editState.action = createDefaultActionFormState({
      actionType: 'jump',
      urlType: state.urlType,
      selectedMenuPath: state.selectedMenuPath,
      shouldLoadMenuOptions: state.shouldLoadMenuOptions
    })
    editState.interaction.target = state.target
    editState.interaction.url = state.url
    return
  }

  if (response.action === 'navigateToUrl') {
    const state = readCompatibilityJumpEditState(response.value || '', response.target)
    editState.action = createDefaultActionFormState({
      actionType: 'jump',
      urlType: state.urlType,
      selectedMenuPath: state.selectedMenuPath,
      shouldLoadMenuOptions: state.shouldLoadMenuOptions
    })
    editState.interaction.target = state.target
    editState.interaction.url = state.url
    return
  }

  if (response.action === 'modify' || response.action === 'updateComponentData') {
    const state = readModifyEditState(response)
    editState.action = createDefaultActionFormState({
      actionType: 'modify'
    })
    editState.interaction.targetComponentId = state.targetComponentId
    editState.interaction.targetProperty = state.targetProperty
    editState.interaction.updateValue = state.updateValue
    editState.targetBinding.bindingPath = createTargetBindingPath(state.targetComponentId, state.targetProperty)
  }
}

export function buildInteractionDraft(input: BuildInteractionDraftInput) {
  const interaction: any = {
    event: input.interaction.event,
    enabled: input.interaction.enabled,
    priority: input.interaction.priority,
    responses: []
  }

  if (input.interaction.event === 'dataChange') {
    interaction.watchedProperty = input.condition.watchedProperty
    const condition = buildCondition(input.condition)
    if (condition) {
      interaction.condition = condition
    }
  }

  interaction.responses = buildInteractionResponses(input)
  return interaction
}

function buildCondition(conditionState: InteractionConditionFormState) {
  if (!conditionState.type) return null

  const condition: Record<string, any> = {
    type: conditionState.type
  }

  if (conditionState.type === 'comparison') {
    condition.operator = conditionState.operator
    condition.value = conditionState.value
  } else if (conditionState.type === 'range' || conditionState.type === 'expression') {
    condition.value = conditionState.value
  }

  return condition
}

function buildInteractionResponses(input: BuildInteractionDraftInput) {
  if (input.action.actionType === 'jump') {
    return [
      buildJumpResponse({
        urlType: input.action.urlType,
        url: input.interaction.url,
        selectedMenuPath: input.action.selectedMenuPath,
        target: input.interaction.target
      })
    ]
  }

  if (input.action.actionType === 'modify') {
    const { targetComponentId, targetProperty } = resolveModifyTarget(input)
    return [
      buildModifyResponse({
        targetComponentId,
        targetProperty,
        updateValue: input.interaction.updateValue,
        bindingPath: input.targetBinding.bindingPath
      })
    ]
  }

  return []
}

function resolveModifyTarget(input: BuildInteractionDraftInput) {
  const propertyInfo = input.targetBinding.propertyInfo
  if (input.targetBinding.bindingPath && propertyInfo) {
    return {
      targetComponentId: propertyInfo.componentId,
      targetProperty: `${propertyInfo.layer}.${propertyInfo.propertyName}`
    }
  }

  return {
    targetComponentId: input.interaction.targetComponentId,
    targetProperty: input.interaction.targetProperty
  }
}

import type {
  InteractionConfig,
  InteractionEventType,
  InteractionResponse
} from './interactionPreviewTypes'

type Translate = (key: string) => string
type InteractionActionType = InteractionResponse['action']

export type PreviewLogType = 'info' | 'success' | 'warning' | 'error'

export function getInteractionEventTagType(event: InteractionEventType) {
  const typeMap: Record<string, string> = {
    click: 'success',
    hover: 'info',
    focus: 'warning',
    blur: 'default',
    custom: 'error'
  }
  return typeMap[event] || 'default'
}

export function getInteractionEventDisplayName(event: InteractionEventType, t: Translate) {
  const nameMap: Record<string, string> = {
    click: t('interaction.events.click'),
    hover: t('interaction.events.hover'),
    focus: t('interaction.events.focus'),
    blur: t('interaction.events.blur'),
    custom: t('interaction.events.custom')
  }
  return nameMap[event] || event
}

export function getInteractionActionDisplayName(action: InteractionActionType, t: Translate) {
  const nameMap: Record<string, string> = {
    changeBackgroundColor: t('interaction.actions.changeBackgroundColor'),
    changeTextColor: t('interaction.actions.changeTextColor'),
    changeBorderColor: t('interaction.actions.changeBorderColor'),
    changeSize: t('interaction.actions.changeSize'),
    changeOpacity: t('interaction.actions.changeOpacity'),
    changeTransform: t('interaction.actions.changeTransform'),
    changeVisibility: t('interaction.actions.changeVisibility'),
    changeContent: t('interaction.actions.changeContent'),
    triggerAnimation: t('interaction.actions.triggerAnimation'),
    custom: t('interaction.actions.custom')
  }
  return nameMap[action] || action
}

export function formatInteractionResponseValue(response: InteractionResponse, t: Translate) {
  const { action, value } = response

  switch (action) {
    case 'changeBackgroundColor':
    case 'changeTextColor':
    case 'changeBorderColor':
      return value
    case 'changeSize':
      if (typeof value === 'object' && value) {
        const sizeValue = value as { width?: number | string; height?: number | string }
        return `${sizeValue.width || '?'}\u00d7${sizeValue.height || '?'}`
      }
      return String(value)
    case 'changeOpacity':
      return `${Math.round((value as number) * 100)}%`
    case 'changeTransform':
      return String(value)
    case 'changeVisibility':
      return value === 'visible' ? t('interaction.visibility.visible') : t('interaction.visibility.hidden')
    case 'changeContent':
      return String(value).substring(0, 20) + (String(value).length > 20 ? '...' : '')
    case 'triggerAnimation':
      return String(value)
    case 'custom':
      try {
        return JSON.stringify(value).substring(0, 30) + '...'
      } catch {
        return String(value)
      }
    default:
      return String(value)
  }
}

export function formatInteractionPreviewTime(date: Date) {
  return date.toLocaleTimeString('zh-CN', {
    hour12: false,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
  })
}

export function getEnabledInteractionsByEvent(interactions: InteractionConfig[], eventType: InteractionEventType) {
  return interactions
    .map((interaction, index) => ({ interaction, index }))
    .filter(({ interaction }) => interaction.event === eventType && interaction.enabled)
    .sort((a, b) => (b.interaction.priority || 0) - (a.interaction.priority || 0))
}

interface ApplyPreviewResponseOptions {
  setRuntimeStyle: (property: string, styleValue: unknown) => void
  setContent: (value: string) => void
}

export function applyInteractionPreviewResponse(
  element: HTMLElement,
  response: InteractionResponse,
  options: ApplyPreviewResponseOptions
) {
  const { action, value, duration = 300, easing = 'ease' } = response
  const { setRuntimeStyle, setContent } = options

  element.style.transition = `all ${duration}ms ${easing}`

  switch (action) {
    case 'changeBackgroundColor':
      setRuntimeStyle('backgroundColor', value)
      break
    case 'changeTextColor':
      setRuntimeStyle('color', value)
      break
    case 'changeBorderColor':
      setRuntimeStyle('borderStyle', 'solid')
      setRuntimeStyle('borderTopStyle', 'solid')
      setRuntimeStyle('borderRightStyle', 'solid')
      setRuntimeStyle('borderBottomStyle', 'solid')
      setRuntimeStyle('borderLeftStyle', 'solid')
      setRuntimeStyle('borderColor', value)
      setRuntimeStyle('borderTopColor', value)
      setRuntimeStyle('borderRightColor', value)
      setRuntimeStyle('borderBottomColor', value)
      setRuntimeStyle('borderLeftColor', value)
      break
    case 'changeSize':
      if (typeof value === 'object' && value) {
        const sizeValue = value as { width?: number | string; height?: number | string }
        if (sizeValue.width) setRuntimeStyle('width', `${sizeValue.width}px`)
        if (sizeValue.height) setRuntimeStyle('height', `${sizeValue.height}px`)
      }
      break
    case 'changeOpacity':
      setRuntimeStyle('opacity', value)
      break
    case 'changeTransform':
      setRuntimeStyle('transform', value)
      break
    case 'changeVisibility':
      setRuntimeStyle('visibility', value)
      break
    case 'changeContent':
      setContent(String(value))
      break
    case 'triggerAnimation':
      element.style.animation = ''
      void element.offsetHeight
      setRuntimeStyle('animation', `${value} ${duration}ms ${easing}`)
      break
    case 'custom':
      if (typeof value === 'object' && value) {
        for (const [property, styleValue] of Object.entries(value)) {
          setRuntimeStyle(property, styleValue)
        }
      }
      break
  }
}

export type InteractionActionType = '' | 'jump' | 'modify' | 'custom' | 'none'
export type InteractionUrlType = 'external' | 'internal'

export type JumpEditState = {
  urlType: InteractionUrlType
  url: string
  target: string
  selectedMenuPath: string
  shouldLoadMenuOptions: boolean
}

export type ModifyEditState = {
  targetComponentId: string
  targetProperty: string
  updateValue: string
}

export type JumpResponseInput = {
  urlType: InteractionUrlType
  url: string
  selectedMenuPath: string
  target: string
}

export type ModifyResponseInput = ModifyEditState & {
  bindingPath: string
}

export function getInteractionActionType(interaction: any): InteractionActionType {
  const firstResponse = interaction?.responses?.[0]
  if (!firstResponse) return 'none'

  if (firstResponse.action === 'jump' || firstResponse.action === 'navigateToUrl') return 'jump'
  if (firstResponse.action === 'modify' || firstResponse.action === 'updateComponentData') return 'modify'

  return 'custom'
}

export function isExternalInteractionUrl(url: string) {
  return url.startsWith('http') || url.startsWith('https')
}

export function isInternalInteractionUrl(url: string) {
  return url.startsWith('/')
}

export function readCompatibilityJumpEditState(url: string, target?: string): JumpEditState {
  const isInternal = Boolean(url) && !isExternalInteractionUrl(url)

  return {
    urlType: isInternal ? 'internal' : 'external',
    url,
    target: target || '_blank',
    selectedMenuPath: isInternal ? url : '',
    shouldLoadMenuOptions: isInternal
  }
}

export function readJumpEditState(response: any): JumpEditState {
  if (!response?.jumpConfig) {
    return readCompatibilityJumpEditState(response?.value || '', response?.target)
  }

  const jumpConfig = response.jumpConfig
  const urlType: InteractionUrlType = jumpConfig.jumpType === 'internal' ? 'internal' : 'external'
  const url = urlType === 'external' ? jumpConfig.url || '' : jumpConfig.internalPath || ''

  return {
    urlType,
    url,
    target: jumpConfig.target || '_self',
    selectedMenuPath: urlType === 'internal' ? jumpConfig.internalPath || '' : '',
    shouldLoadMenuOptions: urlType === 'internal'
  }
}

export function readModifyEditState(response: any): ModifyEditState {
  const modifyConfig = response?.modifyConfig ?? response ?? {}

  return {
    targetComponentId: modifyConfig.targetComponentId || '',
    targetProperty: modifyConfig.targetProperty || '',
    updateValue: modifyConfig.updateValue || ''
  }
}

export function buildJumpResponse(input: JumpResponseInput) {
  const jumpConfig: Record<string, any> = {
    jumpType: input.urlType === 'external' ? 'external' : 'internal',
    target: input.target || '_self'
  }

  if (input.urlType === 'external') {
    jumpConfig.url = input.url
  } else {
    jumpConfig.internalPath = input.selectedMenuPath || input.url
  }

  return {
    action: 'jump',
    jumpConfig,
    value: input.url,
    target: input.target
  }
}

export function buildModifyResponse(input: ModifyResponseInput) {
  const modifyConfig = {
    targetComponentId: input.targetComponentId,
    targetProperty: input.targetProperty,
    updateValue: input.updateValue,
    updateMode: 'replace',
    bindingPath: input.bindingPath
  }

  return {
    action: 'modify',
    modifyConfig,
    targetComponentId: input.targetComponentId,
    targetProperty: input.targetProperty,
    updateValue: input.updateValue
  }
}

import {
  getInteractionActionType,
  isExternalInteractionUrl,
  isInternalInteractionUrl
} from './interactionResponseProtocol'

type Translate = (key: string) => string

function operatorLabel(operator: string, t: Translate) {
  const operatorMap: Record<string, string> = {
    equals: t('interaction.operators.equals'),
    notEquals: t('interaction.operators.notEquals'),
    greaterThan: t('interaction.operators.greaterThan'),
    greaterThanOrEqual: t('interaction.operators.greaterThanOrEqual'),
    lessThan: t('interaction.operators.lessThan'),
    lessThanOrEqual: t('interaction.operators.lessThanOrEqual'),
    contains: t('interaction.operators.contains'),
    startsWith: t('interaction.operators.startsWith'),
    endsWith: t('interaction.operators.endsWith')
  }
  return operatorMap[operator] || operator
}

function eventLabel(event: string, t: Translate) {
  const labelMap: Record<string, string> = {
    click: t('interaction.events.click'),
    hover: t('interaction.events.hover'),
    dataChange: t('interaction.events.dataChange')
  }
  return labelMap[event] || event
}

function conditionSummary(condition: any, t: Translate) {
  if (!condition) return t('interaction.empty.noCondition')

  const conditionType = condition.type
  const value = condition.value
  if (conditionType === 'comparison') {
    return `${operatorLabel(condition.operator, t)} ${value}`
  }
  if (conditionType === 'range') {
    return `${t('interaction.summary.range')} ${value}`
  }
  if (conditionType === 'expression') {
    return `${t('interaction.summary.expression')} ${value}`
  }
  return String(value || '')
}

function jumpResponseSummary(url: string, t: Translate) {
  if (isExternalInteractionUrl(url)) return t('interaction.summary.jumpToExternal')
  if (isInternalInteractionUrl(url)) return t('interaction.summary.jumpToInternal')
  return `${t('interaction.summary.jumpTo')} ${url}`
}

export function interactionSummaryTitle(interaction: any, t: Translate) {
  const actionType = getInteractionActionType(interaction)
  if (actionType === 'jump') return t('interaction.summary.pageJump')
  if (actionType === 'modify') return t('interaction.summary.modifyProperty')
  return t('interaction.summary.customAction')
}

export function interactionSummaryDesc(interaction: any, t: Translate) {
  const event = eventLabel(interaction.event, t)
  const actionType = getInteractionActionType(interaction)
  const response = interaction.responses?.[0] || {}

  if (interaction.event === 'dataChange') {
    const watchedProperty = interaction.watchedProperty || t('interaction.empty.notSpecified')
    let baseDesc = `${t('interaction.summary.listening')} ${watchedProperty} (${conditionSummary(
      interaction.condition,
      t
    )})`

    if (actionType === 'jump') {
      baseDesc += ` -> ${jumpResponseSummary(response.value || '', t)}`
    } else if (actionType === 'modify') {
      const target = response.targetComponentId || t('interaction.empty.component')
      const property = response.targetProperty || t('interaction.empty.property')
      baseDesc += ` -> ${t('interaction.summary.modify')}${target}.${property}`
    }

    return baseDesc
  }

  if (actionType === 'jump') {
    const url = response.value || ''
    if (isExternalInteractionUrl(url)) return `${event}${t('interaction.summary.whenClick')}: ${url}`
    if (isInternalInteractionUrl(url)) return `${event}${t('interaction.summary.whenHover')}: ${url}`
    return `${event}${t('interaction.summary.whenEvent')} ${url}`
  }

  if (actionType === 'modify') {
    const target = response.targetComponentId || t('interaction.empty.component')
    const property = response.targetProperty || t('interaction.empty.property')
    return `${event}${t('interaction.summary.whenEventModify')}${target}.${property}`
  }

  return `${event}${t('interaction.summary.whenEventCustom')}`
}

import { ref, type Ref } from 'vue'
import {
  buildInteractionDraft,
  createDefaultActionFormState,
  createDefaultInteractionState,
  createEmptyConditionFormState,
  createEmptyTargetBindingFormState,
  readInteractionEditFormState,
  type InteractionFormState,
  type TargetPropertyInfo
} from './interactionFormState'
import type { InteractionActionType, InteractionUrlType } from './interactionResponseProtocol'

type UseInteractionCardWizardDraftOptions = {
  interactions: Ref<any[]>
  emitUpdate: (value: any[]) => void
  loadMenuOptions: () => void | Promise<void>
}

export function useInteractionCardWizardDraft(options: UseInteractionCardWizardDraftOptions) {
  const editingIndex = ref(-1)
  const currentInteraction = ref<InteractionFormState>(createDefaultInteractionState())
  const currentActionType = ref<InteractionActionType>('')

  const urlType = ref<InteractionUrlType>('external')
  const selectedMenuPath = ref('')

  const currentWatchedProperty = ref('')
  const currentConditionType = ref('')
  const currentConditionOperator = ref('')
  const currentConditionValue = ref('')

  const currentTargetPropertyBinding = ref('')
  const currentTargetPropertyInfo = ref<TargetPropertyInfo | null>(null)

  function applyConditionState() {
    const conditionState = createEmptyConditionFormState()
    currentWatchedProperty.value = conditionState.watchedProperty
    currentConditionType.value = conditionState.type
    currentConditionOperator.value = conditionState.operator
    currentConditionValue.value = conditionState.value
  }

  function applyTargetBindingState() {
    const targetBinding = createEmptyTargetBindingFormState()
    currentTargetPropertyBinding.value = targetBinding.bindingPath
    currentTargetPropertyInfo.value = targetBinding.propertyInfo
  }

  function hydrateInteractionEditForm(interaction: any) {
    const editState = readInteractionEditFormState(interaction)
    currentInteraction.value = editState.interaction
    currentWatchedProperty.value = editState.condition.watchedProperty
    currentConditionType.value = editState.condition.type
    currentConditionOperator.value = editState.condition.operator
    currentConditionValue.value = editState.condition.value
    currentTargetPropertyBinding.value = editState.targetBinding.bindingPath
    currentTargetPropertyInfo.value = editState.targetBinding.propertyInfo
    currentActionType.value = editState.action.actionType
    urlType.value = editState.action.urlType
    selectedMenuPath.value = editState.action.selectedMenuPath

    if (editState.action.shouldLoadMenuOptions) {
      void options.loadMenuOptions()
    }
  }

  function beginInteractionEdit(index: number) {
    editingIndex.value = index
    hydrateInteractionEditForm(options.interactions.value[index])
  }

  function commitInteraction(interaction: any) {
    if (editingIndex.value >= 0) {
      options.interactions.value[editingIndex.value] = interaction
      editingIndex.value = -1
    } else {
      options.interactions.value.push(interaction)
    }

    options.emitUpdate(options.interactions.value)
  }

  function resetInteractionSaveForm() {
    currentInteraction.value = createDefaultInteractionState()
    const actionState = createDefaultActionFormState()
    currentActionType.value = actionState.actionType
    urlType.value = actionState.urlType
    selectedMenuPath.value = actionState.selectedMenuPath
    applyConditionState()
    applyTargetBindingState()
  }

  function saveCurrentInteraction() {
    const interaction = buildInteractionDraft({
      interaction: currentInteraction.value,
      condition: {
        watchedProperty: currentWatchedProperty.value,
        type: currentConditionType.value,
        operator: currentConditionOperator.value,
        value: currentConditionValue.value
      },
      targetBinding: {
        bindingPath: currentTargetPropertyBinding.value,
        propertyInfo: currentTargetPropertyInfo.value
      },
      action: {
        actionType: currentActionType.value,
        urlType: urlType.value,
        selectedMenuPath: selectedMenuPath.value,
        shouldLoadMenuOptions: false
      }
    })

    commitInteraction(interaction)
    resetInteractionSaveForm()
  }

  return {
    editingIndex,
    currentInteraction,
    currentActionType,
    urlType,
    selectedMenuPath,
    currentWatchedProperty,
    currentConditionType,
    currentConditionOperator,
    currentConditionValue,
    currentTargetPropertyBinding,
    currentTargetPropertyInfo,
    beginInteractionEdit,
    saveCurrentInteraction
  }
}

/**
 * 文件用途：执行交互动作并处理跨组件属性更新。
 * 核心逻辑：根据动作类型解析目标组件、写入配置或触发导航，并通过消息与日志反馈结果。
 * 关键注意事项：DOM 上暴露的 Vue 实例能力有限，访问 exposed 方法前必须保留空值保护。
 * 重构建议：可将动作处理器拆成策略表，减少新增动作时对主流程的修改。
 */

import { useEditorStore } from '@/store/modules/editor'
import { createLogger } from '@/utils/logger'
import { useMessage } from 'naive-ui'

const logger = createLogger('InteractionEngine')

/** Minimal Vue component internals exposed on rendered component DOM nodes. */
interface VueComponentElement extends Element {
  __vueParentComponent?: {
    exposed?: {
      updateConfig?: (section: string, config: Record<string, unknown>) => void
      watchProperty?: (propertyName: string, callback: (newValue: unknown, oldValue: unknown) => void) => () => void
    }
  }
}

type EditorStore = ReturnType<typeof useEditorStore>
type EditorNode = EditorStore['nodes'][number]
type MessageApi = ReturnType<typeof useMessage>

interface InteractionEngineContext {
  editorStore: EditorStore
  message: MessageApi
}

export interface InteractionAction {
  action: string
  targetComponentId?: string
  targetProperty?: string
  updateValue?: any
  jumpConfig?: {
    jumpType: 'external' | 'internal'
    url?: string
    internalPath?: string
    target?: string
  }
  modifyConfig?: {
    targetComponentId: string
    targetProperty: string
    updateValue: any
    updateMode?: 'replace' | 'merge' | 'append'
  }
}

export interface InteractionEvent {
  event: string
  watchedProperty?: string
  condition?: {
    type: 'comparison' | 'range' | 'expression'
    operator?: string
    value?: any
  }
  responses: InteractionAction[]
  enabled: boolean
}

function findComponentElement(componentId: string): VueComponentElement | null {
  return document.querySelector(`[data-component-id="${componentId}"]`) as VueComponentElement | null
}

function executeJumpAction(action: InteractionAction, message: MessageApi) {
  try {
    if (action.jumpConfig) {
      const { jumpType, url, internalPath, target = '_self' } = action.jumpConfig

      if (jumpType === 'external' && url) {
        window.open(url, target)
      } else if (jumpType === 'internal' && internalPath) {
        if (target === '_blank') {
          window.open(`${window.location.origin}${internalPath}`, '_blank')
        } else {
          window.location.href = internalPath
        }
      }
    } else {
      const url = action.updateValue || ''
      const target = action.targetProperty || '_blank'
      window.open(url, target)
    }
  } catch (error) {
    logger.error('[InteractionEngine] 跳转执行失败:', error)
    message.error(`跳转失败: ${error instanceof Error ? error.message : String(error)}`)
  }
}

function buildUpdatedComponentConfig(targetNode: EditorNode, targetProperty: string, updateValue: any) {
  const currentMetadata = (targetNode.metadata || {}) as Record<string, any>
  const currentUnifiedConfig = (currentMetadata.unifiedConfig || {}) as Record<string, any>
  const currentComponent = (currentUnifiedConfig.component || {}) as Record<string, any>
  const updatedComponent = {
    ...currentComponent,
    [targetProperty]: updateValue
  }

  return {
    currentMetadata,
    currentUnifiedConfig,
    updatedComponent
  }
}

function notifyExposedComponentConfig(targetComponentId: string, updatedComponent: Record<string, unknown>) {
  try {
    const targetElement = findComponentElement(targetComponentId)
    if (targetElement?.__vueParentComponent?.exposed?.updateConfig) {
      targetElement.__vueParentComponent.exposed.updateConfig('component', updatedComponent)
    }
  } catch (error) {
    logger.warn('[InteractionEngine] 直接更新组件配置失败:', error)
  }
}

function executeModifyAction(action: InteractionAction, context: InteractionEngineContext) {
  const { editorStore, message } = context

  try {
    const { targetComponentId, targetProperty, updateValue } = action.modifyConfig || action

    if (!targetComponentId || !targetProperty) {
      throw new Error('缺少目标组件ID或属性名')
    }

    const targetNode = editorStore.nodes.find((node) => node.id === targetComponentId)
    if (!targetNode) {
      throw new Error(`目标组件未找到: ${targetComponentId}`)
    }

    const { currentMetadata, currentUnifiedConfig, updatedComponent } = buildUpdatedComponentConfig(
      targetNode,
      targetProperty,
      updateValue
    )

    editorStore.updateNode(targetComponentId, {
      properties: {
        ...targetNode.properties,
        [targetProperty]: updateValue
      },
      metadata: {
        ...currentMetadata,
        unifiedConfig: {
          ...currentUnifiedConfig,
          component: updatedComponent
        },
        lastInteractionUpdate: Date.now()
      }
    })

    notifyExposedComponentConfig(targetComponentId, updatedComponent)
    message.success(`属性已更新: ${targetProperty} = ${updateValue}`)
  } catch (error) {
    logger.error('[InteractionEngine] 属性修改失败:', error)
    message.error(`属性修改失败: ${error instanceof Error ? error.message : String(error)}`)
  }
}

function executeActionWithContext(action: InteractionAction, context: InteractionEngineContext) {
  switch (action.action) {
    case 'jump':
    case 'navigateToUrl':
      executeJumpAction(action, context.message)
      break

    case 'modify':
    case 'updateComponentData':
      executeModifyAction(action, context)
      break

    default:
      logger.warn(`[InteractionEngine] 未知的交互动作类型: ${action.action}`)
      context.message.warning(`未知的交互动作: ${action.action}`)
  }
}

function checkComparisonCondition(operator: string | undefined, actualValue: any, expectedValue: any): boolean {
  switch (operator) {
    case 'equals':
      return actualValue == expectedValue
    case 'notEquals':
      return actualValue != expectedValue
    case 'greaterThan':
      return Number(actualValue) > Number(expectedValue)
    case 'greaterThanOrEqual':
      return Number(actualValue) >= Number(expectedValue)
    case 'lessThan':
      return Number(actualValue) < Number(expectedValue)
    case 'lessThanOrEqual':
      return Number(actualValue) <= Number(expectedValue)
    case 'contains':
      return String(actualValue).includes(String(expectedValue))
    case 'startsWith':
      return String(actualValue).startsWith(String(expectedValue))
    case 'endsWith':
      return String(actualValue).endsWith(String(expectedValue))
    default:
      logger.warn(`[InteractionEngine] 未知的比较操作符: ${operator}`)
      return false
  }
}

function checkRangeCondition(value: any, rangeValue: string): boolean {
  try {
    const numValue = Number(value)

    if (rangeValue.includes('-')) {
      const [min, max] = rangeValue.split('-').map(Number)
      return numValue >= min && numValue <= max
    } else if (rangeValue.startsWith('>')) {
      const min = Number(rangeValue.substring(1))
      return numValue > min
    } else if (rangeValue.startsWith('<')) {
      const max = Number(rangeValue.substring(1))
      return numValue < max
    }

    return false
  } catch (error) {
    logger.error('[InteractionEngine] 范围条件解析失败:', error)
    return false
  }
}

function checkExpressionCondition(value: any, expression: string): boolean {
  try {
    const safeExpression = expression.replace(/value/g, String(value))

    if (/^[\d\s+\-*/.()><=!&|]+$/.test(safeExpression)) {
      return Function(`"use strict"; return (${safeExpression})`)()
    }

    return false
  } catch (error) {
    logger.error('[InteractionEngine] 表达式条件评估失败:', error)
    return false
  }
}

function checkCondition(condition: InteractionEvent['condition'], value: any): boolean {
  if (!condition) return true

  try {
    switch (condition.type) {
      case 'comparison':
        return checkComparisonCondition(condition.operator, value, condition.value)

      case 'range':
        return checkRangeCondition(value, condition.value)

      case 'expression':
        return checkExpressionCondition(value, condition.value)

      default:
        logger.warn(`[InteractionEngine] 未知的条件类型: ${condition.type}`)
        return true
    }
  } catch (error) {
    logger.error('[InteractionEngine] 条件检查失败:', error)
    return false
  }
}

function executeInteractionWithContext(
  interaction: InteractionEvent,
  triggerData: any,
  context: InteractionEngineContext
) {
  if (!interaction.enabled) {
    return
  }

  if (interaction.event === 'dataChange' && interaction.condition && triggerData !== undefined) {
    if (!checkCondition(interaction.condition, triggerData)) {
      return
    }
  }

  interaction.responses.forEach((action) => {
    executeActionWithContext(action, context)
  })
}

function registerPropertyWatcherWithContext(
  componentId: string,
  propertyName: string,
  interactions: InteractionEvent[],
  context: InteractionEngineContext
) {
  const targetNode = context.editorStore.nodes.find((node) => node.id === componentId)
  if (!targetNode) {
    logger.warn(`[InteractionEngine] 注册属性监听失败，组件未找到: ${componentId}`)
    return
  }

  try {
    const targetElement = findComponentElement(componentId)
    if (targetElement?.__vueParentComponent?.exposed?.watchProperty) {
      const unwatch = targetElement.__vueParentComponent.exposed.watchProperty(
        propertyName,
        (newValue: unknown, _oldValue: unknown) => {
          interactions.forEach((interaction) => {
            if (interaction.event === 'dataChange' && interaction.watchedProperty === propertyName) {
              executeInteractionWithContext(interaction, newValue, context)
            }
          })
        }
      )

      return unwatch
    }
  } catch (error) {
    logger.error('[InteractionEngine] 属性监听器注册失败:', error)
  }

  return null
}

/**
 * Create the interaction execution engine.
 */
export function createInteractionEngine() {
  const editorStore = useEditorStore()
  const message = useMessage()
  const context: InteractionEngineContext = { editorStore, message }

  return {
    executeAction: (action: InteractionAction) => executeActionWithContext(action, context),
    executeInteraction: (interaction: InteractionEvent, triggerData?: any) =>
      executeInteractionWithContext(interaction, triggerData, context),
    registerPropertyWatcher: (componentId: string, propertyName: string, interactions: InteractionEvent[]) =>
      registerPropertyWatcherWithContext(componentId, propertyName, interactions, context),
    checkCondition
  }
}

/**
 * Global interaction engine instance.
 */
export const interactionEngine = createInteractionEngine()

/**
 * 文件用途：管理交互系统中组件自定义配置视图的注册、查询和注销。
 * 核心逻辑：使用 Map 维护组件 ID 到配置组件的映射，并提供单例注册表给外部复用。
 * 关键注意事项：注册键必须与组件 ID 保持一致，避免覆盖其他组件的配置入口。
 * 重构建议：后续可补充注册来源、重复注册告警和批量导入导出能力。
 */

export interface IConfigComponent {
  id?: string
  name?: string
  component?: any
  schema?: Record<string, any>
  [key: string]: any
}

interface ConfigComponentRegistration {
  componentId: string
  configComponent: IConfigComponent
}

class ConfigRegistry {
  private registry = new Map<string, IConfigComponent>()

  /**
   * 注册配置组件
   */
  register(componentId: string, configComponent: IConfigComponent) {
    this.registry.set(componentId, configComponent)
  }

  /**
   * 获取配置组件
   */
  get(componentId: string): IConfigComponent | undefined {
    return this.registry.get(componentId)
  }

  /**
   * 检查是否有自定义配置组件
   */
  has(componentId: string): boolean {
    return this.registry.has(componentId)
  }

  /**
   * 获取所有注册的配置组件
   */
  getAll(): ConfigComponentRegistration[] {
    return Array.from(this.registry.entries()).map(([componentId, configComponent]) => ({
      componentId,
      configComponent
    }))
  }

  /**
   * 清除所有注册
   */
  clear() {
    this.registry.clear()
  }

  /**
   * 移除指定组件的配置
   */
  unregister(componentId: string) {
    return this.registry.delete(componentId)
  }
}

// 导出单例
export const configRegistry = new ConfigRegistry()

export default configRegistry

/**
 * 文件用途：执行脚本代码并收集执行结果、日志和性能统计。
 * 核心逻辑：通过沙箱运行代码，封装成功或失败结果，并维护执行次数、耗时和并发状态。
 * 关键注意事项：执行配置中的超时、严格模式和访问权限必须与沙箱安全策略保持一致。
 * 重构建议：可将统计收集、日志捕获和执行调度拆成独立协作者。
 */

import type {
  IScriptExecutor,
  ScriptConfig,
  ScriptExecutionContext,
  ScriptExecutionResult,
  ExecutionStats,
  ScriptLog,
  SandboxConfig,
  ScriptSandboxInstance
} from './types'
import { ScriptSandbox, defaultSandboxConfig } from '@/core/script-engine/sandbox'

/**
 * 脚本执行器实现类
 */
export class ScriptExecutor implements IScriptExecutor {
  private sandbox: ScriptSandbox
  private stats: ExecutionStats
  private executionTimes: number[] = []
  private currentExecutions = 0

  constructor(private readonly sandboxConfig: SandboxConfig = defaultSandboxConfig) {
    this.sandbox = new ScriptSandbox(this.sandboxConfig)
    this.stats = {
      totalExecutions: 0,
      successfulExecutions: 0,
      failedExecutions: 0,
      averageExecutionTime: 0,
      maxExecutionTime: 0,
      minExecutionTime: 0,
      currentConcurrentExecutions: 0
    }
  }

  /**
   * 执行脚本
   */
  async execute<T = unknown>(
    config: ScriptConfig,
    context?: ScriptExecutionContext
  ): Promise<ScriptExecutionResult<T>> {
    const startTime = Date.now()
    const logs: ScriptLog[] = []
    let sandboxEnv: ScriptSandboxInstance | undefined

    // 增加并发计数
    this.currentExecutions++
    this.stats.currentConcurrentExecutions = this.currentExecutions

    try {
      // 验证脚本语法
      const syntaxCheck = this.validateSyntax(config.code)
      if (!syntaxCheck.valid) {
        throw new Error(`脚本语法错误: ${syntaxCheck.error}`)
      }

      // 创建执行环境；必须与执行前安全检查使用同一份策略。
      sandboxEnv = this.sandbox.createSandbox(this.sandboxConfig)

      // 添加上下文变量
      if (context) {
        Object.assign(sandboxEnv, context.variables)
        Object.assign(sandboxEnv, context.functions)
      }

      // 添加自定义全局变量
      if (config.globals) {
        Object.assign(sandboxEnv, config.globals)
      }

      // 添加日志收集器
      sandboxEnv.console = this.createLoggingConsole(logs)

      // 执行脚本
      const timeout = config.timeout || 5000
      const result = await this.sandbox.executeInSandbox(config.code, sandboxEnv, timeout)

      // 计算执行时间
      const executionTime = Date.now() - startTime
      this.updateStats(executionTime, true)

      // 销毁沙箱
      this.sandbox.destroySandbox(sandboxEnv)

      return {
        success: true,
        data: result as T,
        executionTime,
        contextSnapshot: context ? { ...context.variables } : undefined,
        logs
      }
    } catch (error) {
      const executionTime = Date.now() - startTime
      this.updateStats(executionTime, false)

      return {
        success: false,
        error: error as Error,
        executionTime,
        contextSnapshot: context ? { ...context.variables } : undefined,
        logs
      }
    } finally {
      if (sandboxEnv) {
        this.sandbox.destroySandbox(sandboxEnv)
      }

      // 减少并发计数
      this.currentExecutions--
      this.stats.currentConcurrentExecutions = this.currentExecutions
    }
  }

  /**
   * 验证脚本语法
   */
  validateSyntax(code: string): { valid: boolean; error?: string } {
    try {
      // 使用Function构造器验证语法
      new Function(code)
      return { valid: true }
    } catch (error) {
      return {
        valid: false,
        error: (error as Error).message
      }
    }
  }

  /**
   * 获取执行统计
   */
  getExecutionStats(): ExecutionStats {
    return { ...this.stats }
  }

  /**
   * 创建日志收集器
   */
  private createLoggingConsole(logs: ScriptLog[]) {
    const createLogMethod =
      (level: ScriptLog['level']) =>
      (...args: unknown[]) => {
        const log: ScriptLog = {
          level,
          message: args.map(arg => (typeof arg === 'object' ? JSON.stringify(arg) : String(arg))).join(' '),
          timestamp: Date.now(),
          args
        }
        logs.push(log)

        // 同时输出到真实console（带前缀）
        const realConsole = console as Console & Record<string, ((...args: unknown[]) => void) | undefined>
        const loggerFn = realConsole[level]
        if (loggerFn) {
          loggerFn(`[ScriptEngine:${level.toUpperCase()}]`, ...args)
        }
      }

    return {
      log: createLogMethod('log'),
      warn: createLogMethod('warn'),
      error: createLogMethod('error'),
      info: createLogMethod('info'),
      debug: createLogMethod('debug')
    }
  }

  /**
   * 更新执行统计
   */
  private updateStats(executionTime: number, success: boolean): void {
    this.stats.totalExecutions++

    if (success) {
      this.stats.successfulExecutions++
    } else {
      this.stats.failedExecutions++
    }

    // 更新执行时间统计
    this.executionTimes.push(executionTime)

    // 保持最近1000次执行的记录
    if (this.executionTimes.length > 1000) {
      this.executionTimes = this.executionTimes.slice(-1000)
    }

    // 更新时间统计
    this.stats.maxExecutionTime = Math.max(this.stats.maxExecutionTime, executionTime)
    this.stats.minExecutionTime =
      this.stats.minExecutionTime === 0 ? executionTime : Math.min(this.stats.minExecutionTime, executionTime)

    this.stats.averageExecutionTime =
      this.executionTimes.reduce((sum, time) => sum + time, 0) / this.executionTimes.length
  }

  /**
   * 重置统计信息
   */
  resetStats(): void {
    this.stats = {
      totalExecutions: 0,
      successfulExecutions: 0,
      failedExecutions: 0,
      averageExecutionTime: 0,
      maxExecutionTime: 0,
      minExecutionTime: 0,
      currentConcurrentExecutions: this.currentExecutions
    }
    this.executionTimes = []
  }
}

/**
 * 默认脚本配置
 */
export const defaultScriptConfig: ScriptConfig = {
  code: '',
  timeout: 5000,
  strictMode: true,
  asyncSupport: true,
  maxMemory: 50 * 1024 * 1024, // 50MB
  allowNetworkAccess: false,
  allowFileSystemAccess: false
}

/**
 * 文件用途：验证脚本沙箱的安全加固规则和执行器的危险代码拦截行为。
 * 核心逻辑：构造默认沙箱与执行器，覆盖计时器暴露、构造器逃逸、原型访问等攻击路径。
 * 关键注意事项：这些用例是安全回归防线，放宽断言前需要确认不会恢复宿主逃逸风险。
 * 重构建议：可按攻击类型拆分测试分组，并补充新规则的负向与正向样例。
 */
import { describe, expect, it, vi } from 'vitest'

import { ScriptExecutor } from './executor'
import { ScriptSandbox, defaultSandboxConfig } from './sandbox'

const createSandbox = () => new ScriptSandbox(defaultSandboxConfig)

describe('ScriptSandbox security hardening', () => {
  it('does not expose host timers by default', () => {
    const sandbox = createSandbox().createSandbox(defaultSandboxConfig)

    expect(defaultSandboxConfig.allowedGlobals).not.toContain('setTimeout')
    expect(defaultSandboxConfig.allowedGlobals).not.toContain('setInterval')
    expect(sandbox.setTimeout).toBeUndefined()
    expect(sandbox.setInterval).toBeUndefined()
  })

  it('blocks ambient host fetch instead of falling through the sandbox scope', async () => {
    const fetchSpy = vi.spyOn(globalThis, 'fetch')
    const sandbox = createSandbox()
    const env = sandbox.createSandbox(defaultSandboxConfig)

    await expect(sandbox.executeInSandbox("return fetch('https://example.test/data')", env)).rejects.toThrow(
      'SCRIPT_NETWORK_EXTERNAL_BLOCKED'
    )
    expect(fetchSpy).not.toHaveBeenCalled()

    fetchSpy.mockRestore()
  })

  it('keeps an explicitly requested fetch global externally blocked', async () => {
    const fetchSpy = vi.spyOn(globalThis, 'fetch')
    const config = {
      ...defaultSandboxConfig,
      allowedGlobals: [...defaultSandboxConfig.allowedGlobals, 'fetch']
    }
    const sandbox = new ScriptSandbox(config)
    const env = sandbox.createSandbox(config)

    await expect(env.fetch('https://example.test/data')).rejects.toThrow('SCRIPT_NETWORK_EXTERNAL_BLOCKED')
    expect(fetchSpy).not.toHaveBeenCalled()

    fetchSpy.mockRestore()
  })

  it('prevents custom globals from restoring blocked network constructors', async () => {
    const constructorNames = [
      'WebSocket',
      'XMLHttpRequest',
      'EventSource',
      'Worker',
      'SharedWorker',
      'BroadcastChannel'
    ] as const

    for (const constructorName of constructorNames) {
      const injectedConstructor = vi.fn()
      const executor = new ScriptExecutor()
      const result = await executor.execute({
        code: `return new ${constructorName}('https://example.test/socket')`,
        globals: { [constructorName]: injectedConstructor }
      })

      expect(result.success).toBe(false)
      expect(result.error?.message).toContain('SCRIPT_NETWORK_EXTERNAL_BLOCKED')
      expect(injectedConstructor).not.toHaveBeenCalled()
    }
  })

  it('prevents custom globals from restoring host storage access', async () => {
    const injectedStorage = { getItem: vi.fn().mockReturnValue('secret') }
    const executor = new ScriptExecutor()
    const result = await executor.execute({
      code: "return localStorage.getItem('token')",
      globals: { localStorage: injectedStorage }
    })

    expect(result.success).toBe(false)
    expect(result.error?.message).toContain('SCRIPT_STORAGE_EXTERNAL_BLOCKED')
    expect(injectedStorage.getItem).not.toHaveBeenCalled()
  })

  it('preserves network utility contracts while explicitly blocking external access', async () => {
    const fetchSpy = vi.spyOn(globalThis, 'fetch')
    const env = createSandbox().createSandbox(defaultSandboxConfig)
    const { networkUtils } = env._utils

    await expect(networkUtils.httpGet('https://example.test/data')).rejects.toThrow(
      'SCRIPT_NETWORK_EXTERNAL_BLOCKED'
    )
    await expect(networkUtils.httpPost('https://example.test/data', { value: 1 })).rejects.toThrow(
      'SCRIPT_NETWORK_EXTERNAL_BLOCKED'
    )
    await expect(networkUtils.httpPut('https://example.test/data', { value: 2 })).rejects.toThrow(
      'SCRIPT_NETWORK_EXTERNAL_BLOCKED'
    )
    await expect(networkUtils.httpDelete('https://example.test/data')).rejects.toThrow(
      'SCRIPT_NETWORK_EXTERNAL_BLOCKED'
    )
    expect(fetchSpy).not.toHaveBeenCalled()

    fetchSpy.mockRestore()
  })

  it('rejects constructor.constructor bracket escapes', async () => {
    const sandbox = createSandbox()
    const env = sandbox.createSandbox(defaultSandboxConfig)

    await expect(
      sandbox.executeInSandbox('return ({})["constructor"]["constructor"]("return globalThis")()', env)
    ).rejects.toThrow()
  })

  it('rejects prototype bracket access', () => {
    const result = createSandbox().checkCodeSecurity('Object["prototype"]["polluted"] = true')

    expect(result.safe).toBe(false)
    expect(result.issues.length).toBeGreaterThan(0)
  })

  it('does not let compatibility flags disable hard security checks', () => {
    const permissiveConfig = {
      ...defaultSandboxConfig,
      enabled: false,
      blockedGlobals: [],
      allowEval: true,
      allowFunction: true,
      allowPrototypePollution: true
    }
    const sandbox = new ScriptSandbox(permissiveConfig)

    expect(sandbox.checkCodeSecurity('return eval("1 + 1")').safe).toBe(false)
    expect(sandbox.checkCodeSecurity('return new Function("return 1")()').safe).toBe(false)
    expect(sandbox.checkCodeSecurity('Object["prototype"].polluted = true').safe).toBe(false)
  })

  it('rejects direct host global references', () => {
    const sandbox = createSandbox()

    expect(sandbox.checkCodeSecurity('return globalThis.localStorage').safe).toBe(false)
    expect(sandbox.checkCodeSecurity('return this["constructor"]').safe).toBe(false)
  })

  it('rejects obvious non-preemptible infinite loops before execution', () => {
    const sandbox = createSandbox()

    expect(sandbox.checkCodeSecurity('while (true) {}').safe).toBe(false)
    expect(sandbox.checkCodeSecurity('for (;;) {}').safe).toBe(false)
  })
})

describe('ScriptExecutor sandbox hardening', () => {
  it('blocks direct interval escape through the host global', async () => {
    const setIntervalSpy = vi.spyOn(globalThis, 'setInterval')
    const executor = new ScriptExecutor()

    const result = await executor.execute({
      code: 'setInterval(() => {}, 1); return 1',
      timeout: 50
    })

    expect(result.success).toBe(false)
    expect(setIntervalSpy).not.toHaveBeenCalled()

    setIntervalSpy.mockRestore()
  })

  it('does not allow custom globals to replace the blocked network adapter', async () => {
    const injectedFetch = vi.fn().mockResolvedValue({ ok: true })
    const executor = new ScriptExecutor()

    const result = await executor.execute({
      code: "return fetch('https://example.test/data')",
      timeout: 50,
      globals: { fetch: injectedFetch },
      allowNetworkAccess: true
    })

    expect(result.success).toBe(false)
    expect(result.error?.message).toContain('SCRIPT_NETWORK_EXTERNAL_BLOCKED')
    expect(injectedFetch).not.toHaveBeenCalled()
  })

  it('blocks async interval escape through the host global', async () => {
    const setIntervalSpy = vi.spyOn(globalThis, 'setInterval')
    const executor = new ScriptExecutor()

    const result = await executor.execute({
      code: 'await Promise.resolve().then(() => setInterval(() => {}, 1)); return 1',
      timeout: 50
    })

    expect(result.success).toBe(false)
    expect(setIntervalSpy).not.toHaveBeenCalled()

    setIntervalSpy.mockRestore()
  })

  it('fails obvious dead-loop scripts without entering execution', async () => {
    const executor = new ScriptExecutor()

    const result = await executor.execute({
      code: 'while (true) {}',
      timeout: 50
    })

    expect(result.success).toBe(false)
    expect(result.error?.message).toContain('明显无限while循环')
  })
})

/**
 * 文件用途：提供脚本安全沙箱，限制用户脚本可访问的全局对象和危险语法。
 * 核心逻辑：创建受控执行上下文，执行前做安全检查，并在超时或违规时阻断脚本。
 * 关键注意事项：任何放宽全局对象或语法规则的改动都可能扩大宿主环境暴露面。
 * 重构建议：可补充更系统的策略对象和审计日志，便于按场景配置安全级别。
 */

import type {
  BuiltinUtilities,
  IScriptSandbox,
  SandboxConfig,
  ScriptSandboxInstance,
  ScriptSandboxTimerRecord
} from '@/core/script-engine/types'
import { smartDeepClone } from '@/utils/deep-clone'

type SandboxTimerId = ReturnType<typeof setTimeout> | ReturnType<typeof setInterval>

/**
 * 脚本沙箱实现类
 */
export class ScriptSandbox implements IScriptSandbox {
  private config: SandboxConfig

  constructor(config: SandboxConfig) {
    this.config = config
  }

  /**
   * 创建沙箱环境
   */
  createSandbox(config: SandboxConfig): ScriptSandboxInstance {
    const sandbox: ScriptSandboxInstance = {}
    const blockedNetworkFetch = this.createBlockedNetworkFetch()
    const blockedNetworkConstructor = function (): never {
      throw new Error('SCRIPT_NETWORK_EXTERNAL_BLOCKED: script network access requires an audited adapter')
    }
    // with 作用域会向宿主全局回落；不可覆盖访问器既遮蔽网络入口，
    // 也防止 context/globals 通过 Object.assign 重新开启宿主网络能力。
    const blockedNetworkGlobals = {
      fetch: blockedNetworkFetch,
      WebSocket: blockedNetworkConstructor,
      XMLHttpRequest: blockedNetworkConstructor,
      EventSource: blockedNetworkConstructor,
      Worker: blockedNetworkConstructor,
      SharedWorker: blockedNetworkConstructor,
      BroadcastChannel: blockedNetworkConstructor
    }
    Object.entries(blockedNetworkGlobals).forEach(([name, blockedValue]) => {
      Object.defineProperty(sandbox, name, {
        configurable: true,
        enumerable: true,
        get: () => blockedValue,
        set: () => {}
      })
    })

    const blockedHostGlobals = {
      localStorage: 'SCRIPT_STORAGE_EXTERNAL_BLOCKED',
      sessionStorage: 'SCRIPT_STORAGE_EXTERNAL_BLOCKED',
      indexedDB: 'SCRIPT_STORAGE_EXTERNAL_BLOCKED',
      caches: 'SCRIPT_STORAGE_EXTERNAL_BLOCKED',
      window: 'SCRIPT_HOST_GLOBAL_BLOCKED',
      document: 'SCRIPT_HOST_GLOBAL_BLOCKED',
      location: 'SCRIPT_HOST_GLOBAL_BLOCKED',
      navigator: 'SCRIPT_HOST_GLOBAL_BLOCKED'
    }
    Object.entries(blockedHostGlobals).forEach(([name, errorCode]) => {
      Object.defineProperty(sandbox, name, {
        configurable: true,
        enumerable: true,
        get: () => {
          throw new Error(`${errorCode}: ${name} is not available in the script sandbox`)
        },
        set: () => {}
      })
    })

    // 添加允许的全局对象
    config.allowedGlobals.forEach((global) => {
      switch (global) {
        case 'Math':
          sandbox.Math = Math
          break
        case 'Date':
          sandbox.Date = Date
          break
        case 'JSON':
          sandbox.JSON = JSON
          break
        case 'Promise':
          sandbox.Promise = Promise
          break
        case 'setTimeout':
          sandbox.setTimeout = this.createSafeSetTimeout(sandbox)
          break
        case 'clearTimeout':
          sandbox.clearTimeout = this.createSafeClearTimeout(sandbox)
          break
        case 'setInterval':
          sandbox.setInterval = this.createSafeSetInterval(sandbox)
          break
        case 'clearInterval':
          sandbox.clearInterval = this.createSafeClearInterval(sandbox)
          break
        case 'fetch':
          // 网络能力需要可取消、可审计的专用适配器；当前只保留接口并明确阻断外联。
          sandbox.fetch = this.createBlockedNetworkFetch()
          break
        case 'console':
          // 提供安全的console实现
          sandbox.console = this.createSafeConsole()
          break
        default:
          // 其他安全的全局对象
          if (typeof window !== 'undefined' && global in window) {
            const value: unknown = Reflect.get(window, global)
            if (typeof value !== 'function' || this.isSafeFunction(global)) {
              sandbox[global] = value
            }
          }
      }
    })

    // 添加安全的内置工具
    sandbox._utils = this.createBuiltinUtils()

    return sandbox
  }

  /**
   * 在沙箱中执行代码
   */
  async executeInSandbox(code: string, sandbox: ScriptSandboxInstance, timeout: number = 5000): Promise<unknown> {
    // 检查代码安全性
    const securityCheck = this.checkCodeSecurity(code)
    if (!securityCheck.safe) {
      throw new Error(`代码安全检查失败: ${securityCheck.issues.join(', ')}`)
    }

    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(new Error('脚本执行超时'))
      }, timeout)

      try {
        // 创建安全的执行函数
        const wrappedCode = this.wrapCodeForExecution(code)
        const executor = new Function(
          'sandbox',
          `
          with (sandbox) {
            return (async function() {
              ${wrappedCode}
            })();
          }
        `
        )

        // 执行代码
        const result = executor(sandbox)

        if (result instanceof Promise) {
          result
            .then((value) => {
              clearTimeout(timeoutId)
              resolve(value)
            })
            .catch((error) => {
              clearTimeout(timeoutId)
              reject(error)
            })
        } else {
          clearTimeout(timeoutId)
          resolve(result)
        }
      } catch (error) {
        clearTimeout(timeoutId)
        reject(error)
      }
    })
  }

  /**
   * 销毁沙箱
   */
  destroySandbox(sandbox: ScriptSandboxInstance): void {
    // 清理沙箱中的定时器
    if (sandbox._timers) {
      sandbox._timers.forEach((timer) => {
        if (timer.type === 'timeout') {
          clearTimeout(timer.id)
        } else if (timer.type === 'interval') {
          clearInterval(timer.id)
        }
      })
      sandbox._timers = []
    }

    // 清空沙箱对象
    Object.keys(sandbox).forEach((key) => {
      delete sandbox[key]
    })
  }

  /**
   * 检查代码安全性
   */
  checkCodeSecurity(code: string): { safe: boolean; issues: string[] } {
    const issues: string[] = []

    // This is a same-thread guardrail, not a full isolation boundary. Do not
    // treat user code as safely sandboxed until it runs in a worker/AST allowlist.
    // 检查是否包含危险关键字
    const dangerousPatterns = [
      /eval\s*\(/,
      /Function\s*\(/,
      /new\s+Function/,
      /import\s*\(/,
      /require\s*\(/,
      /process\./,
      /global\./,
      /globalThis\b/,
      /window\./,
      /document\./,
      /location\./,
      /navigator\./,
      /\bthis\s*(?:\.|\[)/,
      /__proto__/,
      /(?:\.|\[['"`])\s*constructor\s*(?:['"`\]]|\.)/,
      /(?:\.|\[['"`])\s*prototype\s*(?:['"`\]]|\.)/,
      /\bwhile\s*\(\s*(?:true|1)\s*\)/,
      /\bfor\s*\(\s*;\s*;\s*\)/
    ]

    dangerousPatterns.forEach((pattern, index) => {
      if (pattern.test(code)) {
        const patternNames = [
          'eval函数调用',
          'Function构造器',
          'new Function',
          '动态import',
          'require调用',
          'process对象访问',
          'global对象访问',
          'globalThis对象访问',
          'window对象访问',
          'document对象访问',
          'location对象访问',
          'navigator对象访问',
          'this宿主对象访问',
          '__proto__属性访问',
          'constructor属性访问',
          'prototype属性访问',
          '明显无限while循环',
          '明显无限for循环'
        ]
        issues.push(`检测到危险代码模式: ${patternNames[index]}`)
      }
    })

    // 检查自定义安全策略
    if (this.config.customSecurityPolicy) {
      if (!this.config.customSecurityPolicy(code)) {
        issues.push('自定义安全策略检查失败')
      }
    }

    return {
      safe: issues.length === 0,
      issues
    }
  }

  /**
   * 包装代码以便安全执行
   */
  private wrapCodeForExecution(code: string): string {
    // Same-thread execution cannot preempt synchronous loops; reject the known
    // dangerous shapes before this wrapper and keep the user function strict.
    return `
      "use strict";
      // eval 调用由执行前安全检查拦截；严格模式禁止声明名为 eval 的绑定。
      const Function = undefined;
      const require = undefined;
      const setTimeout = undefined;
      const clearTimeout = undefined;
      const setInterval = undefined;
      const clearInterval = undefined;
      const globalThis = undefined;
      // 注意：不能定义 import 变量，因为它是保留字

      // 用户代码
      ${code}
    `
  }

  /**
   * 创建安全的console实现
   */
  private createSafeConsole(): BuiltinUtilities['logger'] & {
    _getLogs: () => Array<{ level: string; args: unknown[]; timestamp: number }>
  } {
    const logs: Array<{ level: string; args: unknown[]; timestamp: number }> = []

    return {
      log: (...args: unknown[]) => {
        logs.push({ level: 'log', args, timestamp: Date.now() })
      },
      warn: (...args: unknown[]) => {
        logs.push({ level: 'warn', args, timestamp: Date.now() })
      },
      error: (...args: unknown[]) => {
        logs.push({ level: 'error', args, timestamp: Date.now() })
      },
      info: (...args: unknown[]) => {
        logs.push({ level: 'info', args, timestamp: Date.now() })
      },
      debug: (...args: unknown[]) => {
        logs.push({ level: 'debug', args, timestamp: Date.now() })
      },
      _getLogs: () => logs
    }
  }

  private createBlockedNetworkFetch(): typeof fetch {
    return async () => {
      throw new Error('SCRIPT_NETWORK_EXTERNAL_BLOCKED: script network access requires an audited adapter')
    }
  }

  private ensureTimerStore(sandbox: ScriptSandboxInstance): ScriptSandboxTimerRecord[] {
    if (!sandbox._timers) {
      sandbox._timers = []
    }
    return sandbox._timers
  }

  private removeTimer(sandbox: ScriptSandboxInstance, id: SandboxTimerId): void {
    if (!sandbox._timers) {
      return
    }
    sandbox._timers = sandbox._timers.filter((timer) => timer.id !== id)
  }

  private createSafeSetTimeout(sandbox: ScriptSandboxInstance) {
    return (handler: TimerHandler, timeout?: number, ...args: unknown[]) => {
      const timerId = setTimeout(handler, timeout, ...args)
      this.ensureTimerStore(sandbox).push({ type: 'timeout', id: timerId })
      return timerId
    }
  }

  private createSafeClearTimeout(sandbox: ScriptSandboxInstance) {
    return (timerId: SandboxTimerId) => {
      clearTimeout(timerId)
      this.removeTimer(sandbox, timerId)
    }
  }

  private createSafeSetInterval(sandbox: ScriptSandboxInstance) {
    return (handler: TimerHandler, timeout?: number, ...args: unknown[]) => {
      const timerId = setInterval(handler, timeout, ...args)
      this.ensureTimerStore(sandbox).push({ type: 'interval', id: timerId })
      return timerId
    }
  }

  private createSafeClearInterval(sandbox: ScriptSandboxInstance) {
    return (timerId: SandboxTimerId) => {
      clearInterval(timerId)
      this.removeTimer(sandbox, timerId)
    }
  }

  /**
   * 创建内置工具函数
   */
  private createBuiltinUtils(): BuiltinUtilities {
    return {
      // 数据生成工具
      mockData: {
        randomNumber: (min = 0, max = 100) => Math.random() * (max - min) + min,
        randomString: (length = 10) =>
          Math.random()
            .toString(36)
            .substring(2, length + 2),
        randomBoolean: () => Math.random() > 0.5,
        randomDate: (start?: Date, end?: Date) => {
          const startTime = start ? start.getTime() : Date.now() - 365 * 24 * 60 * 60 * 1000
          const endTime = end ? end.getTime() : Date.now()
          return new Date(startTime + Math.random() * (endTime - startTime))
        },
        randomArray: <T>(items: T[], count?: number) => {
          const actualCount = count || Math.floor(Math.random() * items.length) + 1
          const result: T[] = []
          for (let i = 0; i < actualCount; i++) {
            result.push(items[Math.floor(Math.random() * items.length)])
          }
          return result
        },
        randomObject: (template: Record<string, unknown>) => {
          const result: Record<string, unknown> = {}
          Object.keys(template).forEach((key) => {
            const value = template[key]
            if (typeof value === 'function') {
              result[key] = value()
            } else {
              result[key] = value
            }
          })
          return result
        }
      },

      // 数据处理工具
      dataUtils: {
        deepClone: <T>(obj: T): T => smartDeepClone(obj),
        merge: (...objects: unknown[]) => {
          const merged: Record<string, unknown> = {}
          objects.forEach((obj) => Object.assign(merged, obj))
          return merged
        },
        pick: <T extends Record<string, unknown>>(obj: T, keys: (keyof T)[]): Partial<T> => {
          const result: Partial<T> = {}
          keys.forEach((key) => {
            if (key in obj) {
              result[key] = obj[key]
            }
          })
          return result
        },
        omit: <T extends Record<string, unknown>>(obj: T, keys: (keyof T)[]): Partial<T> => {
          const result: Partial<T> = {}
          Object.keys(obj).forEach((key) => {
            if (!keys.includes(key as keyof T)) {
              result[key as keyof T] = obj[key as keyof T]
            }
          })
          return result
        },
        groupBy: <T>(array: T[], key: keyof T | ((item: T) => unknown)): Record<string, T[]> => {
          const result: Record<string, T[]> = {}
          array.forEach((item) => {
            const groupKey = typeof key === 'function' ? key(item) : item[key]
            const groupKeyStr = String(groupKey)
            if (!result[groupKeyStr]) {
              result[groupKeyStr] = []
            }
            result[groupKeyStr].push(item)
          })
          return result
        },
        sortBy: <T>(array: T[], key: keyof T | ((item: T) => unknown)): T[] => {
          return [...array].sort((a, b) => {
            const aVal = (typeof key === 'function' ? key(a) : a[key]) as string | number
            const bVal = (typeof key === 'function' ? key(b) : b[key]) as string | number
            if (aVal < bVal) return -1
            if (aVal > bVal) return 1
            return 0
          })
        }
      },

      // 时间工具
      timeUtils: {
        now: () => Date.now(),
        format: (date: Date | number, format: string = 'YYYY-MM-DD HH:mm:ss') => {
          const d = new Date(date)
          const year = d.getFullYear()
          const month = String(d.getMonth() + 1).padStart(2, '0')
          const day = String(d.getDate()).padStart(2, '0')
          const hours = String(d.getHours()).padStart(2, '0')
          const minutes = String(d.getMinutes()).padStart(2, '0')
          const seconds = String(d.getSeconds()).padStart(2, '0')

          return format
            .replace('YYYY', year.toString())
            .replace('MM', month)
            .replace('DD', day)
            .replace('HH', hours)
            .replace('mm', minutes)
            .replace('ss', seconds)
        },
        addDays: (date: Date, days: number) => {
          const result = new Date(date)
          result.setDate(result.getDate() + days)
          return result
        },
        diffDays: (date1: Date, date2: Date) => {
          const timeDiff = Math.abs(date2.getTime() - date1.getTime())
          return Math.ceil(timeDiff / (1000 * 3600 * 24))
        },
        startOfDay: (date: Date) => {
          const result = new Date(date)
          result.setHours(0, 0, 0, 0)
          return result
        },
        endOfDay: (date: Date) => {
          const result = new Date(date)
          result.setHours(23, 59, 59, 999)
          return result
        }
      },

      // 保留网络工具接口；未接入可取消、可审计的适配器前明确阻断外联。
      networkUtils: {
        httpGet: (url: string, options?: RequestInit) => this.rejectExternalNetwork(url, options),
        httpPost: (url: string, data: unknown, options?: RequestInit) => this.rejectExternalNetwork(url, data, options),
        httpPut: (url: string, data: unknown, options?: RequestInit) => this.rejectExternalNetwork(url, data, options),
        httpDelete: (url: string, options?: RequestInit) => this.rejectExternalNetwork(url, options)
      },

      // 日志接口使用本地收集器，不向外部服务发送数据。
      logger: this.createSafeConsole()
    }
  }

  private rejectExternalNetwork(..._args: unknown[]): Promise<never> {
    return Promise.reject(new Error('SCRIPT_NETWORK_EXTERNAL_BLOCKED: script network access requires an audited adapter'))
  }

  /**
   * 检查函数是否安全
   */
  private isSafeFunction(funcName: string): boolean {
    const safeFunctions = [
      'parseInt',
      'parseFloat',
      'isNaN',
      'isFinite',
      'encodeURIComponent',
      'decodeURIComponent',
      'encodeURI',
      'decodeURI'
    ]
    return safeFunctions.includes(funcName)
  }
}

/**
 * 默认沙箱配置
 */
export const defaultSandboxConfig: SandboxConfig = {
  enabled: true,
  allowedGlobals: ['Math', 'Date', 'JSON', 'Promise', 'console', 'parseInt', 'parseFloat', 'isNaN', 'isFinite'],
  blockedGlobals: [
    'eval',
    'Function',
    'window',
    'document',
    'location',
    'navigator',
    'process',
    'global',
    'require',
    'import'
  ],
  allowEval: false,
  allowFunction: false,
  allowPrototypePollution: false
}

import { describe, expect, it } from 'vitest'

import { defaultSandboxConfig } from './sandbox'
import { ScriptEngine } from './script-engine'

describe('ScriptEngine sandbox configuration', () => {
  it('uses the same custom security policy for checks and execution', async () => {
    const engine = new ScriptEngine({
      sandboxConfig: {
        ...defaultSandboxConfig,
        customSecurityPolicy: code => !code.includes('blockedCall')
      }
    })
    const blockedCode = 'return blockedCall()'

    expect(engine.checkScriptSecurity(blockedCode)).toEqual({
      safe: false,
      issues: ['自定义安全策略检查失败']
    })

    const result = await engine.execute(blockedCode)
    expect(result.success).toBe(false)
    expect(result.error?.message).toContain('代码安全检查失败: 自定义安全策略检查失败')
    expect(result.error?.message).not.toContain('blockedCall is not defined')
  })

  it('still executes code accepted by the custom security policy', async () => {
    const engine = new ScriptEngine({
      sandboxConfig: {
        ...defaultSandboxConfig,
        customSecurityPolicy: code => !code.includes('blockedCall')
      }
    })

    const result = await engine.execute<number>('return 42')

    expect(result.success).toBe(true)
    expect(result.data).toBe(42)
  })

  it('applies an updated sandbox policy to checks and subsequent executions', async () => {
    const engine = new ScriptEngine()
    const code = 'return blockedAfterUpdate()'

    expect(engine.checkScriptSecurity(code).safe).toBe(true)

    engine.updateConfig({
      sandboxConfig: {
        ...defaultSandboxConfig,
        customSecurityPolicy: candidate => !candidate.includes('blockedAfterUpdate')
      }
    })

    expect(engine.checkScriptSecurity(code)).toEqual({
      safe: false,
      issues: ['自定义安全策略检查失败']
    })
    const result = await engine.execute(code)
    expect(result.success).toBe(false)
    expect(result.error?.message).toContain('代码安全检查失败: 自定义安全策略检查失败')
  })
})

/**
 * 文件用途：组合执行器、沙箱、模板管理器和上下文管理器，提供统一脚本引擎门面。
 * 核心逻辑：初始化默认配置与内置模板，对外暴露直接执行、模板执行和状态统计能力。
 * 关键注意事项：默认实例会被多个调用方共享，配置变更需要谨慎评估全局影响。
 * 重构建议：可将门面层与默认实例创建分离，便于测试和多实例注入。
 */

import type {
  IScriptEngine,
  IScriptExecutor,
  IScriptSandbox,
  IScriptTemplateManager,
  IScriptContextManager,
  ScriptEngineConfig,
  ScriptEngineStateSnapshot,
  ScriptExecutionResult,
  ScriptExecutionContext,
  ScriptTemplate,
  ScriptConfig
} from './types'
import { ScriptExecutor, defaultScriptConfig } from '@/core/script-engine/executor'
import { ScriptSandbox, defaultSandboxConfig } from '@/core/script-engine/sandbox'
import { ScriptTemplateManager } from '@/core/script-engine/template-manager'
import { ScriptContextManager } from '@/core/script-engine/context-manager'
import { initializeBuiltInTemplates } from '@/core/script-engine/templates/built-in-templates'

/**
 * 主脚本引擎实现类
 */
export class ScriptEngine implements IScriptEngine {
  public executor: IScriptExecutor
  public sandbox: IScriptSandbox
  public readonly templateManager: IScriptTemplateManager
  public readonly contextManager: IScriptContextManager

  private config: ScriptEngineConfig

  constructor(config?: Partial<ScriptEngineConfig>) {
    this.config = {
      defaultScriptConfig,
      sandboxConfig: defaultSandboxConfig,
      enableCache: true,
      cacheTTL: 5 * 60 * 1000, // 5分钟
      maxConcurrentExecutions: 10,
      enablePerformanceMonitoring: true,
      ...config
    }

    // 检查与实际执行共享同一份沙箱策略，避免配置只影响预检查。
    this.executor = new ScriptExecutor(this.config.sandboxConfig)
    this.sandbox = new ScriptSandbox(this.config.sandboxConfig)
    this.templateManager = new ScriptTemplateManager()
    this.contextManager = new ScriptContextManager()

    initializeBuiltInTemplates(this.templateManager)
  }

  /**
   * 快速执行脚本
   */
  async execute<T = unknown>(code: string, context?: Record<string, unknown>): Promise<ScriptExecutionResult<T>> {
    // 创建脚本配置
    const scriptConfig: ScriptConfig = {
      ...this.config.defaultScriptConfig,
      code
    }

    // 创建或获取执行上下文
    let executionContext = undefined
    if (context) {
      executionContext = this.contextManager.createContext('临时上下文', context)
    }

    try {
      const result = await this.executor.execute<T>(scriptConfig, executionContext)

      // 清理临时上下文
      if (executionContext) {
        this.contextManager.deleteContext(executionContext.id)
      }
      return result
    } catch (error) {
      // 清理临时上下文
      if (executionContext) {
        this.contextManager.deleteContext(executionContext.id)
      }
      throw error
    }
  }

  /**
   * 使用模板执行
   */
  async executeTemplate<T = unknown>(
    templateId: string,
    parameters: Record<string, unknown>
  ): Promise<ScriptExecutionResult<T>> {
    // 根据模板生成代码
    const code = this.templateManager.generateCode(templateId, parameters)

    // 执行生成的代码
    return await this.execute<T>(code)
  }

  /**
   * 批量执行脚本
   */
  async executeBatch<T = unknown>(
    scripts: Array<{ code: string; context?: Record<string, unknown> }>
  ): Promise<ScriptExecutionResult<T>[]> {
    const promises = scripts.map(script => this.execute<T>(script.code, script.context))
    return await Promise.all(promises)
  }

  /**
   * 执行脚本并返回流式结果
   */
  async executeStream<T = unknown>(
    code: string,
    context?: Record<string, unknown>,
    onUpdate?: (result: Partial<ScriptExecutionResult<T>>) => void
  ): Promise<ScriptExecutionResult<T>> {
    // 创建脚本配置
    const scriptConfig: ScriptConfig = {
      ...this.config.defaultScriptConfig,
      code
    }

    // 创建执行上下文
    let executionContext = undefined
    if (context) {
      executionContext = this.contextManager.createContext('流式上下文', context)
    }

    try {
      // 如果提供了更新回调，先发送开始状态
      if (onUpdate) {
        onUpdate({
          success: false,
          executionTime: 0,
          logs: [
            {
              level: 'info',
              message: '脚本开始执行...',
              timestamp: Date.now()
            }
          ]
        })
      }

      const result = await this.executor.execute<T>(scriptConfig, executionContext)

      // 发送最终结果
      if (onUpdate) {
        onUpdate(result)
      }

      // 清理上下文
      if (executionContext) {
        this.contextManager.deleteContext(executionContext.id)
      }

      return result
    } catch (error) {
      // 清理上下文
      if (executionContext) {
        this.contextManager.deleteContext(executionContext.id)
      }

      throw error
    }
  }

  /**
   * 验证脚本语法
   */
  validateScript(code: string): { valid: boolean; error?: string } {
    return this.executor.validateSyntax(code)
  }

  /**
   * 检查脚本安全性
   */
  checkScriptSecurity(code: string): { safe: boolean; issues: string[] } {
    return this.sandbox.checkCodeSecurity(code)
  }

  /**
   * 获取执行统计信息
   */
  getExecutionStats() {
    return {
      executor: this.executor.getExecutionStats(),
      templates: {
        total: this.templateManager.getAllTemplates().length,
        byCategory: this.getTemplatesByCategory()
      },
      contexts: {
        total: this.contextManager.getAllContexts().length,
        active: this.contextManager.getAllContexts().filter(
          ctx => Date.now() - ctx.updatedAt < 24 * 60 * 60 * 1000 // 24小时内活跃
        ).length
      }
    }
  }

  /**
   * 获取按分类统计的模板数量
   */
  private getTemplatesByCategory(): Record<string, number> {
    const templates = this.templateManager.getAllTemplates()
    const stats: Record<string, number> = {}

    templates.forEach(template => {
      stats[template.category] = (stats[template.category] || 0) + 1
    })

    return stats
  }

  /**
   * 获取引擎配置
   */
  getConfig(): ScriptEngineConfig {
    return { ...this.config }
  }

  /**
   * 更新引擎配置。
   * 沙箱策略变更会重建安全检查器和执行器，后续执行立即采用新策略；
   * 重建执行器也会重置其进程内执行统计。
   */
  updateConfig(config: Partial<ScriptEngineConfig>): void {
    this.config = { ...this.config, ...config }

    if (config.sandboxConfig) {
      this.executor = new ScriptExecutor(this.config.sandboxConfig)
      this.sandbox = new ScriptSandbox(this.config.sandboxConfig)
    }
  }

  /**
   * 预热引擎（执行一些初始化脚本以提高后续性能）
   */
  async warmup(): Promise<void> {
    const warmupScripts = [
      'return { device_id: "replace_with_device_id", online: true }',
      'return Math.round((20 + Math.random() * 5) * 10) / 10',
      'return { timestamp: new Date().toISOString(), metric: "temperature" }',
      'return [20, 21, 22].map(value => ({ metric: "temperature", value }))'
    ]

    for (const script of warmupScripts) {
      try {
        await this.execute(script)
      } catch (error) {
        /* intentionally empty */
      }
    }
  }

  /**
   * 清理资源
   */
  cleanup(): void {
    // 清理所有上下文
    const contexts = this.contextManager.getAllContexts()
    contexts.forEach(context => {
      this.contextManager.deleteContext(context.id)
    })
  }

  /**
   * 导出引擎状态
   */
  exportState(): ScriptEngineStateSnapshot {
    return {
      config: this.config,
      stats: this.getExecutionStats(),
      templates: this.templateManager.getAllTemplates(),
      contexts: this.contextManager.getAllContexts(),
      timestamp: new Date().toISOString()
    }
  }

  /**
   * 导入引擎状态
   */
  importState(state: unknown): boolean {
    try {
      if (typeof state !== 'object' || state === null) {
        return false
      }
      const stateRecord = state as Record<string, unknown>

      // 导入配置
      if (stateRecord.config) {
        this.updateConfig(stateRecord.config as Partial<ScriptEngineConfig>)
      }

      // 导入模板
      if (stateRecord.templates && Array.isArray(stateRecord.templates)) {
        for (const template of stateRecord.templates) {
          if (!template || typeof template !== 'object') continue
          if (!(template as { isSystem?: unknown }).isSystem) {
            // 只导入非系统模板
            this.templateManager.createTemplate(template as Omit<ScriptTemplate, 'id' | 'createdAt' | 'updatedAt'>)
          }
        }
      }

      // 导入上下文
      if (stateRecord.contexts && Array.isArray(stateRecord.contexts)) {
        for (const context of stateRecord.contexts) {
          if (!context || typeof context !== 'object') continue
          const contextRecord = context as { name?: unknown; variables?: unknown }
          this.contextManager.createContext(
            contextRecord.name as string,
            contextRecord.variables as Record<string, unknown>
          )
        }
      }
      return true
    } catch {
      return false
    }
  }
}

/**
 * 默认脚本引擎实例。
 * 预热保留为显式 warmup() API，模块导入本身不执行脚本或产生运行时副作用。
 */
export const defaultScriptEngine = new ScriptEngine()

import { describe, expect, it } from 'vitest'
import { ScriptEngine } from './script-engine'
import { ScriptTemplateManager } from './template-manager'
import {
  ALL_BUILT_IN_TEMPLATES,
  DATA_FETCHER_TEMPLATES as FACADE_DATA_FETCHER_TEMPLATES,
  DATA_MERGER_TEMPLATES as FACADE_DATA_MERGER_TEMPLATES,
  DATA_PROCESSOR_TEMPLATES as FACADE_DATA_PROCESSOR_TEMPLATES,
  UTILITY_TEMPLATES as FACADE_UTILITY_TEMPLATES
} from './templates/built-in-templates'
import { DATA_FETCHER_TEMPLATES } from './templates/data-fetcher-templates'
import { DATA_MERGER_TEMPLATES } from './templates/data-merger-templates'
import { DATA_PROCESSOR_TEMPLATES } from './templates/data-processor-templates'
import { UTILITY_TEMPLATES } from './templates/utility-templates'

describe('ScriptTemplateManager', () => {
  it('keeps template modules identical to facade exports and aggregation order', () => {
    expect(FACADE_DATA_FETCHER_TEMPLATES).toBe(DATA_FETCHER_TEMPLATES)
    expect(FACADE_DATA_PROCESSOR_TEMPLATES).toBe(DATA_PROCESSOR_TEMPLATES)
    expect(FACADE_DATA_MERGER_TEMPLATES).toBe(DATA_MERGER_TEMPLATES)
    expect(FACADE_UTILITY_TEMPLATES).toBe(UTILITY_TEMPLATES)
    expect([
      ...DATA_FETCHER_TEMPLATES,
      ...DATA_PROCESSOR_TEMPLATES,
      ...DATA_MERGER_TEMPLATES,
      ...UTILITY_TEMPLATES
    ]).toEqual(ALL_BUILT_IN_TEMPLATES)
  })

  it('starts empty so built-in templates have one explicit registry', () => {
    const manager = new ScriptTemplateManager()
    expect(manager.getAllTemplates()).toEqual([])
  })

  it('registers exactly the canonical built-in template set in ScriptEngine', () => {
    const engine = new ScriptEngine()
    const templates = engine.templateManager.getAllTemplates()

    expect(templates).toHaveLength(ALL_BUILT_IN_TEMPLATES.length)
    expect(templates.map(template => template.name)).toEqual(
      ALL_BUILT_IN_TEMPLATES.map(template => template.name)
    )
    expect(new Set(templates.map(template => template.name)).size).toBe(templates.length)
  })

  it('keeps HTTP integration behind the explicit audited network adapter contract', () => {
    const template = ALL_BUILT_IN_TEMPLATES.find(candidate => candidate.name === 'HTTP API 数据获取')

    expect(template).toBeDefined()
    expect(template?.code).toContain('_utils.networkUtils')
    expect(template?.code).not.toContain('fetch(')
    expect(template?.description).toContain('SCRIPT_NETWORK_EXTERNAL_BLOCKED')
    expect(template?.usageSnippet).toContain('SCRIPT_NETWORK_EXTERNAL_BLOCKED')
  })

  it('preserves parameter validation and interpolation for explicit templates', () => {
    const manager = new ScriptTemplateManager()
    const template = manager.createTemplate({
      name: 'threshold',
      description: 'threshold expression',
      category: 'validation',
      code: 'return value > {{threshold}} && source === {{source}}',
      parameters: [
        { name: 'threshold', type: 'number', required: true },
        { name: 'source', type: 'string', required: true }
      ],
      isSystem: false
    })

    expect(manager.generateCode(template.id, { threshold: 20, source: 'device-1' })).toBe(
      'return value > 20 && source === "device-1"'
    )
    expect(() => manager.generateCode(template.id, { source: 'device-1' })).toThrow('缺少必需参数: threshold')
  })

  it('does not delete canonical system templates', () => {
    const engine = new ScriptEngine()
    const systemTemplate = engine.templateManager.getAllTemplates()[0]

    expect(systemTemplate.isSystem).toBe(true)
    expect(engine.templateManager.deleteTemplate(systemTemplate.id)).toBe(false)
    expect(engine.templateManager.getTemplate(systemTemplate.id)).toBe(systemTemplate)
  })
})

/**
 * 文件用途：管理脚本模板的创建、更新、删除、查询和代码生成。
 * 核心逻辑：使用内存 Map 保存模板，并根据模板参数替换生成可执行脚本。
 * 关键注意事项：参数替换直接影响生成代码，必须保持默认值和必填校验一致。
 * 重构建议：可引入模板解析层和持久化适配器，支持更安全的参数插值与存储。
 */

import type {
  IScriptTemplateManager,
  ScriptTemplate,
  ScriptTemplateParameter,
  TemplateCategory
} from '@/core/script-engine/types'
import { nanoid } from 'nanoid'

/**
 * 脚本模板管理器实现类
 */
export class ScriptTemplateManager implements IScriptTemplateManager {
  private templates: Map<string, ScriptTemplate>

  constructor() {
    // 模板由统一 built-in registry 或调用方显式注册，避免维护两套重叠内置模板。
    this.templates = new Map()
  }

  /**
   * 获取所有模板
   */
  getAllTemplates(): ScriptTemplate[] {
    return Array.from(this.templates.values())
  }

  /**
   * 根据分类获取模板
   */
  getTemplatesByCategory(category: string): ScriptTemplate[] {
    return Array.from(this.templates.values()).filter(template => template.category === category)
  }

  /**
   * 获取指定模板
   */
  getTemplate(id: string): ScriptTemplate | null {
    return this.templates.get(id) || null
  }

  /**
   * 创建模板
   */
  createTemplate(template: Omit<ScriptTemplate, 'id' | 'createdAt' | 'updatedAt'>): ScriptTemplate {
    const now = Date.now()
    const newTemplate: ScriptTemplate = {
      ...template,
      id: nanoid(),
      createdAt: now,
      updatedAt: now
    }

    this.templates.set(newTemplate.id, newTemplate)
    return newTemplate
  }

  /**
   * 更新模板
   */
  updateTemplate(id: string, updates: Partial<ScriptTemplate>): boolean {
    const template = this.templates.get(id)
    if (!template) {
      return false
    }

    const updatedTemplate: ScriptTemplate = {
      ...template,
      ...updates,
      id, // 确保ID不被修改
      updatedAt: Date.now()
    }

    this.templates.set(id, updatedTemplate)
    return true
  }

  /**
   * 删除模板
   */
  deleteTemplate(id: string): boolean {
    const template = this.templates.get(id)
    if (!template || template.isSystem) {
      return false // 不能删除系统模板
    }

    return this.templates.delete(id)
  }

  /**
   * 根据模板生成代码
   */
  generateCode(templateId: string, parameters: Record<string, unknown>): string {
    const template = this.templates.get(templateId)
    if (!template) {
      throw new Error(`模板不存在: ${templateId}`)
    }

    let code = template.code

    // 替换模板参数
    template.parameters.forEach(param => {
      const value = parameters[param.name]
      const actualValue = value !== undefined ? value : param.defaultValue

      if (param.required && actualValue === undefined) {
        throw new Error(`缺少必需参数: ${param.name}`)
      }

      // 验证参数
      this.validateParameter(param, actualValue)

      // 替换代码中的占位符
      const placeholder = new RegExp(`\\{\\{${param.name}\\}\\}`, 'g')
      const replacement = this.formatParameterValue(actualValue, param.type)
      code = code.replace(placeholder, replacement)
    })

    return code
  }

  /**
   * 验证参数值
   */
  private validateParameter(param: ScriptTemplateParameter, value: unknown): void {
    if (value === undefined && !param.required) {
      return
    }

    // 类型检查
    switch (param.type) {
      case 'string':
        if (typeof value !== 'string') {
          throw new Error(`参数 ${param.name} 必须是字符串类型`)
        }
        break
      case 'number':
        if (typeof value !== 'number') {
          throw new Error(`参数 ${param.name} 必须是数字类型`)
        }
        break
      case 'boolean':
        if (typeof value !== 'boolean') {
          throw new Error(`参数 ${param.name} 必须是布尔类型`)
        }
        break
      case 'object':
        if (typeof value !== 'object' || value === null) {
          throw new Error(`参数 ${param.name} 必须是对象类型`)
        }
        break
      case 'array':
        if (!Array.isArray(value)) {
          throw new Error(`参数 ${param.name} 必须是数组类型`)
        }
        break
    }

    // 验证规则检查
    if (param.validation) {
      const validation = param.validation

      // 数值范围检查
      if (typeof value === 'number') {
        if (validation.min !== undefined && value < validation.min) {
          throw new Error(`参数 ${param.name} 不能小于 ${validation.min}`)
        }
        if (validation.max !== undefined && value > validation.max) {
          throw new Error(`参数 ${param.name} 不能大于 ${validation.max}`)
        }
      }

      // 字符串长度检查
      if (typeof value === 'string') {
        if (validation.min !== undefined && value.length < validation.min) {
          throw new Error(`参数 ${param.name} 长度不能小于 ${validation.min}`)
        }
        if (validation.max !== undefined && value.length > validation.max) {
          throw new Error(`参数 ${param.name} 长度不能大于 ${validation.max}`)
        }
        if (validation.pattern && !new RegExp(validation.pattern).test(value)) {
          throw new Error(`参数 ${param.name} 格式不正确`)
        }
      }

      // 枚举值检查
      if (validation.enum && !validation.enum.includes(value)) {
        throw new Error(`参数 ${param.name} 必须是以下值之一: ${validation.enum.join(', ')}`)
      }
    }
  }

  /**
   * 格式化参数值
   */
  private formatParameterValue(value: unknown, type: ScriptTemplateParameter['type']): string {
    switch (type) {
      case 'string':
        return JSON.stringify(value)
      case 'number':
      case 'boolean':
        return String(value)
      case 'object':
      case 'array':
        return JSON.stringify(value)
      case 'function':
        return typeof value === 'function' ? value.toString() : String(value)
      default:
        return JSON.stringify(value)
    }
  }
}

/**
 * 脚本引擎内置模板的聚合与注册 facade。
 *
 * 模板定义按场景拆分到独立模块；这里仅负责统一导出、固定顺序聚合、注册和初始化统计。
 */

import { TemplateCategory } from '@/core/script-engine/types'
import { DATA_FETCHER_TEMPLATES } from './data-fetcher-templates'
import { DATA_MERGER_TEMPLATES } from './data-merger-templates'
import { DATA_PROCESSOR_TEMPLATES } from './data-processor-templates'
import type { BuiltInTemplateDefinition } from './definition-types'
import { UTILITY_TEMPLATES } from './utility-templates'

export {
  DATA_FETCHER_TEMPLATES,
  DATA_PROCESSOR_TEMPLATES,
  DATA_MERGER_TEMPLATES,
  UTILITY_TEMPLATES
}

type BuiltInTemplateManager = {
  createTemplate: (template: BuiltInTemplateDefinition) => unknown
}

type BuiltInTemplateCategory =
  | TemplateCategory.DATA_GENERATION
  | TemplateCategory.DATA_PROCESSING
  | TemplateCategory.API_INTEGRATION
  | TemplateCategory.TIME_SERIES
  | TemplateCategory.TRANSFORMATION
  | TemplateCategory.VALIDATION
  | TemplateCategory.UTILITY

// 初始化统计只关心这几类内置模板，既用于校验，也用于汇总分类数量。
type BuiltInTemplateInitializationStats = {
  total: number
  success: number
  error: number
  categories: Record<BuiltInTemplateCategory, number>
}

// 模板分类白名单，保持与 ScriptTemplate.category 的枚举范围一致。
const BUILT_IN_TEMPLATE_CATEGORIES: BuiltInTemplateCategory[] = [
  TemplateCategory.DATA_GENERATION,
  TemplateCategory.DATA_PROCESSING,
  TemplateCategory.API_INTEGRATION,
  TemplateCategory.TIME_SERIES,
  TemplateCategory.TRANSFORMATION,
  TemplateCategory.VALIDATION,
  TemplateCategory.UTILITY
]

const BUILT_IN_TEMPLATE_CATEGORY_SET = new Set<BuiltInTemplateCategory>(BUILT_IN_TEMPLATE_CATEGORIES)

function createEmptyBuiltInTemplateCategoryStats(): Record<BuiltInTemplateCategory, number> {
  return {
    [TemplateCategory.DATA_GENERATION]: 0,
    [TemplateCategory.DATA_PROCESSING]: 0,
    [TemplateCategory.API_INTEGRATION]: 0,
    [TemplateCategory.TIME_SERIES]: 0,
    [TemplateCategory.TRANSFORMATION]: 0,
    [TemplateCategory.VALIDATION]: 0,
    [TemplateCategory.UTILITY]: 0
  }
}

function isBuiltInTemplateCategory(category: string): category is BuiltInTemplateCategory {
  return BUILT_IN_TEMPLATE_CATEGORY_SET.has(category as BuiltInTemplateCategory)
}

function collectBuiltInTemplateCategoryStats(
  templates: BuiltInTemplateDefinition[]
): Record<BuiltInTemplateCategory, number> {
  const stats = createEmptyBuiltInTemplateCategoryStats()

  for (const template of templates) {
    if (isBuiltInTemplateCategory(template.category)) {
      stats[template.category] += 1
    }
  }

  return stats
}

// 单个模板注册失败时只记失败，不打断其他模板的初始化。
function registerBuiltInTemplate(
  templateManager: BuiltInTemplateManager,
  template: BuiltInTemplateDefinition
): boolean {
  try {
    templateManager.createTemplate(template)
    return true
  } catch {
    return false
  }
}

// 聚合后的模板清单，供外部直接消费或做统一注册。
const BUILT_IN_TEMPLATE_GROUPS: BuiltInTemplateDefinition[][] = [
  DATA_FETCHER_TEMPLATES,
  DATA_PROCESSOR_TEMPLATES,
  DATA_MERGER_TEMPLATES,
  UTILITY_TEMPLATES
]

export const ALL_BUILT_IN_TEMPLATES: BuiltInTemplateDefinition[] = BUILT_IN_TEMPLATE_GROUPS.flat()

const BUILT_IN_TEMPLATE_CATEGORY_STATS = collectBuiltInTemplateCategoryStats(ALL_BUILT_IN_TEMPLATES)

/**
 * 将所有内置模板注册到模板管理器，并返回初始化统计。
 *
 * 这个函数只负责批量注册与统计，不负责模板生成，也不修改模板内容本身。
 */
export function initializeBuiltInTemplates(
  templateManager: BuiltInTemplateManager
): BuiltInTemplateInitializationStats {
  return ALL_BUILT_IN_TEMPLATES.reduce<BuiltInTemplateInitializationStats>(
    (summary, template) => {
      if (registerBuiltInTemplate(templateManager, template)) {
        summary.success += 1
      } else {
        summary.error += 1
      }

      return summary
    },

    // 返回统计信息
    {
      total: ALL_BUILT_IN_TEMPLATES.length,
      success: 0,
      error: 0,
      categories: { ...BUILT_IN_TEMPLATE_CATEGORY_STATS }
    }
  )
}

import type { BuiltInTemplateDefinition } from './definition-types'

/**
 * 数据获取类模板：用于生成设备数据、接口数据和其他输入片段。
 */
export const DATA_FETCHER_TEMPLATES: BuiltInTemplateDefinition[] = [
  {
    name: '模拟设备数据',
    description: '生成模拟的IoT设备数据，包含温度、湿度、状态等信息',
    category: 'data-generation',
    code: `// 生成模拟设备数据
const deviceId = context.deviceId || 'replace_with_device_id'
const timestamp = Date.now()

return {
  deviceId: deviceId,
  timestamp: timestamp,
  data: {
    temperature: Math.round((Math.random() * 40 + 10) * 100) / 100, // 10-50°C
    humidity: Math.round((Math.random() * 60 + 30) * 100) / 100,    // 30-90%
