import type { BuiltInTemplateDefinition } from './definition-types'

/**
 * 数据合并类模板：用于多源数据合并、去重和选择。
 */
export const DATA_MERGER_TEMPLATES: BuiltInTemplateDefinition[] = [
  {
    name: '设备遥测对象合并',
    description: '合并多路设备遥测对象，处理重复指标和数据类型差异',
    category: 'data-processing',
    code: `// 设备遥测对象合并
if (!Array.isArray(items) || items.length === 0) {
  return {}
}

const result = {}
const metadata = {
  sources: items.length,
  conflicts: [],
  dataTypes: {},
  mergedFields: []
}

items.forEach((item, index) => {
  if (!item || typeof item !== 'object') return

  Object.keys(item).forEach(key => {
    const value = item[key]

    // 记录数据类型
    const valueType = Array.isArray(value) ? 'array' : typeof value
    if (!metadata.dataTypes[key]) {
      metadata.dataTypes[key] = []
    }
    if (!metadata.dataTypes[key].includes(valueType)) {
      metadata.dataTypes[key].push(valueType)
    }

    if (result[key] === undefined) {
      // 首次赋值
      result[key] = value
      metadata.mergedFields.push(key)
    } else {
      // 处理冲突
      if (result[key] !== value) {
        metadata.conflicts.push({
          field: key,
          values: [result[key], value],
          sources: [\`telemetry_\${index-1}\`, \`telemetry_\${index}\`]
        })

        // 合并策略
        if (typeof result[key] === 'number' && typeof value === 'number') {
          // 数值求平均
          result[key] = (result[key] + value) / 2
        } else if (Array.isArray(result[key]) && Array.isArray(value)) {
          // 数组合并去重
          result[key] = [...new Set([...result[key], ...value])]
        } else if (typeof result[key] === 'string' && typeof value === 'string') {
          // 字符串拼接
          result[key] = \`\${result[key]}, \${value}\`
        } else {
          // 保持原值或使用最新值
          result[key] = value
        }
      }
    }
  })
})

return {
  ...result,
  _metadata: metadata,
  _mergeInfo: {
    timestamp: Date.now(),
    strategy: 'intelligent',
    itemsProcessed: items.length,
    fieldsCount: Object.keys(result).length - 2 // 排除元数据
  }
}`,
    parameters: [],
    usageSnippet: '// items = [{ device_id: "replace_with_device_id", temperature: 25 }, { device_id: "replace_with_device_id", humidity: 60 }]',
    isSystem: true
  },

  {
    name: '时序数据合并',
    description: '按时间戳合并多个时序数据数组',
    category: 'time-series',
    code: `// 时序数据合并
if (!Array.isArray(items) || items.length === 0) {
  return []
}

// 收集所有时序数据点
const allPoints = []
const sources = []

items.forEach((item, index) => {
  if (Array.isArray(item)) {
    // 直接是时序数组
    item.forEach(point => {
      if (point && typeof point.timestamp === 'number') {
        allPoints.push({
          ...point,
          sourceIndex: index,
          sourceName: \`telemetry_source_\${index}\`
        })
      }
    })
    sources.push(\`telemetry_array_\${index}\`)
  } else if (item && typeof item === 'object') {
    if (typeof item.timestamp === 'number') {
      // 单个时序点
      allPoints.push({
        ...item,
        sourceIndex: index,
        sourceName: \`telemetry_source_\${index}\`
      })
      sources.push(\`telemetry_point_\${index}\`)
    } else if (item.data && Array.isArray(item.data)) {
      // 包含data字段的对象
      item.data.forEach(point => {
        if (point && typeof point.timestamp === 'number') {
          allPoints.push({
            ...point,
            sourceIndex: index,
            sourceName: item.name || \`telemetry_source_\${index}\`
          })
        }
      })
      sources.push(item.name || \`telemetry_payload_\${index}\`)
    }
  }
})

// 按时间戳排序
allPoints.sort((a, b) => a.timestamp - b.timestamp)

// 合并相同时间戳的数据点
const merged = []
const timeGroups = {}

allPoints.forEach(point => {
  const timeKey = point.timestamp
  if (!timeGroups[timeKey]) {
    timeGroups[timeKey] = []
  }
  timeGroups[timeKey].push(point)
})

// 生成合并后的数据
Object.keys(timeGroups).forEach(timestamp => {
  const points = timeGroups[timestamp]
  const mergedPoint = {
    timestamp: parseInt(timestamp),
    values: {},
    sources: [],
    count: points.length
  }

  points.forEach(point => {
    mergedPoint.sources.push(point.sourceName)

    // 合并数值字段
    Object.keys(point).forEach(key => {
      if (key !== 'timestamp' && key !== 'sourceIndex' && key !== 'sourceName') {
        if (typeof point[key] === 'number') {
          if (!mergedPoint.values[key]) {
            mergedPoint.values[key] = []
          }
          mergedPoint.values[key].push(point[key])
        } else if (point[key] !== undefined) {
          mergedPoint[key] = point[key] // 保留非数值字段
        }
      }
    })
  })

  // 计算数值字段的统计值
  Object.keys(mergedPoint.values).forEach(key => {
    const values = mergedPoint.values[key]
    mergedPoint.values[key] = {
      raw: values,
      avg: values.reduce((sum, v) => sum + v, 0) / values.length,
      min: Math.min(...values),
      max: Math.max(...values),
      sum: values.reduce((sum, v) => sum + v, 0)
    }
  })

  merged.push(mergedPoint)
})

return merged`,
    parameters: [],
    usageSnippet: '// items = [temperatureRows, humidityRows] where rows contain {deviceId, timestamp, value}',
    isSystem: true
  },

  {
    name: '最佳遥测点选择',
    description: '按时间、数值或质量从多路遥测中选择最可信的数据点',
    category: 'data-processing',
    code: `// 最佳遥测点选择
if (!Array.isArray(items) || items.length === 0) {
  return null
}

const criteria = context?.criteria || 'latest' // latest, highest, lowest, quality
const valueField = context?.valueField || 'temperature'
const timestampField = context?.timestampField || 'timestamp'
const qualityField = context?.qualityField || 'quality'

let selected = null
let reason = ''

switch (criteria) {
  case 'latest':
    // 选择时间戳最新的遥测点
    selected = items.reduce((latest, item) => {
      if (!latest) return item
      const itemTime = item[timestampField] || 0
      const latestTime = latest[timestampField] || 0
      return itemTime > latestTime ? item : latest
    }, null)
    reason = '选择最新上报的遥测点'
    break

  case 'highest':
    // 选择数值最高的遥测点
    selected = items.reduce((highest, item) => {
      if (!highest) return item
      const itemValue = item[valueField] || 0
      const highestValue = highest[valueField] || 0
      return itemValue > highestValue ? item : highest
    }, null)
    reason = \`选择\${valueField}指标值最高的遥测点\`
    break

  case 'lowest':
    // 选择数值最低的遥测点
    selected = items.reduce((lowest, item) => {
      if (!lowest) return item
      const itemValue = item[valueField] || Number.MAX_VALUE
      const lowestValue = lowest[valueField] || Number.MAX_VALUE
      return itemValue < lowestValue ? item : lowest
    }, null)
    reason = \`选择\${valueField}指标值最低的遥测点\`
    break

  case 'quality':
    // 选择质量最好的遥测点
    const qualityOrder = ['excellent', 'good', 'fair', 'poor']
    selected = items.reduce((best, item) => {
      if (!best) return item
      const itemQuality = item[qualityField] || 'poor'
      const bestQuality = best[qualityField] || 'poor'
      const itemIndex = qualityOrder.indexOf(itemQuality)
      const bestIndex = qualityOrder.indexOf(bestQuality)
      return (itemIndex !== -1 && (bestIndex === -1 || itemIndex < bestIndex)) ? item : best
    }, null)
    reason = \`选择\${qualityField}质量最好的遥测点\`
    break

  default:
    selected = items[0]
    reason = '使用默认选择（第一条遥测点）'
}

// 添加选择信息
return {
  ...selected,
  _selectionInfo: {
    criteria: criteria,
    reason: reason,
    totalItems: items.length,
    selectedIndex: items.indexOf(selected),
    timestamp: Date.now(),
    alternatives: items.length - 1
  }
}`,
    parameters: [
      {
        name: 'criteria',
        type: 'string',
        description: '选择条件',
        required: false,
        defaultValue: 'latest',
        validation: {
          enum: ['latest', 'highest', 'lowest', 'quality']
        }
      },
      {
        name: 'valueField',
        type: 'string',
        description: '比较的数值字段',
        required: false,
        defaultValue: 'temperature'
      }
    ],
    usageSnippet: '// context = { criteria: "highest", valueField: "temperature" }',
    isSystem: true
  }
]

/**
 * 文件用途：定义脚本引擎的执行结果、配置、模板、沙箱和上下文类型。
 * 核心逻辑：集中声明跨执行器、沙箱、模板管理器和上下文管理器共享的 TypeScript 契约。
 * 关键注意事项：这里的类型会影响多个核心模块，字段变更需要同步实现与测试。
 * 重构建议：可按执行、模板、沙箱、上下文拆分类型文件，再由入口统一导出。
 */

// 脚本执行结果
export interface ScriptExecutionResult<T = unknown> {
  /** 执行是否成功 */
  success: boolean
  /** 执行结果数据 */
  data?: T
  /** 错误信息 */
  error?: Error
  /** 执行时间（毫秒） */
  executionTime: number
  /** 执行上下文快照 */
  contextSnapshot?: Record<string, unknown>
  /** 日志输出 */
  logs: ScriptLog[]
}

// 脚本日志
export interface ScriptLog {
  level: 'log' | 'warn' | 'error' | 'info' | 'debug'
  message: string
  timestamp: number
  args?: unknown[]
}

// 脚本配置
export interface ScriptConfig {
  /** 脚本代码 */
  code: string
  /** 执行超时时间（毫秒） */
  timeout?: number
  /** 兼容字段：本地执行始终使用严格模式，不能通过此字段关闭 */
  strictMode?: boolean
  /** 兼容字段：本地执行固定使用异步函数包装 */
  asyncSupport?: boolean
  /** 保留契约：同线程沙箱无法可靠施加内存上限（字节） */
  maxMemory?: number
  /** 自定义全局变量 */
  globals?: Record<string, unknown>
  /** 保留契约：网络仍需可取消、可审计的宿主适配器，布尔值不会直接放行 */
  allowNetworkAccess?: boolean
  /** 保留契约：浏览器本地执行不提供文件系统访问 */
  allowFileSystemAccess?: boolean
}

/**
 * 脚本函数契约。
 * 参数使用 never 以保持逆变安全：任何具体签名的函数都可赋值，
 * 但引擎本身不直接调用这些函数（它们由用户脚本在沙箱内动态调用）。
 */
export type ScriptFunction = (...args: never[]) => unknown

// 脚本执行上下文
export interface ScriptExecutionContext {
  /** 上下文ID */
  id: string
  /** 上下文名称 */
  name: string
  /** 上下文变量 */
  variables: Record<string, unknown>
  /** 内置函数 */
  functions: Record<string, ScriptFunction>
  /** 上下文创建时间 */
  createdAt: number
  /** 上下文最后更新时间 */
  updatedAt: number
}

// 脚本模板
export interface ScriptTemplate {
  /** 模板ID */
  id: string
  /** 模板名称 */
  name: string
  /** 模板描述 */
  description?: string
  /** 模板分类 */
  category: string
  /** 模板代码 */
  code: string
  /** 模板参数 */
  parameters: ScriptTemplateParameter[]
  /** 使用片段 */
  usageSnippet?: string
  /** 是否为系统模板 */
  isSystem?: boolean
  /** 创建时间 */
  createdAt: number
  /** 更新时间 */
  updatedAt: number
}

// 脚本模板参数
export interface ScriptTemplateParameter {
  /** 参数名称 */
  name: string
  /** 参数类型 */
  type: 'string' | 'number' | 'boolean' | 'object' | 'array' | 'function'
  /** 参数描述 */
  description?: string
  /** 是否必需 */
  required: boolean
  /** 默认值 */
  defaultValue?: unknown
  /** 参数验证规则 */
  validation?: {
    min?: number
    max?: number
    pattern?: string
    enum?: unknown[]
  }
}

// 沙箱配置
export interface SandboxConfig {
  /** 兼容字段：本地硬安全策略始终启用，false 不会关闭防护 */
  enabled: boolean
  /** 允许暴露的安全全局对象；网络能力仍由专用适配器控制 */
  allowedGlobals: string[]
  /** 兼容字段：本地硬阻断集合不会因移除此列表项而放宽 */
  blockedGlobals: string[]
  /** 兼容字段：eval 始终阻断，true 不会放行 */
  allowEval: boolean
  /** 兼容字段：Function 构造器始终阻断，true 不会放行 */
  allowFunction: boolean
  /** 兼容字段：原型与构造器访问始终阻断，true 不会放行 */
  allowPrototypePollution: boolean
  /** 自定义安全策略 */
  customSecurityPolicy?: (code: string) => boolean
}

// 脚本引擎配置
export interface ScriptEngineConfig {
  /** 默认脚本配置 */
  defaultScriptConfig: ScriptConfig
  /** 沙箱配置 */
  sandboxConfig: SandboxConfig
  /** 保留契约：当前本地执行器不提供结果缓存 */
  enableCache: boolean
  /** 保留契约：仅在未来启用结果缓存后生效（毫秒） */
  cacheTTL: number
  /** 保留契约：当前调用由宿主调度，执行器不实现并发队列 */
  maxConcurrentExecutions: number
  /** 保留契约：当前仅始终收集基础执行统计 */
  enablePerformanceMonitoring: boolean
}

/**
 * 沙箱内部定时器记录
 */
export interface ScriptSandboxTimerRecord {
  type: 'timeout' | 'interval'
  id: ReturnType<typeof setTimeout> | ReturnType<typeof setInterval>
}

/**
 * 脚本沙箱实例。
 * `with` 作用域使用的自由键值对象；`_timers`/`_utils` 由宿主维护，其余键由脚本自由读写。
 */
export type ScriptSandboxInstance = Record<string, unknown> & {
  _timers?: ScriptSandboxTimerRecord[]
}

// 脚本执行器接口
export interface IScriptExecutor {
  /** 执行脚本 */
  execute<T = unknown>(config: ScriptConfig, context?: ScriptExecutionContext): Promise<ScriptExecutionResult<T>>
  /** 验证脚本语法 */
  validateSyntax(code: string): { valid: boolean; error?: string }
  /** 获取执行统计 */
  getExecutionStats(): ExecutionStats
}

// 脚本沙箱接口
export interface IScriptSandbox {
  /** 创建沙箱环境 */
  createSandbox(config: SandboxConfig): ScriptSandboxInstance
  /** 执行沙箱代码 */
  executeInSandbox(code: string, sandbox: ScriptSandboxInstance, timeout?: number): Promise<unknown>
  /** 销毁沙箱 */
  destroySandbox(sandbox: ScriptSandboxInstance): void
  /** 检查代码安全性 */
  checkCodeSecurity(code: string): { safe: boolean; issues: string[] }
}

// 脚本模板管理器接口
export interface IScriptTemplateManager {
  /** 获取所有模板 */
  getAllTemplates(): ScriptTemplate[]
  /** 根据分类获取模板 */
  getTemplatesByCategory(category: string): ScriptTemplate[]
  /** 获取指定模板 */
  getTemplate(id: string): ScriptTemplate | null
  /** 创建模板 */
  createTemplate(template: Omit<ScriptTemplate, 'id' | 'createdAt' | 'updatedAt'>): ScriptTemplate
  /** 更新模板 */
  updateTemplate(id: string, updates: Partial<ScriptTemplate>): boolean
  /** 删除模板 */
  deleteTemplate(id: string): boolean
  /** 根据模板生成代码 */
  generateCode(templateId: string, parameters: Record<string, unknown>): string
}

// 上下文管理器接口
export interface IScriptContextManager {
  /** 创建执行上下文 */
  createContext(name: string, variables?: Record<string, unknown>): ScriptExecutionContext
  /** 获取上下文 */
  getContext(id: string): ScriptExecutionContext | null
  /** 更新上下文 */
  updateContext(id: string, updates: Partial<ScriptExecutionContext>): boolean
  /** 删除上下文 */
  deleteContext(id: string): boolean
  /** 克隆上下文 */
  cloneContext(id: string, newName: string): ScriptExecutionContext | null
  /** 合并上下文 */
  mergeContexts(sourceId: string, targetId: string): boolean
}

// 脚本引擎主接口
export interface IScriptEngine {
  /** 脚本执行器 */
  executor: IScriptExecutor
  /** 脚本沙箱 */
  sandbox: IScriptSandbox
  /** 模板管理器 */
  templateManager: IScriptTemplateManager
  /** 上下文管理器 */
  contextManager: IScriptContextManager

  /** 快速执行脚本 */
  execute<T = unknown>(code: string, context?: Record<string, unknown>): Promise<ScriptExecutionResult<T>>
  /** 使用模板执行 */
  executeTemplate<T = unknown>(templateId: string, parameters: Record<string, unknown>): Promise<ScriptExecutionResult<T>>
  /** 获取引擎配置 */
  getConfig(): ScriptEngineConfig
  /** 更新引擎配置 */
  updateConfig(config: Partial<ScriptEngineConfig>): void
}

// 执行统计
export interface ExecutionStats {
  /** 总执行次数 */
  totalExecutions: number
  /** 成功执行次数 */
  successfulExecutions: number
  /** 失败执行次数 */
  failedExecutions: number
  /** 平均执行时间（毫秒） */
  averageExecutionTime: number
  /** 最长执行时间（毫秒） */
  maxExecutionTime: number
  /** 最短执行时间（毫秒） */
    minExecutionTime: number
  /** 当前并发执行数 */
  currentConcurrentExecutions: number
}

// 引擎统计快照
export interface ScriptEngineStatsSnapshot {
  executor: ExecutionStats
  templates: {
    total: number
    byCategory: Record<string, number>
  }
  contexts: {
    total: number
    active: number
  }
}

// 引擎状态导出快照
export interface ScriptEngineStateSnapshot {
  config: ScriptEngineConfig
  stats: ScriptEngineStatsSnapshot
  templates: ScriptTemplate[]
  contexts: ScriptExecutionContext[]
  timestamp: string
}

// 内置工具函数类型
export interface BuiltinUtilities {
  /** 数据生成工具 */
  mockData: {
    randomNumber: (min?: number, max?: number) => number
    randomString: (length?: number) => string
    randomBoolean: () => boolean
    randomDate: (start?: Date, end?: Date) => Date
    randomArray: <T>(items: T[], count?: number) => T[]
    randomObject: (template: Record<string, unknown>) => Record<string, unknown>
  }

  /** 数据处理工具 */
  dataUtils: {
    deepClone: <T>(obj: T) => T
    merge: (...objects: unknown[]) => Record<string, unknown>
    pick: <T extends Record<string, unknown>>(obj: T, keys: (keyof T)[]) => Partial<T>
    omit: <T extends Record<string, unknown>>(obj: T, keys: (keyof T)[]) => Partial<T>
    groupBy: <T>(array: T[], key: keyof T | ((item: T) => unknown)) => Record<string, T[]>
    sortBy: <T>(array: T[], key: keyof T | ((item: T) => unknown)) => T[]
  }

  /** 时间工具 */
  timeUtils: {
    now: () => number
    format: (date: Date | number, format: string) => string
    addDays: (date: Date, days: number) => Date
    diffDays: (date1: Date, date2: Date) => number
    startOfDay: (date: Date) => Date
    endOfDay: (date: Date) => Date
  }

  /** 网络工具 */
  networkUtils: {
    httpGet: (url: string, options?: RequestInit) => Promise<unknown>
    httpPost: (url: string, data: unknown, options?: RequestInit) => Promise<unknown>
    httpPut: (url: string, data: unknown, options?: RequestInit) => Promise<unknown>
    httpDelete: (url: string, options?: RequestInit) => Promise<unknown>
  }

  /** 日志工具 */
  logger: {
    log: (...args: unknown[]) => void
    warn: (...args: unknown[]) => void
    error: (...args: unknown[]) => void
    info: (...args: unknown[]) => void
    debug: (...args: unknown[]) => void
  }
}

